window.__Q=window.__Q||{};window.__Q["prev/7/A1"]=[{"q":"格列本脲降血糖作用的主要机制是","o":["增强胰岛素的作用","促进葡萄糖分解","刺激胰岛β细胞释放胰岛素","使细胞内cAMP减少","抑制胰高血糖素作用"],"a":2,"e":"格列本脲属磺酰脲类，阻断胰岛β细胞膜ATP敏感性钾通道，促钙内流而刺激胰岛素释放，降糖作用依赖尚存功能的β细胞，适用于2型糖尿病。"},{"q":"使用氢氯噻嗪时加用螺内酯的主要目的是","o":["增强利尿作用","对抗氢氯噻嗪所致的低血钾","延长氢氯噻嗪的作用时间","对抗氢氯噻嗪的升血糖作用","对抗氢氯噻嗪升高血尿酸的作用"],"a":1,"e":"氢氯噻嗪长期排钾可致低血钾，螺内酯为醛固酮受体拮抗药，保钾排钠，二者合用可纠正低血钾并增强利尿，防止低钾诱发心律失常。"},{"q":"大多数脂溶性药物跨膜转运的方式是","o":["被动转运","膜孔滤过","易化扩散","胞吞","主动转运"],"a":0,"e":"脂溶性药物可顺浓度梯度直接溶于细胞膜脂质双层而跨膜，不耗能、无载体、无饱和现象，属被动转运，其速度取决于膜两侧浓度差与药物脂溶性。"},{"q":"酚妥拉明对间羟胺升压作用的影响是","o":["升压作用增强","升压作用减弱","产生升压翻转效应","升压作用不变","先升压再降压"],"a":1,"e":"间羟胺主要激动α1受体收缩血管升压，酚妥拉明阻断α受体后其升压作用明显减弱；因间羟胺几无β2效应，故不出现肾上腺素的升压翻转。"},{"q":"多黏菌素B的主要不良反应是","o":["肾损害","肝损害","耳毒性","消化道反应","过敏反应"],"a":0,"e":"多黏菌素B经肾排泄并在肾小管上皮蓄积，肾损害最常见且与剂量相关，可致蛋白尿、血尿乃至急性肾小管坏死，此外尚有神经毒性。"},{"q":"苯二氮卓类的药理作用机制是","o":["阻断谷氨酸的兴奋作用","抑制GABA代谢增加其脑内含量","激动甘氨酸受体","易化GABA介导的氯离子内流","增加多巴胺刺激的cAMP活性"],"a":3,"e":"苯二氮䓬类与GABA-A受体复合物上的苯二氮䓬位点结合，增强GABA与受体亲和力，易化氯通道开放使氯离子内流增加，产生中枢抑制。"},{"q":"氨甲苯酸的作用是","o":["增加血小板聚集","促进肝脏合成凝血酶原","促使毛细血管收缩","激活纤溶酶原","对抗纤溶酶原激活因子"],"a":4,"e":"氨甲苯酸属抗纤溶药，竞争性抑制纤溶酶原激活因子，阻止纤溶酶原转变为纤溶酶，保护纤维蛋白不被降解而止血，用于纤溶亢进所致出血。"},{"q":"下列药物中，几乎无抗炎作用的是","o":["阿司匹林","对乙酰氨基酚","吲哚美辛","双氯芬酸","布洛芬"],"a":1,"e":"对乙酰氨基酚抑制中枢前列腺素合成而解热镇痛，对外周环氧酶作用弱，几乎无抗炎抗风湿作用，也不影响血小板功能。"},{"q":"强心苷对下列哪些疾病诱发的心衰疗效较好","o":["瓣膜病、高血压、先天性心脏病","贫血、甲亢、维生素B6缺乏症","肺源性心脏病、心肌损伤、活动性心肌炎","严重二尖瓣狭窄和缩窄性心包炎","伴传导阻滞的心功能不全"],"a":0,"e":"强心苷对心室负荷加重、心肌收缩功能尚可的代偿性心衰疗效好，故瓣膜病、高血压、先天性心脏病所致者效果佳；贫血、甲亢因高动力循环而疗效差。"},{"q":"以下哪种细胞是环孢素的主要抑制靶点","o":["巨噬细胞","树突状细胞","自然杀伤细胞","T细胞","B细胞"],"a":3,"e":"环孢素主要选择性抑制辅助性T细胞，阻碍白细胞介素-2等细胞因子基因转录，使T细胞增殖分化受阻，对巨噬细胞及B细胞影响小。"},{"q":"治疗呆小病的药物是","o":["甲巯咪唑","小剂量碘","甲状腺素","丙硫氧嘧啶","卡比马唑"],"a":2,"e":"呆小病系甲状腺功能减退致生长发育与智力障碍，须终身补充甲状腺素替代治疗，宜尽早开始以减轻智力损害。"},{"q":"应用奎尼丁治疗心房纤颤合用强心苷的目的是","o":["拮抗奎尼丁引起的血管扩张","对抗奎尼丁引起的心脏抑制","提高奎尼丁的血药浓度","增强奎尼丁的抗心律失常作用","抑制房室结传导，减慢心室率"],"a":4,"e":"奎尼丁抑制房室结传导作用弱，单用于房颤时心房率减慢后经房室结下传增多，心室率反而加快，合用强心苷抑制房室结传导以控制心室率。"},{"q":"去甲肾上腺素禁止肌肉或皮下注射给药，原因是","o":["易致心律失常","升压过强","无效","吸收慢，出现作用慢","强烈收缩局部血管，引起局部组织缺血坏死"],"a":4,"e":"去甲肾上腺素强烈收缩局部血管，肌注或皮下注射可致注射部位组织缺血坏死，故只能静脉滴注并防止药液外漏。"},{"q":"下列哪种药物属于选择性环氧酶-2抑制药","o":["保泰松","阿司匹林","尼美舒利","舒林酸","双氯芬酸"],"a":2,"e":"尼美舒利属选择性环氧酶-2抑制药，治疗量对环氧酶-1影响小，胃肠及肾不良反应较轻；保泰松、阿司匹林、舒林酸、双氯芬酸均为非选择性。"},{"q":"药物肝肠循环影响了药物在体内的","o":["起效快慢","消除快慢","分布速度","给药途径","与血浆蛋白结合"],"a":1,"e":"药物经胆汁排入肠腔后被重吸收再入肝，形成肝肠循环，使药物在体内滞留时间延长，消除减慢、作用时间延长，如洋地黄毒苷。"},{"q":"用白酒送服2瓶地西泮（2.5mg×100片/瓶），以下可以作为解救药物的是","o":["伊马替尼","氟马西尼","索拉非尼","舒芬太尼","布美他尼"],"a":1,"e":"氟马西尼为苯二氮䓬受体特异性拮抗药，可迅速逆转地西泮引起的中枢及呼吸抑制，是其中毒解救药；伊马替尼、索拉非尼为酪氨酸激酶抑制药。"},{"q":"抗菌谱是","o":["抗菌药物的治疗指数","抗菌药物的抗菌范围","抗菌药物的抗菌能力","抗菌药物的治疗效果","抗菌药物的适应证"],"a":1,"e":"抗菌谱指抗菌药物抑制或杀灭病原微生物的范围，其广窄是临床选药的重要依据；治疗指数反映药物安全性，二者概念不同。"},{"q":"以下哪种药物为α-葡萄糖苷酶抑制剂","o":["甲苯磺丁脲","甲巯咪唑","格列本脲","瑞格列奈","阿卡波糖"],"a":4,"e":"阿卡波糖在小肠竞争性抑制α-葡萄糖苷酶，延缓淀粉及双糖分解为葡萄糖，降低餐后血糖，为α-葡萄糖苷酶抑制药。"},{"q":"阿托品抑制腺体分泌作用最弱的是","o":["汗腺分泌","唾液腺分泌","胃酸分泌","呼吸道腺体分泌","泪腺分泌"],"a":2,"e":"阿托品阻断M受体，对腺体分泌的影响以唾液腺、汗腺最敏感，泪腺、呼吸道腺体次之，对胃酸分泌抑制作用最弱，因胃酸分泌尚有胃泌素等非胆碱机制。"},{"q":"治疗窦性心动过速首选的药物是","o":["奎尼丁","普萘洛尔","氟卡尼","苯妥英钠","利多卡因"],"a":1,"e":"窦性心动过速多与交感张力增高有关，普萘洛尔阻断β1受体减慢窦房结舒张期除极，为首选；奎尼丁具抗胆碱作用反可加快心率。"},{"q":"下列可削弱硝酸酯类的抗心绞痛作用的是","o":["室壁张力降低","心室容积缩小","心室压力降低","心脏体积缩小","心率加快"],"a":4,"e":"硝酸酯类扩张静脉减少回心血量、降低前负荷而减少心肌耗氧；心率加快使耗氧增加、舒张期缩短冠脉灌注减少，从而削弱其抗心绞痛疗效。"},{"q":"用于治疗立克次体引起斑疹伤寒的首选药物是","o":["磺胺嘧啶","红霉素","四环素","氧氟沙星","青霉素G"],"a":2,"e":"四环素对立克次体有较强抑制作用，为斑疹伤寒、恙虫病等立克次体感染的首选药；磺胺类反可促进立克次体繁殖。"},{"q":"为使口服药物加速达到有效血浆浓度，缩短到达坪值时间，并维持体内药量在D～2D之间，应采取如下给药方案","o":["首剂给2D，维持量为2D/2t1/2","首剂给3D，维持量为D/t1/2","首剂给2D，维持量为2D/t1/2","首剂给3D，维持量为D/2t1/2","首剂给2D，维持量为D/t1/2"],"a":4,"e":"为迅速达稳态可先给负荷量，按一级动力学蓄积规律首剂加倍即2D，随后按D/t1/2给维持量，可使体内药量维持在D至2D之间。"},{"q":"下列药物中，不属于一氧化氮供体的是","o":["硝普钠","硝酸甘油","西地那非","硝苯地平","戊四硝酯"],"a":3,"e":"硝苯地平为二氢吡啶类钙通道阻滞药，阻断L型钙通道舒张血管，本身不释放一氧化氮；硝普钠、硝酸甘油、戊四硝酯均属NO供体。"},{"q":"长期应用苯妥英钠可导致双香豆素","o":["作用增强","作用减弱","作用加快","作用时间延长","吸收增加"],"a":1,"e":"苯妥英钠为肝药酶诱导剂，长期应用加速双香豆素代谢，使其抗凝作用减弱，合用时需增加双香豆素剂量并监测凝血功能。"},{"q":"长期大量应用易导致人体叶酸缺乏的药物是","o":["TMP","红霉素","四环素","链霉素","青霉素G"],"a":0,"e":"甲氧苄啶抑制细菌二氢叶酸还原酶，使二氢叶酸不能还原为四氢叶酸；长期大量应用可干扰人体叶酸代谢，致巨幼细胞贫血。"},{"q":"药效学主要研究","o":["药物的跨膜转运","药物的生物转化","药物的时量关系","药物对机体作用","血药浓度的昼夜节律"],"a":3,"e":"药效学研究药物对机体的作用、作用机制及量效关系，属药物效应动力学；跨膜转运、生物转化与血药浓度变化则属药动学范畴。"},{"q":"应用地高辛治疗心房纤颤，减慢心室率主要作用是","o":["抑制房室结传导","加速房室结传导","抑制浦肯野纤维传导","加速浦肯野纤维传导","抑制窦房结传导"],"a":0,"e":"地高辛兴奋迷走神经并抑制房室结传导，延长房室结有效不应期，使房颤时过多冲动不能下传心室，从而减慢心室率。"},{"q":"下列属于药物基本作用的是","o":["治疗与不良反应","治疗与预防作用","对因治疗和对症治疗","兴奋和抑制作用","局部与吸收作用"],"a":3,"e":"药物对机体先产生兴奋或抑制两种基本反应，二者可相互转化；治疗作用与不良反应是按用药目的划分的效应分类，非基本作用形式。"},{"q":"阿司匹林预防血栓形成的机制是","o":["抑制TXA2合成","促进PGI2合成","促进TXA2合成","抑制PGI2合成","抑制凝血酶原"],"a":0,"e":"阿司匹林不可逆抑制血小板环氧酶-1，减少血栓素A2生成而抑制血小板聚集，小剂量长期用于预防血栓形成，对血管内皮前列环素影响较小。"},{"q":"为预防长期大量服用阿司匹林引起出血，应选用下列哪个药物","o":["维生素C","维生素K","维生素B1","维生素A","维生素E"],"a":1,"e":"阿司匹林抑制血小板聚集并干扰凝血酶原合成，长期大量应用可致出血，维生素K促进凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成，可用于防治。"},{"q":"激动M受体不会引起","o":["支气管平滑肌收缩","骨骼肌收缩","胃肠道平滑肌收缩","膀胱逼尿肌收缩","睫状肌收缩"],"a":1,"e":"M受体激动使支气管、胃肠及膀胱逼尿肌收缩、睫状肌收缩；骨骼肌收缩由神经肌肉接头N2受体介导，与M受体无关。"},{"q":"巴比妥类药物中毒时，静脉滴注碳酸氢钠是有效的解毒措施，其基本原因是","o":["减少巴比妥类药物从胃吸收","加速巴比妥类药物在体内破坏","对抗巴比妥类药物在中枢抑制","减少脑细胞中药物含量，加快从肾脏排泄","切断了巴比妥类药物的肠肝循环"],"a":3,"e":"碳酸氢钠碱化血液使巴比妥类解离增多、脂溶性下降，向脑组织分布减少，同时碱化尿液减少肾小管重吸收而加速排泄。"},{"q":"药物激动或阻断相应受体，取决于","o":["药物的化学结构","药物的剂量大小","药物内在活性的大小","药物与受体的亲和力强弱","药物的剂型"],"a":2,"e":"药物与受体结合后能否激动受体取决于有无内在活性，有内在活性者产生效应为激动药，缺乏者为拮抗药，亲和力只决定结合强度。"},{"q":"肼屈嗪降压作用方式是","o":["直接扩张小动脉","阻断外周α受体","耗竭肾上腺素能神经末梢的NA","抑制肾素释放","阻断中枢α受体"],"a":0,"e":"肼屈嗪直接舒张小动脉平滑肌，降低外周阻力而降压，对静脉影响小；阻断α受体者为哌唑嗪，耗竭神经末梢递质者为利血平。"},{"q":"普萘洛尔抗心绞痛的原理是","o":["延长射血时间","降低心肌耗氧量","增加前负荷","扩张动脉增加心肌供氧","降低外周阻力"],"a":1,"e":"普萘洛尔阻断β受体，减慢心率、减弱心肌收缩力，使心肌耗氧量下降而缓解心绞痛，但不宜用于变异型心绞痛。"},{"q":"明朝时期编著，收载药物1890余种，被译成英、日、朝等七种文本的中国古典药物学巨著是","o":["《本草纲目》","《神农本草经》","《新修本草》","《黄帝内经》","《伤寒论》"],"a":0,"e":"《本草纲目》为明代李时珍所著，载药1892种，附方万余首，已被译成多国文字，是十六世纪以前中国药物学的总结性巨著。"},{"q":"与口服给药相比，直肠给药的最主要优点是","o":["适用于昏迷、抽搐等不能口服","在一定程度上避免首过消除","吸收缓慢","适用于对胃刺激引起呕吐的药物","作用持久"],"a":1,"e":"直肠下段静脉血经直肠下静脉回流至下腔静脉，不经门静脉入肝，故直肠给药可在一定程度上避免首过消除，提高生物利用度。"},{"q":"下列疾病最适宜选用选择性M1受体阻断药治疗的是","o":["膀胱过度活动症","消化性溃疡","青光眼","支气管哮喘","妊娠呕吐"],"a":1,"e":"哌仑西平选择性阻断胃壁细胞M1受体，抑制胃酸分泌，用于消化性溃疡；膀胱过度活动症用M3阻断药，青光眼则禁用抗胆碱药。"},{"q":"脑内的胆碱受体以何种受体为主","o":["M1","M2","M3","M4","N"],"a":0,"e":"中枢胆碱受体以M1型为主，广泛分布于大脑皮层与海马，参与觉醒、学习记忆与运动调节；M2多为突触前自身受体。"},{"q":"维拉帕米不能用于治疗","o":["心绞痛","慢性心功能不全","高血压","室上性心动过速","心房纤颤"],"a":1,"e":"维拉帕米抑制心肌细胞钙内流，负性肌力作用明显，可加重心功能不全，故慢性心功能不全者不用；对心绞痛、高血压、室上性心动过速有效。"},{"q":"长期应用糖皮质激素可引起","o":["高血钙","高血钾","高血镁","高血磷","低血钾"],"a":4,"e":"糖皮质激素有弱盐皮质激素样作用，促进肾小管保钠排钾，长期应用可致低血钾、水钠潴留和高血压，并使血钙降低、骨质疏松。"},{"q":"以下哪种类型的癫痫发作又称为癫痫小发作","o":["单纯性局限性发作","复合性局限性发作","失神性发作","肌阵挛性发作","强直-阵挛性发作"],"a":2,"e":"失神性发作即癫痫小发作，表现为短暂意识丧失、脑电图为3Hz棘慢波，多见于儿童，首选乙琥胺；单纯局限性发作属部分性发作。"},{"q":"属于抗雄激素类药物的是","o":["黄体酮","己烯雌酚","氯米芬","米非司酮","环丙孕酮"],"a":4,"e":"环丙孕酮为合成孕激素，竞争性阻断雄激素受体并抑制促性腺激素分泌，属抗雄激素药，用于前列腺癌、痤疮及女性多毛症。"},{"q":"青霉素G不宜口服的原因是","o":["脂溶性低","易被胃酸及消化酶破坏，吸收少且不规则","口服后达峰时间长","主要分布于细胞外液","几乎全部以原形经尿排泄"],"a":1,"e":"青霉素G不耐酸，口服后被胃酸及消化酶破坏，且吸收少而不规则、血药浓度低，故须注射给药；耐酸者可口服如青霉素V。"},{"q":"普萘洛尔抗心律失常作用机制不包括","o":["阻断心脏β受体","降低窦房结、浦肯野纤维自律性","减少儿茶酚胺所致的迟后除极","减慢房室结传导，延长其有效不应期","开放乙酰胆碱敏感性钾通道"],"a":4,"e":"普萘洛尔阻断心脏β1受体，降低窦房结及浦肯野纤维自律性、减慢房室结传导并延长其有效不应期；开放乙酰胆碱敏感性钾通道是腺苷的作用。"},{"q":"卵巢功能不全和闭经宜选用的药物是","o":["黄体酮","甲基睾丸酮","氯米芬","己烯雌酚","双醋炔诺醇"],"a":3,"e":"卵巢功能不全及闭经宜用雌激素替代，己烯雌酚为合成雌激素，可促进生殖器官发育、维持第二性征并形成人工月经周期。"},{"q":"对抗局麻药中毒引起的惊厥，首选的药物是","o":["地西泮","苯妥英钠","硫喷妥钠","苯巴比妥","水合氯醛"],"a":0,"e":"局麻药吸收过量先兴奋后抑制中枢，出现惊厥时首选地西泮静脉注射，可迅速控制惊厥且对呼吸循环抑制轻。"},{"q":"卡托普利发挥降压作用主要是通过","o":["直接舒张血管平滑肌","兴奋中枢α受体","阻滞钙通道","抑制血管紧张素转化酶","利尿作用"],"a":3,"e":"卡托普利抑制血管紧张素转化酶，减少血管紧张素Ⅱ生成与醛固酮分泌，同时抑制缓激肽降解，使血管舒张、血压下降。"},{"q":"TMP与SMZ联合用药的机制是","o":["增加SMZ吸收","增加TMP吸收","减慢SMZ的消除","发挥协同抗菌作用","减慢TMP的消除"],"a":3,"e":"磺胺甲噁唑抑制二氢蝶酸合酶，甲氧苄啶抑制二氢叶酸还原酶，二者作用于叶酸代谢前后两个环节，双重阻断使抗菌作用增强。"},{"q":"巴比妥类药物中毒用碳酸氢钠的目的是","o":["酸碱中和解毒","促进其经肾排泄","防止酸中毒","对抗中枢抑制","促进其经生物膜扩散"],"a":1,"e":"碳酸氢钠碱化尿液，使巴比妥类解离型增多、脂溶性降低，肾小管重吸收减少，从而加速其经肾排泄，是中毒时的重要排毒措施。"},{"q":"心率受阿托品影响最明显的人群是","o":["老年人","青壮年人","婴幼儿","正在运动的人","迷走神经张力低的人"],"a":1,"e":"阿托品解除迷走神经对窦房结的抑制而加快心率，青壮年迷走张力高，故心率增快最明显；婴幼儿及迷走张力低者反应较弱。"},{"q":"以下哪项免疫调节药物由真菌代谢产物中提取的环状多肽","o":["环孢素","他克莫司","环磷酰胺","干扰素","泼尼松"],"a":0,"e":"环孢素是由真菌代谢产物中提取的环状多肽，含11个氨基酸，选择性抑制T细胞功能，为器官移植抗排斥反应的关键药物。"},{"q":"下列哪项不是中枢乙酰胆碱的功能","o":["觉醒","学习","记忆","运动调节","中枢抑制"],"a":4,"e":"中枢乙酰胆碱参与觉醒、学习记忆与运动调节，以兴奋性作用为主，并无中枢抑制作用；中枢抑制主要与GABA及甘氨酸能系统相关。"},{"q":"药物在肝脏生物转化，不属于第一步反应的是","o":["氧化","还原","水解","结合","去硫"],"a":3,"e":"生物转化第一步为氧化、还原、水解等非结合反应，使药物极性略增；结合反应属第二步，与葡萄糖醛酸等结合后水溶性明显增加而便于排泄。"},{"q":"某患者诊断为钩端螺旋体病，治疗药物首选","o":["四环素","红霉素","庆大霉素","氨苄西林","青霉素G"],"a":4,"e":"钩端螺旋体对青霉素G高度敏感，早期足量应用可迅速杀灭病原体、缩短病程，为治疗的首选药物。"},{"q":"以下药物对胃的刺激性较大的是","o":["地西泮","水合氯醛","苯巴比妥","甲丙氨酯","硫喷妥钠"],"a":1,"e":"水合氯醛对胃黏膜有强烈刺激性，口服易致恶心呕吐，须稀释后服用或灌肠，溃疡病患者不宜口服。"},{"q":"青霉素类最严重的不良反应为","o":["肝毒性","肾毒性","耳毒性","过敏性休克","二重感染"],"a":3,"e":"青霉素降解产物青霉噻唑酸等作为半抗原与蛋白结合致敏，可发生过敏性休克，为最常见且最严重的不良反应，用药前须皮试并备肾上腺素。"},{"q":"通过改变细菌细胞膜功能而产生抗菌作用的药物是","o":["四环素","多黏菌素B","红霉素","链霉素","氯霉素"],"a":1,"e":"多黏菌素B为多肽类抗生素，其阳离子与革兰阴性菌外膜脂多糖磷酸根结合，使膜通透性增加、胞内物质外漏而杀菌。"},{"q":"下列疾病中宜采用阿托品进行治疗的是","o":["室性心动过速","窦房阻滞","室上性心动过速","缺血性心脏病","窦性心动过速"],"a":1,"e":"阿托品阻断M受体解除迷走神经对心脏的抑制，改善窦房传导，用于窦房阻滞、房室传导阻滞等缓慢型心律失常；室性心动过速禁用。"},{"q":"可抑制骨髓造血功能的药物是","o":["四环素","米诺环素","氯霉素","红霉素","氨苄西林"],"a":2,"e":"氯霉素抑制骨髓造血，可致可逆性血细胞减少及不可逆的再生障碍性贫血，用药期间应定期检查血象。"},{"q":"他汀类药物是","o":["胆碱酯酶抑制药","碳酸酐酶抑制药","HMG-CoA还原酶抑制药","Na＋、K＋-ATP酶抑制药","磷酸二酯酶抑制药"],"a":2,"e":"他汀类竞争性抑制羟甲基戊二酰辅酶A还原酶，减少肝内胆固醇合成，并上调肝细胞LDL受体而降低血浆胆固醇。"},{"q":"与药物的过敏反应无关的是","o":["药物的代谢产物","制剂中的杂质","患者的体质","遗传因素","药物的剂量"],"a":4,"e":"过敏反应与药物剂量无关，取决于药物及代谢产物、制剂杂质等致敏原与患者体质、遗传因素，极小剂量亦可诱发严重反应。"},{"q":"下列哪种类型的癫痫首选苯妥英钠","o":["局限性发作","癫痫小发作","肌阵挛性发作","婴儿痉挛","精神运动性发作"],"a":0,"e":"苯妥英钠对局限性即部分性发作疗效好，为首选药之一，也可用于大发作和癫痫持续状态；对小发作无效甚至可加重。"},{"q":"糖皮质激素隔日清晨一次给药法，可避免","o":["对胃酸胃蛋白酶分泌的刺激作用","类肾上腺皮质功能亢进综合征","反跳现象","诱发和加重感染","反馈性抑制垂体-肾上腺皮质轴机能"],"a":4,"e":"隔日清晨一次给予中效糖皮质激素，可避开垂体-肾上腺皮质轴负反馈的敏感时段，减轻对轴的反馈性抑制，防止肾上腺皮质萎缩。"},{"q":"青霉素对以下哪种病原体引起的感染多数抗药","o":["钩端螺旋体","白喉杆菌","肺炎球菌","肠球菌","放线菌"],"a":3,"e":"青霉素对肠球菌仅具抑菌作用，且多数菌株产生β-内酰胺酶而抗药，治疗肠球菌感染常需与氨基糖苷类联合。"},{"q":"硫酸镁中毒导致血压下降时，最佳选择的治疗药物是","o":["肾上腺素","异丙肾上腺素","去甲肾上腺素","氯化钙","50%葡萄糖"],"a":3,"e":"硫酸镁过量抑制神经肌肉传递并扩张血管致血压下降，钙剂可直接对抗镁离子作用，故首选葡萄糖酸钙或氯化钙静脉缓慢注射。"},{"q":"骨质疏松症的主要特征不包括","o":["骨量降低","骨脆性降低","骨组织微细结构破坏","骨的力学功能减弱","是一种全身代谢性疾病"],"a":1,"e":"骨质疏松以骨量降低、骨组织微细结构破坏、骨脆性增加、骨的力学功能减弱为特征，属全身性代谢性骨病，故骨脆性降低的说法错误。"},{"q":"用于治疗阿尔茨海默病的胆碱酯酶抑制药是","o":["左旋多巴","占诺美林","多奈哌齐","美金刚","苯海索"],"a":2,"e":"多奈哌齐可逆性抑制中枢乙酰胆碱酯酶，提高脑内乙酰胆碱含量，改善阿尔茨海默病患者认知功能，用于轻中度患者。"},{"q":"激动后，可促进肾素分泌的是","o":["α1受体","α2受体","β1受体","β2受体","β3受体"],"a":2,"e":"肾小球旁细胞β1受体激动可使肾素释放增加，激活肾素-血管紧张素-醛固酮系统；β2受体激动则舒张血管、扩张支气管。"},{"q":"去甲肾上腺素生物合成过程中的限速酶是","o":["多巴脱羧酶","多巴胺β-羟化酶","酪氨酸羟化酶","儿茶酚胺氧位甲基转移酶","单胺氧化酶"],"a":2,"e":"去甲肾上腺素合成以酪氨酸为原料，酪氨酸羟化酶催化酪氨酸生成多巴，是该过程的限速酶，也是药物作用的靶点。"},{"q":"吗啡引起瞳孔缩小的机制是","o":["激动虹膜括约肌M受体","阻滞虹膜辐射肌α受体","直接兴奋虹膜括约肌","兴奋支配瞳孔的副交感神经，瞳孔括约肌收缩","激动睫状肌β受体"],"a":3,"e":"吗啡激动中枢μ受体，兴奋动眼神经核使支配瞳孔的副交感神经张力增高，瞳孔括约肌收缩而缩瞳，针尖样瞳孔是其中毒特征。"},{"q":"能与林可霉素竞争同一结合部位，呈拮抗作用的药物是","o":["链霉素","万古霉素","青霉素","红霉素","替考拉宁"],"a":3,"e":"红霉素与林可霉素均作用于细菌核糖体50S亚基，两药合用竞争同一结合位点而产生拮抗，故不宜联用。"},{"q":"下列四环素类药物中，抗菌作用最强的是","o":["米诺环素","多西环素","四环素","土霉素","金霉素"],"a":0,"e":"米诺环素为长效半合成四环素，脂溶性高、组织穿透力强，在四环素类中抗菌作用最强，对耐药金葡菌亦有效。"},{"q":"氯丙嗪引起锥体外系反应的机制是","o":["阻断肾上腺素α受体","阻断结节-漏斗系统D2受体","阻断中脑-边缘系统D2样受体","阻断中脑-皮层系统的D2样受体","阻断黑质-纹状体系统D2受体"],"a":4,"e":"氯丙嗪阻断黑质-纹状体通路D2受体，使多巴胺对纹状体的抑制解除、胆碱能相对亢进，出现帕金森综合征等锥体外系反应。"},{"q":"乙酰胆碱的主要消除方式是","o":["被单胺氧化酶所破坏","被氧位甲基转移酶破坏","被磷酸二酯酶破坏","被乙酰胆碱酯酶破坏","被神经末梢再摄取"],"a":3,"e":"乙酰胆碱在突触间隙迅速被乙酰胆碱酯酶水解为胆碱和乙酸而失活，是其主要消除方式；单胺氧化酶和儿茶酚氧位甲基转移酶代谢儿茶酚胺。"},{"q":"可首选治疗流行性脑脊髓膜炎的药物是","o":["甲氧苄啶","司帕沙星","氧氟沙星","磺胺嘧啶银","磺胺嘧啶"],"a":4,"e":"磺胺嘧啶与血浆蛋白结合率低，易透过血脑屏障，脑脊液浓度高，对脑膜炎奈瑟菌敏感，为流行性脑脊髓膜炎的首选药。"},{"q":"选择性M1受体阻断药是","o":["阿托品","东莨菪碱","贝那替秦","溴丙胺太林","哌仑西平"],"a":4,"e":"哌仑西平选择性阻断胃壁细胞M1受体，抑制胃酸分泌，为选择性M1受体阻断药，不良反应较阿托品少。"},{"q":"阿托品对眼的作用表现为","o":["降低眼内压","调节痉挛","缩瞳","收缩瞳孔括约肌","调节晶状体扁平"],"a":4,"e":"阿托品阻断睫状肌M受体使其松弛，悬韧带紧张而使晶状体变扁平，调节麻痹、视近物模糊；同时瞳孔括约肌松弛而散瞳、眼内压升高。"},{"q":"新斯的明不宜用于治疗","o":["青光眼","手术后尿潴留","阵发性室上性心动过速","筒箭毒碱过量中毒","重症肌无力"],"a":0,"e":"新斯的明为可逆性抗胆碱酯酶药，用于重症肌无力、术后腹胀及尿潴留、阵发性室上性心动过速和筒箭毒碱中毒；青光眼以毛果芸香碱局部治疗。"},{"q":"下列药物中具有内在拟交感活性的是","o":["普萘洛尔","纳多洛尔","噻吗洛尔","吲哚洛尔","阿替洛尔"],"a":3,"e":"吲哚洛尔兼具β受体阻断与内在拟交感活性，对心率、心输出量抑制较轻；普萘洛尔、噻吗洛尔、纳多洛尔、阿替洛尔均无内在拟交感活性。"},{"q":"对急性痛风有效的药物是","o":["秋水仙碱","别嘌醇","丙磺舒","阿司匹林","保泰松"],"a":0,"e":"秋水仙碱抑制中性粒细胞趋化与微管功能，减轻尿酸盐结晶引起的急性炎症，为急性痛风发作的首选药；别嘌醇、丙磺舒用于间歇期。"},{"q":"骨折剧痛，宜选用的止痛药是","o":["可待因","氯丙嗪","罗通定","吲哚美辛","哌替啶"],"a":4,"e":"哌替啶为人工合成阿片受体激动药，镇痛强度约为吗啡的十分之一，起效快，可用于骨折等急性锐痛；可待因、罗通定镇痛作用弱。"},{"q":"对毒性反应的描述错误的是","o":["在药物剂量过大时可能会发生","一般可以预知","导致畸胎不属于毒性反应","药物在体内蓄积过多时可能会发生","包括急性毒性反应和慢性毒性反应"],"a":2,"e":"毒性反应由剂量过大或体内蓄积过多所致，可预知，分急性与慢性两类；药物致畸属特殊毒性作用，仍属毒性反应范畴。"},{"q":"药物或其代谢物排泄的主要途径是","o":["肾","胆道","肠道","汗腺","肺"],"a":0,"e":"药物及其代谢物主要经肾小球滤过、肾小管分泌和重吸收排出，肾是大多数药物排泄的主要器官；胆汁、乳汁及汗腺排泄量少。"},{"q":"关于糖皮质激素抗炎作用的基本机制，错误的是","o":["与靶细胞质内的糖皮质激素受体结合，而影响了参与炎症的一些基因转录","可抑制炎性介质白三烯等的生成","直接杀灭细菌","抑制一氧化氮合酶的表达","对细胞能量代谢有直接影响"],"a":2,"e":"糖皮质激素与胞质受体结合后调控炎症相关基因转录，抑制白三烯、前列腺素等炎性介质生成及诱导型一氧化氮合酶表达，并无直接杀菌作用。"},{"q":"可用于治疗高钙血症的药物是","o":["阿米洛利","氨苯喋啶","呋塞米","氢氯噻嗪","螺内酯"],"a":2,"e":"呋塞米抑制髓袢升支粗段对钙的重吸收，增加尿钙排出，配合补液可用于高钙血症；噻嗪类减少尿钙排泄，反可升高血钙。"},{"q":"首过消除主要发生在","o":["口服给药","肌内注射","静脉推注","腹腔注射","静脉滴注"],"a":0,"e":"口服药物经胃肠吸收后先经门静脉入肝，部分被肝药酶代谢灭活，使进入体循环药量减少，称首过消除；注射给药不经过门静脉。"},{"q":"可用于各种局部麻醉方法的局麻药是","o":["丁卡因","利多卡因","普鲁卡因","丁哌卡因","罗哌卡因"],"a":1,"e":"利多卡因穿透力强、弥散广、起效快，对组织刺激性小，可用于表面麻醉、浸润麻醉、传导麻醉及硬膜外麻醉等各种局麻方法。"},{"q":"肾绞痛时宜选用的治疗药物组合是","o":["阿托品和新斯的明合用","东莨菪碱和毒扁豆碱合用","哌替啶和吗啡合用","阿托品和哌替啶合用","东莨菪碱和哌替啶合用"],"a":3,"e":"肾绞痛由输尿管痉挛引起，阿托品阻断M受体解痉，哌替啶镇痛，二者合用解痉止痛，为肾绞痛的标准组合。"},{"q":"下列有关于抗贫血药铁剂的描述，不正确的是","o":["Fe2＋易于吸收","铁剂和维生素C同服不利于吸收","鞣质不利于铁剂的吸收","铁剂和牛奶同服不利于吸收","四环素会影响铁剂的吸收"],"a":1,"e":"维生素C使铁还原为二价铁并形成可溶性螯合物，促进铁吸收，同服有利；鞣质、牛奶中的钙磷及四环素类则妨碍铁吸收。"},{"q":"治疗重症肌无力应选用","o":["新斯的明","毛果芸香碱","毒扁豆碱","筒箭毒碱","碘解磷定"],"a":0,"e":"新斯的明抑制胆碱酯酶，增加神经肌肉接头处乙酰胆碱浓度，改善肌无力症状，为治疗重症肌无力的常用药。"},{"q":"药动学中房室模型中的房室划分是基于","o":["药物的代谢率","药物的转运速率","药物的吸收率","药物的排泄速率","药物的分布容积"],"a":1,"e":"房室模型按药物体内转运速率快慢将机体划分为若干抽象房室，同一房室内药物分布均匀，故划分依据是转运速率而非解剖结构。"},{"q":"属于β-肾上腺素受体激动药的平喘药是","o":["沙丁胺醇","胆茶碱","酮替芬","布地奈德","扎鲁司特"],"a":0,"e":"沙丁胺醇选择性激动支气管平滑肌β2受体，激活腺苷酸环化酶使cAMP增加，舒张支气管而平喘，为短效β2受体激动药。"},{"q":"对临床MRSA作用强，被誉为“抗生素的最后一道防线”的药物是","o":["多黏菌素B","阿奇霉素","多西霉素","万古霉素","林可霉素"],"a":3,"e":"万古霉素与细菌细胞壁前体肽聚糖结合，阻碍细胞壁合成，对MRSA等耐药革兰阳性菌作用强，被誉为抗生素的最后防线。"},{"q":"某患者诊断为梅毒感染，治疗药物首选青霉素G，其抗菌作用机制为","o":["抑制细菌细胞壁的合成","改变胞浆膜的通透性","抑制细菌蛋白质的合成","抑制细菌叶酸的合成","抑制细菌DNA的复制"],"a":0,"e":"青霉素与青霉素结合蛋白结合，抑制转肽酶，阻碍肽聚糖交联使细胞壁缺损，菌体肿胀破裂而杀菌，对繁殖期细菌作用强。"},{"q":"通过保护胃黏膜治疗消化性溃疡的药物是","o":["硫酸镁","乳酶生","硫糖铝","碳酸氢钠","碳酸钙"],"a":2,"e":"硫糖铝在酸性环境下解离并聚合成胶体覆盖溃疡面，形成保护膜、吸附胃蛋白酶并刺激前列腺素合成，属胃黏膜保护药。"},{"q":"硝酸甘油最常用的给药途径是","o":["贴皮","静脉注射","口服","舌下给药","吸入"],"a":3,"e":"硝酸甘油首过消除明显，口服生物利用度不足10%，舌下含服经口腔黏膜吸收直接入体循环，起效快，为心绞痛发作常用途径。"},{"q":"与细菌耐药性产生无关的是","o":["细菌产生β内酰胺酶水解青霉素G","细菌产生钝化酶灭活氨基糖苷类抗生素","细菌体内与抗菌药结合的靶位结构改变","细菌改变对抗菌药的通透性降低抗菌药在菌体内的浓度","细菌体内产生的内毒素增加"],"a":4,"e":"细菌耐药机制包括产生灭活酶、改变靶位结构、降低膜通透性及增强外排；内毒素为革兰阴性菌细胞壁成分，其增多与耐药无关。"},{"q":"在体内的代谢产物仍有抗凝作用的药物是","o":["肝素","水蛭素","华法林","阿司匹林","醋硝香豆素"],"a":4,"e":"醋硝香豆素的代谢产物仍具抗凝活性，作用较双香豆素持久；华法林代谢物基本失活，其抗凝作用主要取决于原形药浓度。"},{"q":"无中枢抑制作用的药物是","o":["苯海拉明","异丙嗪","特非那定","曲吡那敏","氯苯那敏"],"a":2,"e":"特非那定不易透过血脑屏障，几乎无中枢镇静作用，属第二代H1受体阻断药；过量或与肝酶抑制药合用可致心脏毒性。"},{"q":"下列情况慎用碘制剂的是","o":["孕妇","甲亢患者术前准备","单纯性甲状腺肿","甲状腺危象","白细胞减少"],"a":0,"e":"碘可透过胎盘进入胎儿甲状腺，妊娠期使用可致胎儿甲状腺肿及甲减，故孕妇慎用；小剂量碘用于单纯性甲状腺肿及术前准备。"},{"q":"强心苷中毒所致室性心动过速伴有二度房室传导阻滞应选用的治疗药物是","o":["维拉帕米","氯化钾","普鲁卡因胺","氟桂利嗪","苯妥英钠"],"a":4,"e":"强心苷中毒所致室性心律失常伴传导阻滞时，苯妥英钠抑制浦肯野纤维自律性、改善传导且不抑制房室传导，为首选，此时补钾应慎重。"},{"q":"舌下给药的主要优点是","o":["经济方便","吸收面积大","吸收规则","避免首过消除","副作用少"],"a":3,"e":"舌下黏膜血流丰富，药物经舌下静脉直接入体循环，避开胃肠及肝脏首过消除，生物利用度高、起效快。"},{"q":"治疗黏液性水肿的药物是","o":["甲巯咪唑","丙硫氧嘧啶","小剂量碘剂","甲状腺激素","卡比马唑"],"a":3,"e":"黏液性水肿为甲状腺功能减退的严重表现，须用甲状腺激素替代治疗，从小剂量开始逐渐加量，并监测心率与血T3、T4。"},{"q":"有关哌替啶的描述错误的是","o":["可以用于心源性哮喘","镇痛效价强度比吗啡弱","有止泻作用","有呼吸抑制作用","有成瘾性"],"a":2,"e":"哌替啶激动阿片受体，镇痛强度约为吗啡的十分之一，可致呼吸抑制、成瘾，可用于心源性哮喘；其使胃肠蠕动减慢，并无止泻用途。"},{"q":"可迅速进入中枢神经系统的M受体阻断药是","o":["山莨菪碱","东莨菪碱","溴甲东莨菪碱","哌仑西平","地西泮"],"a":1,"e":"东莨菪碱脂溶性高，易透过血脑屏障，对中枢神经系统作用强，治疗量即可致镇静、催眠，用于晕动病及麻醉前给药。"},{"q":"可用于治疗癌症呕吐的药物是","o":["氯噻嗪","氯氮平","氯胺酮","甲氯芬酯","氯丙嗪"],"a":4,"e":"氯丙嗪阻断延髓催吐化学感受区D2受体，有强大镇吐作用，可用于尿毒症、放射病及癌症所致呕吐，对前庭刺激引起的晕吐无效。"},{"q":"临床上可以口服治疗消化性溃疡的前列腺素类似物是","o":["双嘧达莫","前列环素","米索前列醇","前列腺素E2","奥美拉唑"],"a":2,"e":"米索前列醇为前列腺素E1衍生物，口服可抑制胃酸分泌、促进黏液和碳酸氢盐分泌并增加黏膜血流，用于消化性溃疡及NSAIDs相关溃疡。"},{"q":"可增强加拉碘铵肌松作用的药物是","o":["青霉素","庆大霉素","氯霉素","头孢拉定","多黏菌素E"],"a":1,"e":"氨基糖苷类阻断神经肌肉接头传递并降低接头对乙酰胆碱的敏感性，庆大霉素与加拉碘铵合用可增强并延长肌松作用，甚至致呼吸抑制。"},{"q":"以下哪项不是自身免疫性疾病的共同特点","o":["病因大多不明，女性多于男性","血液中常存在高滴度自身抗体","多因严重感染、恶性肿瘤、免疫抑制剂等原因引起","常反复发作或慢性迁延","有明显的家族倾向性"],"a":2,"e":"自身免疫性疾病多病因不明、女性多见，血中存在高滴度自身抗体，病程反复迁延且有家族倾向；因严重感染、肿瘤或免疫抑制所致者属继发性免疫缺陷。"},{"q":"药物效应动力学研究的是","o":["人体对药物的反应性","如何提高药物疗效","实验动物对药物的反应性","药物在机体的影响下发生的变化及规律","药物对机体的作用及作用机制"],"a":4,"e":"药物效应动力学研究药物对机体的作用、作用机制及量效关系；机体对药物的处置即吸收、分布、代谢与排泄属药动学内容。"},{"q":"浸润麻醉时局麻药中加入肾上腺素的目的是","o":["预防过敏性休克","防止麻醉过程产生血压下降","对抗局麻药的扩张血管作用","延长局麻作用持续时间","促进局麻药的吸收"],"a":3,"e":"肾上腺素收缩局部血管，减少局麻药吸收，既延长局麻作用时间、增强麻醉效果，又降低吸收中毒风险，并减少手术野出血。"},{"q":"无明显中枢副作用的H1受体阻断药是","o":["苯海拉明","异丙嗪","美克洛嗪","氯苯那敏","阿司咪唑"],"a":4,"e":"阿司咪唑为第二代H1受体阻断药，难以透过血脑屏障，几乎无中枢镇静作用；过量或与肝酶抑制药合用可致QT间期延长和室性心律失常。"},{"q":"患儿，男，4岁，因患体癣需要局部应用制霉菌素，该药特点为","o":["极易产生耐药性","对念珠菌属抗菌活性较高","可注射给药","局部给药时不良反应明显","口服给药主要不良反应为粒细胞减少"],"a":1,"e":"制霉菌素为多烯类抗真菌药，与真菌细胞膜麦角固醇结合形成孔道，对念珠菌属活性高，口服不吸收，局部外用治疗皮肤黏膜念珠菌感染。"},{"q":"磺胺类药物目前临床应用大大受限的主要原因是","o":["抗菌谱窄","血药浓度低","细菌易耐药","容易引起过敏反应","易透过血脑屏障"],"a":3,"e":"磺胺类抗菌谱较广、价格低廉，但过敏反应发生率高，可致皮疹、药热甚至剥脱性皮炎，加之耐药菌株增多，使其临床应用明显受限。"},{"q":"使用胰岛素治疗过程中若出现饥饿、心悸、昏迷、震颤、惊厥等应立即给予","o":["肾上腺素皮下注射","胰岛素皮下注射","异丙嗪肌内注射","50%葡萄糖静脉注射","氢化可的松肌内注射"],"a":3,"e":"上述症状为胰岛素过量所致低血糖反应，应立即静脉注射50%葡萄糖，清醒后以含糖食物维持，并调整胰岛素剂量。"},{"q":"下列属于新药的是","o":["已上市的药品改变剂型","已上市的药品改变给药途径","已上市的药品增加新的适应证","已上市的药品制成新的复方制剂","未曾在中国境内外上市销售的药品"],"a":4,"e":"新药指未曾在中国境内外上市销售的药品；改变剂型、给药途径、增加新适应证或制成复方制剂者属改良型药品。"},{"q":"呋塞米的临床应用不包括","o":["治疗水肿","加速毒物排出","预防急慢性肾衰竭","治疗尿崩症","治疗高钙血症"],"a":3,"e":"呋塞米用于各类水肿、急性肺水肿、急慢性肾功能不全、高钙血症及加速毒物排泄；尿崩症用氢氯噻嗪，故不属其临床应用。"},{"q":"吗啡的下述药理作用，哪项是错误的","o":["镇痛作用","呼吸抑制作用","镇咳作用","食欲抑制作用","止泻作用"],"a":3,"e":"吗啡的典型作用为镇痛、镇静、镇咳、抑制呼吸及兴奋胃肠平滑肌致便秘；食欲抑制不是其固有药理作用。"},{"q":"外周肾上腺素能神经合成与释放的主要递质是","o":["多巴胺","肾上腺素","去甲肾上腺素","异丙肾上腺素","间羟胺"],"a":2,"e":"外周肾上腺素能神经末梢合成并以去甲肾上腺素为主要递质，释放后激动α、β受体；肾上腺素主要由肾上腺髓质嗜铬细胞分泌。"},{"q":"NN受体激动剂产生的药理作用是","o":["胃肠道平滑肌舒张","呼吸道分泌物减少","血管扩张，血压下降","心率加快，心肌收缩力增强","骨骼肌收缩"],"a":3,"e":"NN受体激动使自主神经节后神经元兴奋，交感神经节兴奋占优势时心率加快、心肌收缩力增强、血压升高；骨骼肌收缩由N2受体介导。"},{"q":"可用糖皮质激素治疗的是","o":["严重哮喘伴有高血压","病毒感染","精神病患者服用苯巴比妥引起的过敏性皮炎","急性淋巴细胞白血病","带状疱疹"],"a":3,"e":"糖皮质激素可诱导淋巴细胞凋亡，对急性淋巴细胞白血病有治疗作用，常联合化疗用于儿童急淋；其抑制免疫炎症，不利于抗感染。"},{"q":"治疗铜绿假单胞菌感染有效的药物是","o":["头孢氨苄","克林霉素","青霉素","羧苄西林","阿莫西林"],"a":3,"e":"羧苄西林为抗铜绿假单胞菌广谱青霉素，对铜绿假单胞菌有效；头孢氨苄、阿莫西林、克林霉素及青霉素G对其无效。"},{"q":"利福平抗结核菌的作用原理是","o":["干扰菌体RNA的合成","干扰菌体DNA的合成","抑制分枝菌酸","抑制蛋白质合成","竞争PABA"],"a":0,"e":"利福平特异性抑制细菌DNA依赖性RNA聚合酶，阻碍mRNA合成而杀灭结核分枝杆菌，对细胞内、外菌均有作用。"},{"q":"卡比多巴治疗帕金森病的机制是","o":["激动中枢多巴胺受体","抑制外周多巴脱羧酶活性","阻断中枢胆碱受体","抑制多巴胺的再摄取","使多巴胺受体增敏"],"a":1,"e":"卡比多巴抑制外周多巴脱羧酶，使左旋多巴在外周脱羧减少、进入中枢的量增加，从而增强疗效并减轻外周不良反应。"},{"q":"下列哪个镇静催眠药物适合治疗单纯入睡困难","o":["地西泮","异戊巴比妥","唑吡坦","水合氯醛","丁螺环酮"],"a":2,"e":"唑吡坦选择性激动GABA-A受体ω1亚型，催眠作用强而抗焦虑、肌松作用弱，起效快、半衰期短，适用于单纯入睡困难。"},{"q":"吗啡禁用于分娩止痛，是由于","o":["可抑制新生儿呼吸","易产生成瘾性","易在新生儿体内蓄积","镇痛效果差","可致新生儿便秘"],"a":0,"e":"吗啡易透过胎盘抑制胎儿呼吸中枢，可致新生儿呼吸抑制甚至窒息，故分娩止痛禁用，必要时备纳洛酮。"},{"q":"有关噻氯匹定的说法，正确的是","o":["与血小板膜糖蛋白GP Ⅱb/Ⅲa受体结合，阻断受体与纤维蛋白原的结合","骨髓抑制常发生在用药3个月之后","干扰血小板膜糖蛋白GP Ⅱb/Ⅲa受体与纤维蛋白原结合，抑制血小板激活","口服后2小时即可发挥作用","主要不良反应为诱发消化性溃疡"],"a":2,"e":"噻氯匹定经肝代谢为活性物，阻断血小板ADP受体，进而抑制GPⅡb/Ⅲa受体与纤维蛋白原结合，使血小板不能聚集；骨髓抑制多发生于用药3个月内。"},{"q":"糖皮质激素治疗哪种休克效果最佳","o":["感染中毒性休克","低血容量性休克","过敏性休克","心源性休克","疼痛性休克"],"a":0,"e":"感染中毒性休克在有效抗菌治疗基础上早期大剂量应用糖皮质激素，可抑制炎症介质释放、降低血管通透性、改善微循环，疗效最佳。"},{"q":"毒扁豆碱可用于治疗","o":["青光眼","重症肌无力","腹胀气","尿潴留","阵发性室上性心动过速"],"a":0,"e":"毒扁豆碱为可逆性胆碱酯酶抑制药，局部滴眼可缩小瞳孔、降低眼内压并收缩睫状肌，用于青光眼治疗。"},{"q":"耳、肾毒性最大的氨基糖苷类抗生素是","o":["西索米星","奈替米星","卡那霉素","庆大霉素","新霉素"],"a":4,"e":"新霉素的耳毒性与肾毒性在氨基糖苷类中最强，因毒性大，现仅作口服或局部外用，不用于全身感染。"},{"q":"属于抗精神分裂症药的是","o":["氨氯地平","氯氮平","丙咪嗪","氟西汀","碳酸锂"],"a":1,"e":"氯氮平属非典型抗精神病药，阻断D4与5-HT2A受体，对难治性精神分裂症有效且锥体外系反应少；丙咪嗪、氟西汀为抗抑郁药。"},{"q":"硝普钠治疗心功能不全的药理学基础是","o":["改善冠脉血流","降低心输出量","降低血压","扩张动、静脉而降低心脏前、后负荷","扩张动脉降低后负荷"],"a":3,"e":"硝普钠释放一氧化氮，同时扩张动脉与静脉，降低心脏前、后负荷，减少心肌耗氧并增加心输出量，用于急性心功能不全。"},{"q":"下列关于阿司匹林的不良反应，错误的是","o":["胃肠道反应最为常见","维生素K可预防阿司匹林导致的出血","阿司匹林哮喘是以抗原-抗体反应为基础的过敏反应","病毒感染患儿不宜用阿司匹林","静脉滴注碳酸氢钠可缓解严重的水杨酸反应"],"a":2,"e":"阿司匹林哮喘系环氧酶被抑制后前列腺素合成减少、脂氧酶途径白三烯生成增多所致，并非抗原-抗体反应的过敏反应。"},{"q":"因行胃镜操作给予筒箭毒碱导致中毒，建议给予的抢救药物是","o":["肾上腺素","去甲肾上腺素","新斯的明","多巴胺","麻黄碱"],"a":2,"e":"筒箭毒碱为非去极化型肌松药，竞争性阻断N2受体；新斯的明抑制胆碱酯酶、增加乙酰胆碱浓度可竞争性拮抗其肌松作用。"},{"q":"酚妥拉明不用于治疗","o":["顽固性充血性心力衰竭","休克","胃十二指肠溃疡","肾上腺嗜铬细胞瘤","外周血管痉挛性疾病"],"a":2,"e":"酚妥拉明阻断α受体，用于外周血管痉挛性疾病、休克、嗜铬细胞瘤及顽固性心衰；其促进胃酸分泌，故不用于胃十二指肠溃疡。"},{"q":"伴有心绞痛的高血压患者宜选用的降压药物是","o":["硝酸甘油","普萘洛尔","维拉帕米","氢氯噻嗪","卡托普利"],"a":1,"e":"普萘洛尔阻断β受体，既降低血压又减慢心率、降低心肌耗氧量，可同时控制血压与心绞痛发作，为伴心绞痛高血压的优选。"},{"q":"绝大多数的药物受体是属于","o":["分子量小于1000的小分子物质","双分子层的脂质物质","位于膜上或胞内的蛋白质","DNA","RNA"],"a":2,"e":"绝大多数药物受体是位于细胞膜或胞内的蛋白质，具有特异性识别与信号转导功能，少数为核酸或酶。"},{"q":"糖皮质激素大剂量突击疗法适用于","o":["肾病综合征","结缔组织病","恶性淋巴瘤","感染中毒性休克","顽固性支气管哮喘"],"a":3,"e":"大剂量突击疗法适用于急性危重疾病，如感染中毒性休克、过敏性休克、哮喘持续状态，疗程一般不超过3至5天。"},{"q":"治疗癫痫大发作和单纯局限性发作首选","o":["苯二氮䓬类","乙琥胺","苯巴比妥钠","卡马西平","丙戊酸钠"],"a":3,"e":"卡马西平抑制钠通道并抑制强直后电位扩散，对癫痫大发作和单纯局限性发作疗效好，为首选药，对失神发作无效。"},{"q":"阿托品作用于","o":["烟碱受体","α受体","β受体","突触前M受体","各类型M受体"],"a":4,"e":"阿托品对M1、M2、M3各亚型M受体均有阻断作用，选择性低，故作用广泛，涉及腺体、眼、内脏平滑肌及心脏。"},{"q":"氨基糖苷类抗生素的耐药机制不包括","o":["产生乙酰化酶","产生β-内酰胺酶","产生腺苷化酶","外膜膜孔蛋白的结构改变","30S核糖体改变"],"a":1,"e":"氨基糖苷类耐药主要因细菌产生乙酰化酶、磷酸化酶、腺苷化酶等钝化酶，或膜孔蛋白改变致摄取减少、30S核糖体靶位改变；β-内酰胺酶水解青霉素类。"},{"q":"氯沙坦的作用靶点是","o":["α1受体","AT1受体","AT2受体","β受体","血管紧张素转化酶"],"a":1,"e":"氯沙坦选择性阻断血管紧张素Ⅱ的AT1受体，抑制其收缩血管与促醛固酮分泌作用而降压，不影响缓激肽降解，故干咳少见。"},{"q":"某药剂量相等的两种制剂口服后曲线下面积相等，但达峰时间不同，是因为","o":["肝脏代谢速度不同","肾脏排泄速度不同","血浆蛋白结合率不同","分布部位不同","吸收速度不同"],"a":4,"e":"AUC反映药物吸收总量，两制剂AUC相等说明吸收程度相同；达峰时间不同提示吸收速度存在差异，属生物利用度速率方面的差别。"},{"q":"体内药物主动转运的特点是","o":["由载体进行，消耗能量","由载体进行，不消耗能量","不消耗能量，无竞争性抑制","消耗能量，无竞争性抑制","不消耗能量，有竞争性抑制"],"a":0,"e":"主动转运逆浓度梯度进行，需膜上特异性载体并消耗ATP，具有饱和现象和竞争性抑制，如钠泵及肾小管有机酸分泌。"},{"q":"中枢镇静作用最强的药物是","o":["阿司咪唑","苯海拉明","西替利嗪","苯茚胺","氯雷他定"],"a":1,"e":"苯海拉明脂溶性高，易透过血脑屏障阻断中枢H1受体，镇静催眠作用在H1受体阻断药中最强，可用于晕动病及失眠。"},{"q":"当肝功能严重障碍时，药物从机体的消除有何变化","o":["消除速率加快，应适当增加给药剂量","消除速率减慢，应适当减少给药剂量","消除速率加快，半衰期延长，应适当减少给药剂量","消除速率减慢，半衰期缩短，应适当增加给药剂量","消除速率不变，半衰期延长，应适当减少给药剂量"],"a":1,"e":"肝功能严重障碍时肝药酶活性降低，药物生物转化减慢，消除速率下降、半衰期延长，易致蓄积中毒，故应减少给药剂量。"},{"q":"属于中效能利尿药的药物是","o":["呋塞米","依他尼酸","氢氯噻嗪","布美他尼","阿米洛利"],"a":2,"e":"氢氯噻嗪抑制髓袢升支粗段皮质部钠氯共转运体，属中效能利尿药；呋塞米、依他尼酸、布美他尼为高效能，阿米洛利为低效能保钾药。"},{"q":"华法林引起的出血宜选用","o":["去甲肾上腺素","维生素K","氨甲苯酸","对氯苯甲酸","维生素C"],"a":1,"e":"华法林抑制维生素K环氧化物还原酶，阻碍凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的γ-羧化，其所致出血用维生素K对抗，紧急时输注凝血酶原复合物。"},{"q":"麻黄碱的用途中，描述错误的是","o":["可用于房室传导阻滞的治疗","可用于轻症哮喘的治疗","缓解荨麻疹的皮肤黏膜症状","治疗鼻黏膜充血引起的鼻塞","防治硬膜外麻醉和蛛网膜下腔麻醉引起的低血压"],"a":0,"e":"麻黄碱激动α、β受体并促进NA释放，用于轻症哮喘、鼻塞、荨麻疹及硬膜外麻醉所致低血压；房室传导阻滞需用异丙肾上腺素等直接兴奋β1受体的药物。"},{"q":"苯海索的作用是","o":["促进DA神经元释放DA，抑制DA摄取","在脑内转变为DA，补充纹状体中DA之不足","激活DA受体","拮抗中枢胆碱受体","兴奋中枢胆碱受体"],"a":3,"e":"苯海索为中枢性抗胆碱药，阻断纹状体M胆碱受体，纠正帕金森病中DA与ACh的失衡；其不能补充DA，也不激动DA受体。"},{"q":"促进铁的吸收因素有","o":["磷酸盐","碳酸盐","四环素","维生素C","抗酸药"],"a":3,"e":"维生素C将Fe3+还原为Fe2+并形成可溶性螯合物，显著促进铁吸收；磷酸盐、碳酸盐、四环素及抗酸药均与铁形成难溶复合物而阻碍吸收。"},{"q":"以下关于血/气分配系数小的全麻药，描述正确的是","o":["诱导快，苏醒快","诱导慢，苏醒快","诱导快，苏醒慢","诱导慢，苏醒慢","不影响诱导，苏醒快"],"a":0,"e":"血/气分配系数小者血中溶解量少，肺泡内麻醉药分压上升快，脑内分压随之迅速升高，故诱导快；停药后血液迅速带走药物，苏醒也快。"},{"q":"丙硫氧嘧啶的作用机制是","o":["抑制甲状腺激素的合成","抑制甲状腺激素的释放","抑制甲状腺激素的利用","抑制甲状腺激素的摄取","增加外周组织中T3水平"],"a":0,"e":"丙硫氧嘧啶抑制甲状腺过氧化物酶，阻碍碘化物氧化及酪氨酸偶联，从而抑制甲状腺激素合成；尚抑制外周T4脱碘生成T3。"},{"q":"下列何药可用于治疗立克次体引起的斑疹伤寒","o":["青霉素","红霉素","四环素","阿奇霉素","乙酰螺旋霉素"],"a":2,"e":"四环素对立克次体有较强作用，为斑疹伤寒、恙虫病等立克次体病的首选；青霉素、红霉素及大环内酯类对其无效或疗效差。"},{"q":"下列疾病，禁用糖皮质激素类药物的是","o":["中毒性菌痢","感染性休克","活动性消化性溃疡病","重症伤寒","过敏性休克"],"a":2,"e":"糖皮质激素促进胃酸和胃蛋白酶分泌、抑制胃黏液合成并延缓溃疡愈合，活动性消化性溃疡病属禁忌；中毒性菌痢、感染性休克恰为其适应证。"},{"q":"磺胺类药物常见的不良反应不包括","o":["结晶尿、血尿和尿闭等症状","药物热、皮疹、偶见多形性红斑及剥脱性皮炎","白细胞减少症","再生障碍性贫血","过敏性休克"],"a":4,"e":"磺胺类常见结晶尿、血尿，皮疹、药物热等过敏反应及白细胞减少、再生障碍性贫血；过敏性休克多由青霉素引起，不是磺胺的典型不良反应。"},{"q":"心房纤颤伴甲亢应选用","o":["维拉帕米","奎尼丁","胺碘酮","普萘洛尔","地高辛"],"a":3,"e":"普萘洛尔阻断β受体，减慢房室传导并降低儿茶酚胺对心房肌的刺激，甲亢时交感活性增强所致房颤尤为适用；维拉帕米、地高辛不控制甲亢高代谢状态。"},{"q":"强心苷中肠肝循环量最多的药物是","o":["洋地黄毒苷","地高辛","毛花苷丙","毒毛花苷K","铃兰毒苷"],"a":0,"e":"洋地黄毒苷脂溶性高，经胆汁排入肠后又部分被重吸收，肠肝循环量最大，故作用持久、t1/2长；地高辛、毛花苷丙等肠肝循环少。"},{"q":"不能减少触发活动的机制是","o":["促进或加速复极，可减少早后除极","抑制早后除极上升支的内向离子流，可减少早后除极","降低最大舒张电位，可减少早后除极","抑制细胞内钙超载，可减少迟后除极的发生","动作电位时程过度延长，可减少早后除极的发生"],"a":2,"e":"降低最大舒张电位只改变膜电位水平，不能中止早后除极的钙内流；减少触发活动需缩短动作电位时程、抑制L型钙流或减轻细胞内钙超载。"},{"q":"布洛芬主要用于","o":["冠心病","心源性哮喘","风湿性关节炎","人工冬眠","镇静催眠"],"a":2,"e":"布洛芬抑制环氧酶，具解热、镇痛、抗炎作用，临床主要用于风湿性及类风湿性关节炎、骨关节炎；对冠心病、心源性哮喘无效。"},{"q":"地塞米松适用于下列哪种疾病的治疗","o":["水痘","糖尿病","带状疱疹","霉菌感染","再生障碍性贫血"],"a":4,"e":"地塞米松可刺激骨髓造血，用于再生障碍性贫血、血小板减少症等血液病；水痘、带状疱疹、糖尿病及真菌感染均属其禁忌或慎用情况。"},{"q":"哌唑嗪可选择性阻断","o":["β1受体","β2受体","α1受体","α2受体","M受体"],"a":2,"e":"哌唑嗪选择性阻断突触后膜α1受体，舒张小动脉和静脉而降压，不阻断突触前α2受体，故较少引起反射性心动过速。"},{"q":"氨基糖苷类抗生素的抗菌作用机制是","o":["抑制细胞壁的合成","影响细菌胞浆膜通透性","抗叶酸代谢","抑制细菌蛋白质的合成","抑制核酸代谢"],"a":3,"e":"氨基糖苷类与细菌30S亚基多个位点结合，抑制始动、延伸及终止各阶段，阻碍蛋白质合成并使异常蛋白掺入胞膜。"},{"q":"以下免疫抑制剂及其作用机制配对错误的是","o":["环孢素——抑制T细胞活化、抑制多种细胞因子的生成","泼尼松——抑制多种细胞因子的基因转录","他克莫司——抑制嘌呤及嘧啶的合成","巴利昔单克隆抗体——阻断T help细胞IL-2受体","环磷酰胺——杀伤增殖期淋巴细胞及NK细胞活性"],"a":2,"e":"他克莫司与环孢素同属钙调磷酸酶抑制剂，抑制T细胞活化及细胞因子生成；抑制嘌呤、嘧啶合成的是霉酚酸酯与硫唑嘌呤，故该配对错误。"},{"q":"下列哪种药物可用于治疗焦虑症","o":["异戊巴比妥","唑吡坦","水合氯醛","甲丙氨酯","丁螺环酮"],"a":4,"e":"丁螺环酮为5-HT1A受体部分激动剂，具抗焦虑作用而无镇静、肌松和成瘾性，适用于焦虑症；唑吡坦、甲丙氨酯主要用于催眠。"},{"q":"促进胰岛素分泌的口服降糖药是","o":["甲苯磺丁脲","二甲双胍","吡格列酮","阿卡波糖","罗格列酮"],"a":0,"e":"甲苯磺丁脲属磺酰脲类，阻断胰岛β细胞ATP敏感性钾通道，促钙内流而释放胰岛素；二甲双胍、阿卡波糖及噻唑烷二酮类不促泌。"},{"q":"抑制远曲小管近端Na+-Cl-同向转运子的药物是","o":["呋塞米","螺内酯","氢氯噻嗪","乙酰唑胺","甘露醇"],"a":2,"e":"氢氯噻嗪抑制远曲小管近端Na+-Cl-同向转运子，减少NaCl重吸收而利尿；呋塞米作用于髓袢升支，螺内酯拮抗醛固酮受体。"},{"q":"治疗梅毒与钩端螺旋体病应首选","o":["四环素","庆大霉素","红霉素","氯霉素","青霉素"],"a":4,"e":"青霉素对梅毒螺旋体及钩端螺旋体高度敏感，为两病首选；四环素、红霉素、氯霉素疗效均不及青霉素，庆大霉素对螺旋体无效。"},{"q":"青霉素类药共同具有","o":["耐酸、口服有效","耐β-内酰胺酶","抗菌谱广","主要应用于革兰氏阳性菌感染","可能发生过敏性休克，并有交叉过敏反应"],"a":4,"e":"青霉素类均可引起过敏性休克，且各药间存在交叉过敏，用前须做皮试并备肾上腺素；抗菌谱窄、不耐酸不耐酶并非其共同特点。"},{"q":"氯丙嗪阻断黑质-纹状体通路D2受体引起","o":["抗精神病作用","体温调节失灵","催乳素分泌","锥体外系反应","镇吐作用"],"a":3,"e":"氯丙嗪阻断黑质-纹状体通路D2受体，使ACh相对占优，引起帕金森综合征、静坐不能等锥体外系反应；抗精神病作用与中脑边缘系统相关。"},{"q":"需要饭前服用的药物是","o":["哌仑西平","溴丙胺太林","山莨菪碱","阿托品","地泊溴铵"],"a":1,"e":"溴丙胺太林为季铵类M受体阻断药，餐前半小时服用可使进食时胃酸分泌和胃肠痉挛得到充分抑制，故用于消化性溃疡的辅助治疗。"},{"q":"下列哪种药物为治疗心绞痛的钙拮抗药","o":["硝苯地平","普萘洛尔","硝酸甘油","硝酸异山梨酯","特拉唑嗪"],"a":0,"e":"硝苯地平阻断血管平滑肌L型钙通道，扩张冠脉并降低心脏后负荷，属二氢吡啶类钙拮抗药；普萘洛尔为β受体阻断药，硝酸酯类非钙拮抗药。"},{"q":"胰岛素的常用给药途径是","o":["口服","皮下注射","静脉注射","肌内注射","吸入"],"a":1,"e":"胰岛素为多肽，口服易被胃肠蛋白酶破坏，常规经皮下注射给药；酮症酸中毒等急症时改用静脉滴注，吸入制剂非主流途径。"},{"q":"阿司匹林用于防止脑血栓形成时，不用大剂量的原因是","o":["避免胃肠道反应","避免激活血管壁中PG合成酶","避免激活血小板中PG合成酶","避免抑制血管壁中PG合成酶","避免抑制血小板中PG合成酶"],"a":3,"e":"大剂量阿司匹林同时抑制血管壁环氧酶，使抗血小板聚集的PGI2生成减少，反而削弱抗血栓作用；小剂量只抑制血小板TXA2合成，故取小剂量。"},{"q":"属于男性避孕药的是","o":["乙酸棉酚","米非司酮","炔诺酮","甲地孕酮","己烯雌酚"],"a":0,"e":"乙酸棉酚直接损害睾丸生精上皮，使精子生成减少，曾用作男性避孕药；米非司酮为抗孕激素药，炔诺酮、甲地孕酮为孕激素类女用避孕药。"},{"q":"产生副反应的剂量是","o":["半数致死量","治疗量","极量","中毒量","无效量"],"a":1,"e":"副反应是在治疗量下出现的与用药目的无关的反应，故其发生剂量为治疗量；中毒量引起毒性反应，极量则为最大允许剂量。"},{"q":"多奈哌齐口服的生物利用度为100%，这意味着多奈哌齐口服","o":["消除速度缓慢","吸收完全","后血药浓度变化和静脉滴注一致","吸收迅速","代谢缓慢"],"a":1,"e":"生物利用度表示药物进入体循环的程度和速度，达100%说明口服药物全部被吸收入血；消除速度与代谢快慢由半衰期等参数反映。"},{"q":"新生儿使用磺胺类药物易出现胆红素脑病，是因为磺胺类药物","o":["减少胆红素排泄","竞争血浆白蛋白而置换出胆红素","降低血-脑脊液屏障的功能","溶解红细胞","抑制肝药酶"],"a":1,"e":"磺胺类与胆红素竞争血浆白蛋白结合位点，使游离胆红素增多并透过血-脑脊液屏障，新生儿易致胆红素脑病，故新生儿禁用。"},{"q":"肿瘤化疗引起的呕吐选用","o":["阿托品","枸橼酸铋钾","昂丹司琼","乳果糖","甘露醇"],"a":2,"e":"昂丹司琼阻断中枢及外周5-HT3受体，对化疗药引起小肠嗜铬细胞释放5-HT所致的呕吐疗效显著；阿托品、铋剂等无此作用。"},{"q":"下列最常用于表面麻醉的药物是","o":["普鲁卡因","丁卡因","布比卡因","罗哌卡因","甲哌卡因"],"a":1,"e":"丁卡因脂溶性高、穿透力强，对黏膜表面麻醉效果好，为表面麻醉首选；普鲁卡因穿透力弱，布比卡因、罗哌卡因多用于浸润和传导麻醉。"},{"q":"急性严重中毒性感染采用糖皮质激素类药物治疗的用法和疗程是","o":["大剂量突击静注或静滴","一般剂量多次给药","大剂量肌肉注射","大剂量口服","隔日疗法"],"a":0,"e":"急性严重中毒性感染需迅速控制症状，采用大剂量糖皮质激素突击静注或静滴，疗程一般不超过3日，症状控制后即停，不需长期维持。"},{"q":"下列何药用于治疗鳞状上皮癌疗效最好","o":["6-MP","5-FU","VCR","BLM","CTX"],"a":3,"e":"博来霉素对鳞状上皮癌疗效突出，可用于头颈部、食管、肺等鳞癌；氟尿嘧啶偏重消化道腺癌，长春新碱用于白血病及淋巴瘤。"},{"q":"下列药物中，能阻断甲硫氨酸脑啡肽生理学活性的是","o":["亮氨酸脑啡肽","吗啡","哌替啶","纳洛酮","喷他佐辛"],"a":3,"e":"纳洛酮为阿片受体竞争性拮抗药，可阻断甲硫氨酸脑啡肽与μ、δ受体结合而取消其效应；吗啡、哌替啶、喷他佐辛均为激动药。"},{"q":"地西泮抗焦虑作用的部位是","o":["脑干网状结构","丘脑","第三脑室周围灰质","大脑边缘系统","大脑导水管周围灰质"],"a":3,"e":"地西泮的抗焦虑作用主要通过作用于大脑边缘系统的苯二氮䓬受体，增强GABA能抑制；脑干网状结构主要与镇静催眠相关。"},{"q":"可增强心肌收缩力及明显舒张肾血管的药物是","o":["肾上腺素","麻黄碱","甲氧明","多巴胺","去甲肾上腺素"],"a":3,"e":"多巴胺激动β1受体增强心肌收缩力，并激动肾血管D1受体使肾血管明显舒张、肾血流增加；去甲肾上腺素则收缩肾血管。"},{"q":"药-时曲线下面积代表","o":["药物血浆半衰期","药物剂量","药物吸收速度","药物排泄量","药物进入循环的相对量"],"a":4,"e":"药-时曲线下面积反映药物进入体循环的相对总量，与吸收程度成正比；它不表示吸收速度、排泄量或半衰期。"},{"q":"性激素受体位于","o":["细胞膜","细胞质","细胞核","线粒体","粗面内质网"],"a":2,"e":"性激素属甾体激素，其受体位于细胞核内，激素进入细胞与核受体结合后调控基因转录，故需数小时才出现效应。"},{"q":"以下哪种药物可以对各型血吸虫病、肠吸虫以及肺吸虫产生有效的治疗效果","o":["甲硝唑","青蒿素","吡喹酮","二氯尼特","乙胺嗪"],"a":2,"e":"吡喹酮使血吸虫体被兴奋、挛缩并破坏皮层，对各型血吸虫病、肠吸虫及肺吸虫均有良效，为广谱抗吸虫首选药。"},{"q":"解热镇痛药的共同作用机制是","o":["抑制脑内γ-氨基丁酸（GABA）合成","抑制多巴胺合成","直接抑制中枢神经系统","减少炎症部位刺激因子合成","抑制前列腺素（PG）的合成"],"a":4,"e":"解热镇痛药抑制环氧酶，减少前列腺素合成，使体温调定点下移并降低痛觉感受器敏感性；对GABA、多巴胺系统无直接作用。"},{"q":"吩噻嗪类抗精神病药引起的帕金森综合征宜选用","o":["左旋多巴","金刚烷胺","司来吉兰","溴隐亭","苯海索"],"a":4,"e":"吩噻嗪类阻断纹状体D2受体致ACh相对亢进，出现帕金森综合征，宜用中枢抗胆碱药苯海索；此时左旋多巴无效且可加重精神症状。"},{"q":"ACEI使用中被迫停药的主因是","o":["低血糖","阳痿","体位性高血压","刺激性干咳","头痛、潮红"],"a":3,"e":"ACEI减少缓激肽降解，缓激肽在肺内蓄积刺激气道引起刺激性干咳，为最常见的被迫停药原因；改用ARB后咳嗽少见。"},{"q":"关于苯二氮䓬类的中枢作用机制，以下说法正确的是","o":["作用于GABAB受体","抑制GABA与其受体结合","增加Cl-通道开放频率","延长Cl-通道开放时间","引起神经元细胞膜去极化"],"a":2,"e":"苯二氮䓬类作用于GABA-A受体上的BZ位点，增强GABA亲和力，使Cl-通道开放频率增加而超极化；巴比妥类则延长通道开放时间。"},{"q":"介导吗啡镇痛效应的主要阿片受体是","o":["α受体","β受体","δ受体","κ受体","μ受体"],"a":4,"e":"吗啡激动μ受体产生强大镇痛、呼吸抑制和欣快感，μ受体是介导其镇痛效应的主要受体；δ、κ受体作用较弱。"},{"q":"治疗链激酶过量所致的出血宜选用","o":["右旋糖酐","垂体后叶素","维生素K","氨甲苯酸","鱼精蛋白"],"a":3,"e":"链激酶激活纤溶酶原使纤维蛋白溶解而致出血，氨甲苯酸抑制纤溶酶原激活，可对抗其出血；鱼精蛋白仅拮抗肝素。"},{"q":"哌唑嗪的降压作用主要是","o":["激动中枢与外周α2受体","妨碍递质贮存而使递质耗竭","减少血管紧张素Ⅱ的作用","选择性的阻断α1受体的作用","直接扩张血管"],"a":3,"e":"哌唑嗪选择性阻断血管平滑肌α1受体，舒张小动脉而降压，不阻断突触前α2受体，故少有反射性心动过速。"},{"q":"下列药物中脑血管扩张性偏头痛宜选用的是","o":["硝苯地平","尼群地平","非洛地平","尼索地平","尼莫地平"],"a":4,"e":"尼莫地平脂溶性高，易透过血-脑脊液屏障，选择性扩张脑血管，用于脑血管痉挛及血管性头痛；其他二氢吡啶类以外周降压为主。"},{"q":"下列关于我国古代药物学著作对应正确的是","o":["孙思邈——《神农本草经》","华佗——《新修本草》","张仲景——《千金要方》","李时珍——《本草纲目》","扁鹊——《千金翼方》"],"a":3,"e":"李时珍著《本草纲目》，为本草学集大成之作；《神农本草经》非孙思邈所著，《新修本草》为苏敬等编修，《千金要方》为孙思邈所撰。"},{"q":"青霉素的抗菌作用机制是","o":["与细菌胞浆膜结合，破坏胞浆膜结构","破坏细胞壁使水分内渗","抑制DNA多聚酶，影响DNA的合成","与PBP结合，抑制细菌细胞壁合成","抑制菌体蛋白的合成"],"a":3,"e":"青霉素与细菌胞浆膜上的青霉素结合蛋白结合，抑制转肽酶，阻碍肽聚糖交联，致细胞壁缺损而杀菌。"},{"q":"下列关于拉贝洛尔作用的叙述，正确的是","o":["对β受体的阻断作用强于普萘洛尔","对β1受体有选择性阻断作用","对α受体的阻断作用强于酚妥拉明","多用于治疗中度和重度高血压","常用于心功能不全者"],"a":3,"e":"拉贝洛尔兼有α、β受体阻断作用，对β受体阻断强度弱于普萘洛尔、对α受体弱于酚妥拉明，多用于中度及重度高血压和妊娠高血压。"},{"q":"磺酰脲类药物引起较严重的不良反应是","o":["胃肠道反应","过敏反应","嗜睡","持久性的低血糖反应","粒细胞减少"],"a":3,"e":"磺酰脲类刺激β细胞过量释放胰岛素，可致持久而严重的低血糖，老年及肝肾功能不全者尤易发生，为该类最严重的不良反应。"},{"q":"氨基糖苷类抗生素抑制细菌蛋白质合成的作用点是","o":["只作用于起始阶段","只作用于肽链延伸阶段","只作用于终止阶段","蛋白质合成的全过程","抑制蛋白质的转运"],"a":3,"e":"氨基糖苷类与30S亚基结合，抑制始动、肽链延伸和终止全过程并致密码错译，属静止期杀菌药；大环内酯类仅作用于延伸阶段。"},{"q":"选择性作用于β2受体的药物是","o":["多巴胺","沙丁胺醇","麻黄碱","多巴酚丁胺","氨茶碱"],"a":1,"e":"沙丁胺醇选择性激动β2受体，舒张支气管平滑肌，用于哮喘；多巴胺、麻黄碱、多巴酚丁胺受体选择性差，氨茶碱非受体激动药。"},{"q":"下列关于奎尼丁抗心律失常作用的叙述，错误的是","o":["降低浦肯野纤维自律性","减慢心房、心室和浦肯野纤维传导性","延长心房、心室和浦肯野纤维的动作电位时程和有效不应期","阻滞钠通道，不影响钾通道","对钠通道、钙通道都有抑制作用"],"a":3,"e":"奎尼丁阻滞钠通道，同时抑制钾、钙通道，延长动作电位时程和有效不应期；称其不影响钾通道与其广谱通道阻滞特点不符。"},{"q":"下列疾病中可以使用阿托品治疗的是","o":["青光眼","前列腺增生","心肌缺血","室性心律失常","窦性心动过缓"],"a":4,"e":"阿托品阻断M受体，解除迷走神经对窦房结的抑制，使心率加快，用于窦性心动过缓；青光眼、前列腺增生为其禁忌。"},{"q":"关于肾素-血管紧张素系统（RAS）描述正确的是","o":["RAS仅存在于体液系统中","RAS仅存在于循环系统中","RAS激活可诱导高血压、心肌肥厚等病理过程","肾素由心肌细胞分泌，使血管紧张素原转化成血管紧张素Ⅰ","血管紧张素Ⅱ作用于血管紧张素受体亚型2（AT2），产生血管收缩作用"],"a":2,"e":"循环及局部组织（心肌、血管壁）中均存在RAS，激活后血管紧张素Ⅱ促血管收缩、促心肌肥厚与重构，是高血压和心肌肥厚的病理基础。"},{"q":"可引起乳酸性酸中毒的药物是","o":["胰岛素","格列吡嗪","格列喹酮","氯磺丙脲","二甲双胍"],"a":4,"e":"二甲双胍增加无氧糖酵解、抑制肝糖异生，乳酸生成增多而清除减少，易诱发乳酸性酸中毒，肾功能不全者尤须警惕。"},{"q":"治疗敏感菌引起的急慢性骨及关节感染，宜选用","o":["红霉素","乙酰螺旋霉素","麦白霉素","林可霉素","万古霉素"],"a":3,"e":"林可霉素在骨组织中浓度高，对革兰阳性菌及厌氧菌有效，为急慢性骨髓炎、骨关节感染的首选药物之一；红霉素类骨浓度低。"},{"q":"合理应用双膦酸盐类治疗骨质疏松的注意事项中不包括","o":["应用3～5年后应该考虑药物假期","停用后疗效平稳下降","停用后其抗骨折的作用可以保存数年","使用超过5年，罕见不良反应发生率依然较低","停用双膦酸盐类治疗后，如果骨折风险仍高，可以换用特立帕肽"],"a":3,"e":"双膦酸盐长期使用超过5年，颌骨坏死、非典型股骨骨折等罕见不良反应发生率明显升高，故需设药物假期，并非依然较低。"},{"q":"阿片受体拮抗药为","o":["苯佐那酯","吗啡","喷他佐辛","喷托维林","纳洛酮"],"a":4,"e":"纳洛酮为阿片受体竞争性拮抗药，能迅速逆转吗啡等所致的呼吸抑制和镇痛；苯佐那酯、喷托维林为镇咳药。"},{"q":"下列降血糖的药物中，可造成乳酸血症的是","o":["氯磺丙脲","胰岛素","甲苯磺丁脲","二甲双胍","格列齐特"],"a":3,"e":"二甲双胍抑制肝糖异生并增加外周无氧酵解，使乳酸堆积，可致乳酸血症，禁用于肾功能不全、缺氧及酗酒者。"},{"q":"用于心脏骤停复苏的最佳药物是","o":["去甲肾上腺素","麻黄碱","肾上腺素","多巴胺","间羟胺"],"a":2,"e":"肾上腺素激动β1受体增强心肌收缩、提高窦房结自律性，并收缩外周血管提高冠脉灌注压，为心脏骤停复苏的首选。"},{"q":"乙胺丁醇可致","o":["球后视神经炎","外周神经炎","耳神经损害","中毒性脑病","粒细胞减少症"],"a":0,"e":"乙胺丁醇的主要毒性为球后视神经炎，表现为视力下降、红绿色盲，用药期间应定期查视力和视野；外周神经炎多见于异烟肼。"},{"q":"用于诱导麻醉的药物是","o":["硫喷妥钠","司可巴比妥","苯巴比妥","水合氯醛","氯丙嗪"],"a":0,"e":"硫喷妥钠脂溶性极高，静注后迅速透过血-脑脊液屏障，数十秒即意识消失，常用作诱导麻醉；其余药物无此特点。"},{"q":"小剂量氯丙嗪镇吐作用部位是","o":["延脑呕吐中枢","内耳前庭","胃黏膜感受器","延脑催吐化学感受区","胃肠道"],"a":3,"e":"小剂量氯丙嗪抑制延脑催吐化学感受区的D2受体而镇吐，大剂量才直接抑制呕吐中枢；对前庭刺激所致呕吐无效。"},{"q":"抗菌谱是指","o":["抗菌药物杀灭细菌的强度","抗菌药物抑制细菌的能力","抗菌药物的抗菌程度","抗菌药物一定的抗菌范围","抗菌药物对耐药菌的疗效"],"a":3,"e":"抗菌谱指抗菌药物所能抑制或杀灭病原微生物的范围，反映其抗菌的广窄；抗菌强度由最低抑菌浓度等参数表示。"},{"q":"下列哪项不属于糖皮质激素的禁忌证","o":["曾患严重精神病","新近胃肠吻合术","水痘","非特异性角膜炎","严重糖尿病"],"a":3,"e":"非特异性角膜炎可用糖皮质激素滴眼控制炎症，不属禁忌；曾患严重精神病、新近胃肠吻合术、水痘及严重糖尿病均列为禁忌。"},{"q":"下列哪种药是β-内酰胺酶抑制药","o":["阿莫西林","头孢哌酮","舒巴坦","头孢他啶","氨曲南"],"a":2,"e":"舒巴坦为β-内酰胺酶抑制药，与青霉素类合用可保护后者不被水解；阿莫西林、头孢哌酮属β-内酰胺类抗生素，氨曲南为单环类。"},{"q":"普萘洛尔治疗心绞痛时，可产生下列哪种作用","o":["增加心收缩力，减慢心率","心室容积增大，射血时间延长","扩张冠脉","扩张动脉","抑制心肌收缩力，增快心率"],"a":1,"e":"普萘洛尔阻断β受体使心肌收缩力减弱、心率减慢，心室收缩末期容积增大、射血时间延长，此为治疗心绞痛时的不利一面。"},{"q":"治疗肺炎球菌性肺炎的首选药是","o":["链霉素","四环素","氯霉素","红霉素","青霉素"],"a":4,"e":"肺炎链球菌对青霉素高度敏感，青霉素仍为肺炎球菌性肺炎的首选；链霉素、四环素等疗效差且耐药多见。"},{"q":"8岁以下儿童禁止使用的药物是","o":["氨苄西林","四环素","庆大霉素","头孢克肟","诺氟沙星"],"a":1,"e":"四环素与钙螯合沉积于骨骼和牙釉质，致牙齿黄染、釉质发育不全，8岁以下儿童禁用；诺氟沙星则限18岁以下禁用。"},{"q":"对肠道革兰氏阴性杆菌和铜绿假单胞菌，所产生的多种氨基糖苷类灭活酶稳定的氨基糖苷类抗生素是","o":["卡那霉素","阿米卡星","链霉素","青霉素","妥布霉素"],"a":1,"e":"阿米卡星是卡那霉素的半合成衍生物，对氨基糖苷类灭活酶最稳定，对肠道革兰阴性杆菌及铜绿假单胞菌仍有效。"},{"q":"后遗效应是","o":["血药浓度已降至阈浓度以下时残存的药理效应","血药浓度过高引起的不良反应","血浆蛋白结合率过高引起的不良反应","短期内残存的药理效应","机体产生依赖性引起"],"a":0,"e":"后遗效应指停药后血药浓度已降至阈浓度以下时仍残存的药理效应，如巴比妥类次晨的困倦；与剂量过高或依赖性无关。"},{"q":"治疗流行性脑脊髓膜炎的首选药是","o":["链霉素","四环素","磺胺嘧啶","红霉素","环丙沙星"],"a":2,"e":"磺胺嘧啶易透过血-脑脊液屏障，脑脊液浓度高，为流行性脑脊髓膜炎的首选；青霉素G须大剂量才达有效脑脊液浓度。"},{"q":"直接作用于支气管腺体，促进黏液分泌细胞的溶酶体释出，裂解黏痰中的黏多糖纤维的药物是","o":["N-乙酰半胱氨酸","氯化铵","溴己新","喷托维林","美司坦"],"a":2,"e":"溴己新直接作用于支气管腺体，促使黏液细胞溶酶体释放，裂解痰中黏多糖纤维，使痰液黏度降低而易于咳出。"},{"q":"可用于急性风湿热鉴别诊断的药物是","o":["保泰松","对乙酰氨基酚","阿司匹林","布洛芬","吲哚美辛"],"a":2,"e":"阿司匹林对急性风湿热具解热、镇痛、抗炎及降低血沉作用，用药后症状迅速缓解，故可用于风湿热的鉴别诊断。"},{"q":"下列药物中降低血浆胆固醇作用最明显的是","o":["烟酸","他汀类","贝特类","抗氧化剂","多烯脂肪酸类"],"a":1,"e":"他汀类抑制HMG-CoA还原酶，减少肝内胆固醇合成并上调LDL受体，降低血浆胆固醇作用最强，为高胆固醇血症首选。"},{"q":"下列药物中半衰期最长的二氢吡啶类药物是","o":["硝苯地平","尼莫地平","氨氯地平","尼群地平","尼索地平"],"a":2,"e":"氨氯地平与钙通道结合及解离均慢，t1/2达35～50小时，为二氢吡啶类中半衰期最长者；硝苯地平、尼群地平等t1/2短。"},{"q":"治疗高胆固醇血症的首选药物是","o":["低分子肝素","氯贝丁酯","烟酸","洛伐他汀","苯扎贝特"],"a":3,"e":"洛伐他汀抑制HMG-CoA还原酶，减少胆固醇合成，为高胆固醇血症的首选药物；贝特类、烟酸以降甘油三酯为主。"},{"q":"下列哪项不符合氨基糖苷类抗生素的特点","o":["对革兰氏阴性杆菌具强大抗菌作用","具有抗菌后效应","干扰细菌核酸合成","抗菌作用为浓度依赖性","口服不吸收"],"a":2,"e":"氨基糖苷类对革兰阴性杆菌作用强、具抗菌后效应、为浓度依赖性杀菌且口服不吸收；其机制为抑制蛋白质合成，不干扰核酸合成。"},{"q":"吗啡镇咳的主要作用部位是","o":["脑室及导水管周围灰质","脑干网状结构","延髓孤束核","中脑盖前核","大脑皮层"],"a":2,"e":"吗啡抑制延髓孤束核的咳嗽中枢而镇咳，对胸膜炎等干咳有效；镇咳剂量即可抑制呼吸，故不作常规镇咳药。"},{"q":"耐药金黄色葡萄球菌感染不宜采用青霉素G治疗，此细菌对青霉素G产生耐药的可能机制是","o":["细胞膜通透性改变","产生乙酰转移酶","菌体内靶位结构改变","产生β-内酰胺酶","产生二氢蝶酸合酶"],"a":3,"e":"耐药金葡菌产生β-内酰胺酶水解青霉素G的β-内酰胺环，使其失去与青霉素结合蛋白结合的能力，故不宜再用青霉素G。"},{"q":"高血压药物治疗的新概念不包括","o":["终身治疗","平稳降压","有效治疗","间断用药","联合用药"],"a":3,"e":"高血压治疗强调终身治疗、平稳降压、有效治疗与联合用药，间断用药会造成血压波动、靶器官损害加重，不属新概念。"},{"q":"组织中的组胺主要存在于","o":["粒细胞","红细胞","肥大细胞","嗜酸细胞","巨噬细胞"],"a":2,"e":"组胺主要储存于肥大细胞和嗜碱性粒细胞的颗粒中，以皮肤、支气管黏膜、肠黏膜及胃黏膜含量最高，释放后引起过敏反应。"},{"q":"毛果芸香碱不能用于治疗","o":["青光眼","虹膜炎","唾液腺功能减退","阵发性心动过速","阿托品中毒"],"a":3,"e":"毛果芸香碱激动M受体，减慢心率并抑制房室传导，禁用于阵发性心动过速；可用于青光眼、虹膜炎及阿托品中毒的解救。"},{"q":"阻碍细胞有丝分裂的抗癌药是","o":["丝裂霉素","氟尿嘧啶","紫杉醇","甲氨蝶呤","氨苯蝶啶"],"a":2,"e":"紫杉醇与微管蛋白结合，抑制微管解聚，使纺锤体不能形成，细胞停止于有丝分裂期；氟尿嘧啶、甲氨蝶呤属抗代谢药。"},{"q":"治疗脑水肿宜选用的药物是","o":["呋塞米","氢氯噻嗪","氨苯蝶啶","螺内酯","阿米洛利"],"a":0,"e":"呋塞米静注后提高血浆渗透压并抑制髓袢升支NaCl重吸收，产生强大利尿和脱水作用，可用于脑水肿的辅助治疗。"},{"q":"硫酸镁不能用于治疗","o":["肠内毒物排出","阻塞性黄疸","高血压危象","子痫","消化性溃疡"],"a":4,"e":"硫酸镁口服导泻、利胆，注射可抗惊厥、降压，用于子痫和高血压危象；其无抑制胃酸及保护胃黏膜作用，不能治疗消化性溃疡。"},{"q":"一旦糖皮质激素与其受体结合，从其受体复合物中解离的是","o":["启动子","热休克蛋白","抑制性蛋白","兴奋性蛋白","大分子蛋白复合物"],"a":1,"e":"糖皮质激素与胞浆受体结合后热休克蛋白解离，受体二聚化转入核内与激素反应元件结合，调节靶基因转录。"},{"q":"下列不属于影响细菌细胞壁合成的抗生素是","o":["青霉素类","头孢菌素类","万古霉素","林可霉素","杆菌肽"],"a":3,"e":"林可霉素抑制细菌蛋白质合成，不影响细胞壁；青霉素类、头孢菌素类、万古霉素及杆菌肽均作用于细胞壁合成。"},{"q":"药物的血浆半衰期（t1/2）是指","o":["稳态血浆药物浓度下降一半的时间","有效血浆药物浓度下降一半的时间","血浆药物浓度下降一半的时间","药物被肝脏转化一半的时间","药物从肾脏排泄一半的时间"],"a":2,"e":"血浆半衰期指血浆药物浓度下降一半所需时间，一级动力学时为一常数，反映药物消除快慢，与给药剂量无关。"},{"q":"有关水蛭素的叙述，正确的是","o":["主要经肝脏代谢失活","过量可用维生素K对抗","口服易吸收","灭活凝血因子Ⅱa、Ⅶa、Ⅸa、Ⅹa","抑制凝血酶活性"],"a":4,"e":"水蛭素为直接凝血酶抑制药，与凝血酶结合并灭活其活性，用于肝素诱导的血小板减少症；过量鱼精蛋白仅部分对抗，维生素K无效。"},{"q":"应用硫脲类抗甲药最需要注意的严重不良反应是","o":["粒细胞缺乏","药物热","甲状腺肿大","突眼加重","甲状腺素缺乏"],"a":0,"e":"硫脲类最严重的不良反应为粒细胞缺乏，多发生于用药后2～3个月，用药期间应定期查血象，出现咽痛发热立即停药。"},{"q":"既可用于活动性结核病的治疗，又可用作预防的药物","o":["乙胺丁醇","环丝氨酸","链霉素","异烟肼","对氨水杨酸"],"a":3,"e":"异烟肼对结核分枝杆菌高度选择、穿透力强，既为活动性结核病联合化疗的核心药物，也可单用于结核病的预防。"},{"q":"吗啡的适应证是","o":["心源性哮喘","支气管哮喘","诊断未明的急腹症","颅内压增高","分娩止痛"],"a":0,"e":"吗啡抑制呼吸、扩张外周血管并减轻心脏前后负荷，用于左心衰所致心源性哮喘；支气管哮喘、颅内压增高及分娩止痛均禁用。"},{"q":"属于抗孕激素类药物的是","o":["米非司酮","黄体酮","己烯雌酚","氯米芬","环丙孕酮"],"a":0,"e":"米非司酮竞争孕激素受体，阻断黄体酮对子宫内膜的支持作用，属抗孕激素药，与米索前列醇合用可终止早孕。"},{"q":"一个效价强度高、效能强的激动剂应是","o":["高脂溶性，短t1/2","高亲和力，高内在活性","低亲和力，低内在活性","低亲和力，高内在活性","高亲和力，低内在活性"],"a":1,"e":"效价强度取决于亲和力，效能取决于内在活性；效价高、效能强即亲和力与内在活性均高，属完全激动药。"},{"q":"下列关于离子通道生理功能，错误的是","o":["维持细胞正常形态和功能完整性","对血管平滑肌的舒缩活动无影响","介导兴奋-收缩偶联和兴奋-分泌偶联","决定细胞的兴奋性、不应性和传导性","参与细胞跨膜信号转导过程"],"a":1,"e":"离子通道维持细胞形态与功能、决定兴奋性、介导兴奋-收缩和兴奋-分泌偶联，并参与跨膜信号转导；血管平滑肌舒缩依赖钙、钾通道。"},{"q":"肝药酶的特点是","o":["专一性高，活性高","专一性高，活性低","专一性低，个体差异大","专一性低，个体差异小","专一性高，个体差异大"],"a":2,"e":"肝药酶主要为CYP450酶系，底物广泛、专一性低，活性受遗传、年龄、药物和食物影响，个体差异大，易发生药物相互作用。"},{"q":"阿卡波糖的药理作用是","o":["减慢碳水化合物水解及产生葡萄糖的速度并延缓葡萄糖的吸收","结合胰岛β细胞膜上的特异性受体，促进胰岛素分泌","改善胰岛素抵抗","促进脂肪组织摄取葡萄糖","促进胰岛素的作用"],"a":0,"e":"阿卡波糖在小肠竞争抑制α-葡萄糖苷酶，减慢淀粉等水解为葡萄糖的速度并延缓其吸收，主要降低餐后血糖。"},{"q":"能促进去甲肾上腺素能神经末梢释放NA的拟肾上腺素药物是","o":["去甲肾上腺素","异丙肾上腺素","新斯的明","麻黄碱","多巴酚丁胺"],"a":3,"e":"麻黄碱促进去甲肾上腺素能神经末梢释放NA，并直接激动α、β受体，作用较肾上腺素持久；新斯的明为胆碱酯酶抑制药。"},{"q":"改善恶性贫血患者的神经症状宜用","o":["叶酸","铁剂","维生素B1","维生素B12","亚叶酸钙"],"a":3,"e":"维生素B12参与甲基丙二酰辅酶A的代谢，缺乏时神经髓鞘受损；恶性贫血的神经症状须用维生素B12，叶酸不能纠正。"},{"q":"小儿发热常选用的药物是","o":["阿司匹林","对乙酰氨基酚","吲哚美辛","吡罗昔康","尼美舒利"],"a":1,"e":"对乙酰氨基酚解热镇痛作用缓和，对胃肠刺激小，不诱发瑞夷综合征，为小儿发热的常用药；阿司匹林可诱发瑞夷综合征。"},{"q":"阿托品抗休克主要是由于","o":["收缩血管，升高血压","兴奋心脏，输出量增加","扩张血管，改善微循环","扩张支气管，缓解呼吸困难","减少休克因子的释放"],"a":2,"e":"阿托品大剂量阻断小血管M受体并抑制汗腺分泌，使血管扩张、微循环改善、组织灌注增加，用于感染中毒性休克。"},{"q":"易渗入骨组织中治疗骨髓炎的有效药物是","o":["红霉素","吉他霉素","克林霉素","阿奇霉素","罗红霉素"],"a":2,"e":"克林霉素在骨组织中浓度高，对金黄色葡萄球菌等革兰阳性菌及厌氧菌有效，宜用于敏感菌所致骨髓炎和骨关节感染。"},{"q":"甲苯磺丁脲降血糖作用的主要机制是","o":["增强胰岛素作用","提高靶细胞的敏感性","刺激胰岛β细胞释放胰岛素","使细胞内cAMP含量减少","抑制胰高血糖素的作用"],"a":2,"e":"甲苯磺丁脲阻断β细胞ATP敏感性钾通道，促细胞外钙内流，刺激胰岛β细胞释放胰岛素而降低血糖。"},{"q":"药物零级动力学消除是指","o":["药物完全消除到零","单位时间内按恒量消除药物","药物消除速度与吸收速度相等","单位时间内按恒比消除药物","血浆浓度达到稳定水平"],"a":1,"e":"零级动力学指药物消除速率与血药浓度无关，单位时间内消除恒定量药物，半衰期随血药浓度升高而延长。"},{"q":"最易引起暂时或永久性耳聋的利尿药是","o":["依他尼酸","布美他尼","呋塞米","氢氧噻嗪","氯酞酮"],"a":0,"e":"依他尼酸的耳毒性在袢利尿药中最强，可致暂时或永久性耳聋，与氨基糖苷类合用更易发生；呋塞米耳毒性相对较轻。"},{"q":"HMG-CoA还原酶抑制剂是","o":["普罗布考","考来烯胺","苯扎贝特","洛伐他汀","氯贝丁酯"],"a":3,"e":"洛伐他汀竞争性抑制HMG-CoA还原酶，减少胆固醇合成；考来烯胺为胆汁酸螯合剂，苯扎贝特、氯贝丁酯属贝特类。"},{"q":"促进药物被动转运的因素里，最普遍的是","o":["药物的跨膜浓度差小","药物油水分布系数小","药物的分子量小","药物的解离度小","药物的脂溶性小"],"a":3,"e":"被动转运顺浓度梯度进行，分子小、脂溶性高、解离度低的药物易透过脂质膜；解离度小使分子型比例高，是最普遍的影响因素。"},{"q":"以下关于曲马多的药理作用，错误的是","o":["较弱的μ受体激动作用","呼吸抑制作用弱","对胃肠道无影响","纳洛酮可完全拮抗其镇痛效应","镇痛效力与喷他佐辛相当"],"a":3,"e":"曲马多激动μ受体并抑制NA、5-HT再摄取，镇痛效力与喷他佐辛相当，呼吸抑制轻；其镇痛作用只能被纳洛酮部分拮抗。"},{"q":"能嵌入到肿瘤细胞DNA双链中影响其功能的药物是","o":["甲氨蝶呤","氟尿嘧啶","阿糖胞苷","放线菌素D","L-门冬酰胺酶"],"a":3,"e":"放线菌素D嵌入DNA双链的鸟嘌呤-胞嘧啶碱基对之间，阻断RNA聚合酶，抑制RNA合成；甲氨蝶呤、氟尿嘧啶属抗代谢药。"},{"q":"奥美拉唑治疗消化性溃疡的作用是","o":["阻断M1胆碱受体，抑制胃酸分泌","阻断H2受体，抑制胃酸分泌","阻断胃泌素受体，抑制胃酸分泌","抑制胃壁细胞H＋泵，抑制胃酸分泌","保护胃黏膜"],"a":3,"e":"奥美拉唑在胃壁细胞泌酸小管转化为活性代谢物，与H+-K+-ATP酶共价结合，不可逆抑制胃酸分泌，作用持久。"},{"q":"引起血压双相反应的药物是","o":["去甲肾上腺素","麻黄碱","肾上腺素","间羟胺","异丙肾上腺素"],"a":2,"e":"肾上腺素激动α受体使皮肤黏膜血管收缩、血压升高，同时激动β2受体舒张骨骼肌血管，总外周阻力下降，故血压呈双相反应。"},{"q":"目前临床上，戊巴比妥主要用于下列哪种情况","o":["抗焦虑","镇静催眠","抗惊厥抗癫痫","中枢性肌肉松弛","内镜检查前"],"a":2,"e":"戊巴比妥脂溶性高、作用快而短，现主要用于抗惊厥及癫痫持续状态的控制；镇静催眠已由苯二氮䓬类取代。"},{"q":"碘化物的急性不良反应是","o":["心绞痛","血管神经性水肿","粒细胞缺乏","甲状腺功能减退","耳毒性"],"a":1,"e":"碘化物的急性不良反应为血管神经性水肿、上呼吸道黏膜水肿及喉头水肿，可致窒息；粒细胞缺乏为硫脲类的不良反应。"},{"q":"梗阻性黄疸引起的出血宜选用哪种药物进行治疗","o":["氨甲苯酸","去甲肾上腺素","维生素K","链激酶","纤维蛋白原"],"a":2,"e":"梗阻性黄疸时胆盐排出受阻，维生素K吸收障碍致凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成不足而出血，补充维生素K可纠正。"},{"q":"普萘洛尔禁用于支气管哮喘的机理是","o":["阻断支气管平滑肌β2受体","阻断支气管平滑肌β1受体","阻断支气管平滑肌α受体","阻断支气管平滑肌M受体","激动支气管平滑肌M受体"],"a":0,"e":"普萘洛尔阻断支气管平滑肌β2受体，使支气管收缩，诱发或加重哮喘，故支气管哮喘患者禁用。"},{"q":"氯丙嗪抗精神病作用机制是阻断","o":["中枢α肾上腺素受体","中枢β肾上腺素受体","中脑边缘叶及中脑皮质通路中DA受体","黑质纹状体通路中的5-HT1受体","中枢M1受体"],"a":2,"e":"氯丙嗪阻断中脑-边缘叶及中脑-皮质通路的D2受体，产生抗精神病作用；阻断黑质-纹状体通路则引起锥体外系反应。"},{"q":"通过干扰细菌蛋白质合成而产生抗菌作用的抗菌药物是","o":["万古霉素","青霉素","多黏菌素","庆大霉素","头孢菌素"],"a":3,"e":"庆大霉素与细菌30S亚基结合，抑制蛋白质合成全过程而杀菌；万古霉素、青霉素、头孢菌素均抑制细胞壁合成。"},{"q":"长期应用有成瘾性的镇咳药是","o":["喷托维林","可待因","氯化铵","苯佐那酯","右美沙芬"],"a":1,"e":"可待因激动延髓孤束核的阿片受体而镇咳，反复使用可成瘾，属麻醉药品管理；右美沙芬、喷托维林无成瘾性。"},{"q":"与丙磺舒竞争肾小管分泌的抗生素是","o":["链霉素","青霉素","多黏菌素B","异烟肼","氯霉素"],"a":1,"e":"青霉素与丙磺舒均经肾小管有机酸转运系统分泌，二者竞争同一载体，丙磺舒可延长青霉素的作用时间。"},{"q":"关于硝酸甘油的作用，哪项是错误的","o":["扩张脑血管","扩张冠状血管","心率减慢","扩张静脉","降低外周阻力"],"a":2,"e":"硝酸甘油扩张静脉和动脉，降低前、后负荷，血压下降反射性引起心率加快而非减慢；扩张冠脉和脑血管亦为其作用。"},{"q":"药动学是研究","o":["药物作用随剂量变化的规律","药物作用随时间变化的规律","药物的体内过程及体内药物浓度随时间变化的规律","药物作用随药物化学结构变化的规律","药物的体内过程及体内药物浓度随剂量变化的规律"],"a":2,"e":"药动学研究药物在体内的吸收、分布、代谢和排泄过程及血药浓度随时间变化的规律；药效学研究药物对机体的作用。"},{"q":"兼有抗利尿素分泌作用的降血糖药是","o":["甲苯磺丁脲","二甲双胍","格列本脲","氯磺丙脲","苯乙双胍"],"a":3,"e":"氯磺丙脲除刺激β细胞分泌胰岛素外，尚促进抗利尿激素释放并增强其作用，可用于尿崩症，为该类药特有作用。"},{"q":"氯霉素的抗菌谱中，不包括","o":["金葡菌","伤寒杆菌","肺炎链球菌","结核分枝杆菌","立克次体"],"a":3,"e":"氯霉素对革兰阳性菌、阴性菌及立克次体有效，对结核分枝杆菌无效；其典型不良反应为骨髓抑制和灰婴综合征。"},{"q":"对普鲁卡因胺的叙述错误的是","o":["作用与奎尼丁相似但较弱","能降低浦肯野纤维的自律性","减慢传导速度","延长有效不应期","较强的抗α受体和抗胆碱作用"],"a":4,"e":"普鲁卡因胺的电生理作用与奎尼丁相似，但抗α受体和抗胆碱作用较弱，称其较强与事实不符；长期用可致红斑狼疮样综合征。"},{"q":"以下属于麻醉前给药的药物是","o":["氯丙嗪","阿托品","琥珀胆碱","氯胺酮","丙泊酚"],"a":1,"e":"麻醉前给阿托品可抑制呼吸道腺体分泌、减少误吸，并拮抗麻醉药所致心动过缓；氯丙嗪、氯胺酮、丙泊酚属麻醉用药。"},{"q":"某药按零级动力学消除，其消除半衰期等于","o":["0.693/Ke","Ke/0.5C0","0.5C0/Ke","Ke/0.5","0.5/Ke"],"a":2,"e":"零级动力学时血药浓度随时间直线下降，降至起始浓度一半所需时间为0.5C0/Ke，与剂量有关而与浓度无关。"},{"q":"下列属于西咪替丁临床适应证的是","o":["严重急性感染","异体器官移植","消化性溃疡","再生障碍性贫血","感染中毒性休克"],"a":2,"e":"西咪替丁阻断胃壁细胞H2受体，抑制基础及夜间胃酸分泌，用于消化性溃疡；器官移植多用环孢素等免疫抑制剂。"},{"q":"氯丙嗪抗精神病作用的主要机制是","o":["阻断黑质-纹状体系统D2受体","阻断中脑-边缘系统和中脑-皮层系统的D2样受体","阻断结节-漏斗系统D2受体","阻断肾上腺素α受体","阻断M胆碱受体"],"a":1,"e":"氯丙嗪阻断中脑-边缘系统和中脑-皮层系统的D2样受体，产生抗精神病作用；阻断结节-漏斗系统则致催乳素分泌增加。"},{"q":"可刺激卵巢滤泡发育和成熟，使其分泌雌激素的物质是","o":["FSH","LH","GnRH","TSH","ACTH"],"a":0,"e":"FSH作用于卵巢颗粒细胞，促进卵泡发育和成熟，并使芳香化酶活性升高、分泌雌激素；LH主要促排卵和黄体形成。"},{"q":"新药Ⅱ期临床试验观察病例不少于","o":["50例","100例","200例","300例","400例"],"a":1,"e":"新药Ⅱ期临床试验为治疗作用的初步评价阶段，要求观察病例不少于100例，以确定疗效和安全性；Ⅳ期为上市后监测。"},{"q":"可强烈促进血小板聚集的是","o":["PGE1","PGI2","TXA2","5-HT","PGF2α"],"a":2,"e":"TXA2由血小板环氧酶合成，是强烈的血小板聚集剂和血管收缩剂；PGI2由血管内皮生成，作用与之相反。"},{"q":"下列药物中对于变异型心绞痛治疗效果最好，并对伴有高血压患者尤为适用的是","o":["硝苯地平","硝酸甘油","普萘洛尔","维拉帕米","硝酸异山梨酯"],"a":0,"e":"硝苯地平扩张冠脉、解除冠脉痉挛，对变异型心绞痛疗效最佳，并降低外周阻力，对合并高血压者尤为适用。"},{"q":"高效利尿药的作用机制是","o":["抑制髓袢升支Na＋-K＋交换","减少近曲小管NaCl的再吸收","抑制髓袢升支髓质部与皮质部Na＋-K＋-2Cl－共转运","作用于髓袢升支皮质部，阻断NaCl再吸收","抑制远曲小管Na＋-K＋交换"],"a":2,"e":"高效利尿药抑制髓袢升支粗段管腔膜Na+-K+-2Cl-共转运子，减少NaCl重吸收，产生强大利尿作用并破坏髓质高渗。"},{"q":"下列可影响递质释放的药物是","o":["毛果芸香碱","地西泮","烟碱","去甲肾上腺素","麻黄碱"],"a":4,"e":"麻黄碱促进去甲肾上腺素能神经末梢释放NA，属影响递质释放的药物；毛果芸香碱、去甲肾上腺素为受体激动药。"},{"q":"下列哪种情况不必首选胰岛素治疗","o":["1型糖尿病","2型糖尿病患者经饮食治疗无效","2型糖尿病患者口服降糖药治疗无效","酮症酸中毒","糖尿病并发严重感染"],"a":1,"e":"2型糖尿病经饮食控制和运动治疗无效时首选口服降糖药，不必立即用胰岛素；1型糖尿病、酮症酸中毒及严重感染须用胰岛素。"},{"q":"出现紧张、忧虑、失眠并伴有心悸、出汗、震颤等症状，下列可以显著改善该症状的药物是","o":["地西泮","苯妥英钠","唑吡坦","水合氯醛","氟马西尼"],"a":0,"e":"该组症状为焦虑伴自主神经功能亢进，地西泮作用于边缘系统苯二氮䓬受体，抗焦虑并缓解心悸、出汗，起效快。"},{"q":"常用舌下给药的药物是","o":["阿司匹林","硝酸甘油","维拉帕米","链霉素","苯妥英钠"],"a":1,"e":"硝酸甘油首过效应强，口服生物利用度不足10%，舌下含服经口腔黏膜吸收入血可迅速起效，故为常用舌下给药药物。"},{"q":"作用快而短暂，不用于治疗，可用于诊断重症肌无力的药物是","o":["新斯的明","毒扁豆碱","毛果芸香碱","依酚氯铵","安贝氯铵"],"a":3,"e":"依酚氯铵为短效胆碱酯酶抑制药，静注后肌无力症状迅速改善，用于重症肌无力的诊断；新斯的明作用持久，用于治疗。"},{"q":"有关肝素的药理作用机制，叙述正确的是","o":["拮抗维生素K","直接灭活凝血因子Ⅱa、Ⅶa、Ⅸa、Ⅹa","增强抗凝血酶Ⅲ的活性","直接与凝血酶结合，抑制其活性","抑制凝血因子的生物合成"],"a":2,"e":"肝素与抗凝血酶Ⅲ结合，使其构象改变、活性增强千倍，灭活凝血酶及Ⅹa等因子；其本身无直接抗凝作用。"},{"q":"只激动M受体的药物是","o":["乙酰胆碱","阿托品","毒扁豆碱","氯贝胆碱","卡巴胆碱"],"a":3,"e":"氯贝胆碱不易被胆碱酯酶水解，选择性激动M受体，对N受体几无作用；卡巴胆碱则M、N受体均激动。"},{"q":"与血浆蛋白结合力较强的两种药物同时应用时，应注意","o":["结合型药物增加，药理作用下降","游离型药物增加，药理活性增加","结合型药物减少，药理活性下降","游离型药物减少，药理活性下降","结合型药物增加，药理活性下降"],"a":1,"e":"两药竞争同一血浆蛋白结合位点，结合力强者将另一药置换，使游离型药物浓度升高、药理活性增强，甚至引起中毒。"},{"q":"第三代头孢菌素的特点不包括","o":["对革兰氏阳性菌作用比第一、二代强","对革兰氏阴性菌包括肠杆菌属和铜绿假单胞菌及厌氧菌有较强的作用","t1/2较长，体内分布广","对肾脏基本无毒性","对β-内酰胺酶有较高稳定性"],"a":0,"e":"第三代头孢菌素对革兰阴性菌及铜绿假单胞菌作用强、对β-内酰胺酶稳定、肾毒性低、t1/2较长，对革兰阳性菌作用弱于第一、二代。"},{"q":"下列药物可用于治疗高钙血症的药物是","o":["呋塞米","氨苯喋啶","乙酰唑胺","噻嗪类","甘露醇"],"a":0,"e":"呋塞米抑制髓袢升支NaCl重吸收，在排钠利尿的同时促进钙排泄，可用于高钙血症；噻嗪类则减少尿钙排出。"},{"q":"能降低地高辛血药浓度的药物是","o":["奎尼丁","苯妥英钠","胺碘酮","维拉帕米","普罗帕酮"],"a":1,"e":"苯妥英钠诱导肝药酶，加速地高辛代谢并减少其肠道吸收，使地高辛血药浓度降低；奎尼丁、胺碘酮则使之升高。"},{"q":"以下关于丁丙诺啡的描述，正确的是","o":["镇痛效力弱于吗啡","呼吸抑制作用强","可用于吗啡成瘾的脱毒治疗","拮抗μ受体","激动κ受体"],"a":2,"e":"丁丙诺啡为μ受体部分激动药，镇痛效力强于吗啡、呼吸抑制较轻，可替代吗啡用于成瘾者的脱毒治疗。"},{"q":"治疗继发性醛固酮增多症的首选药物是","o":["呋塞米","氢氯噻嗪","氨苯喋啶","螺内酯","甘露醇"],"a":3,"e":"螺内酯竞争性拮抗醛固酮受体，抑制远曲小管和集合管的Na+-K+交换，保钾排钠，为继发性醛固酮增多症的首选。"},{"q":"脑内最重要的抑制性神经递质是","o":["5-HT","GABA","ACh","DA","NA"],"a":1,"e":"脑内抑制性递质以γ-氨基丁酸为主，其激动GABAA受体开放氯通道，使神经元超极化而产生抑制；5-HT、ACh、DA、NA均以兴奋性传递为主。"},{"q":"与核蛋白30S亚基结合，阻止氨基酰tRNA进入A位的抗菌药是","o":["氯霉素","林可霉素","庆大霉素","四环素","链霉素"],"a":3,"e":"四环素与核蛋白体30S亚基A位特异性结合，阻止氨基酰tRNA进入A位，抑制肽链延长；氯霉素、林可霉素作用于50S亚基。"},{"q":"某驾驶员患有过敏性鼻炎，工作期间最宜使用","o":["苯海拉明","异丙嗪","曲吡那敏","阿司咪唑","氯苯那敏"],"a":3,"e":"阿司咪唑属第二代H1受体阻断药，不易透过血脑屏障，几无中枢镇静作用，适合驾驶员使用；苯海拉明、异丙嗪、氯苯那敏均易致嗜睡。"},{"q":"多巴胺使肾和肠系膜的血管舒张，是由于","o":["兴奋β受体","直接作用于血管平滑肌","选择性兴奋DA受体","选择性阻断α受体","促组胺释放"],"a":2,"e":"多巴胺选择性激动血管DA1受体，激活腺苷酸环化酶使肾、肠系膜、冠状动脉舒张，肾血流量增加；此作用不被β受体阻断药取消。"},{"q":"苯巴比妥在临床上不用于","o":["镇静、催眠","麻醉","抗惊厥","抗癫痫","中枢性肌松作用"],"a":4,"e":"苯巴比妥具镇静催眠、抗惊厥、抗癫痫及麻醉前给药用途，大剂量只抑制中枢而并不松弛骨骼肌；中枢性肌松作用由地西泮等苯二氮䓬类产生。"},{"q":"绝对口服生物利用度等于","o":["（静脉注射定量药物后AUC/口服等量药物后AUC）×100%","（口服等量药物后AUC/静脉注射定量药物后AUC）×100%","（口服定量药物后AUC/静脉注射定量药物后AUC）×100%","（口服一定药物后AUC/静脉注射定量药物后AUC）×100%","（静脉注射等量药物后AUC/口服定量药物后AUC）×100%"],"a":1,"e":"绝对生物利用度F＝（口服等量药物后AUC／静脉注射后AUC）×100%，以静脉给药为参比，反映药物进入体循环的百分数；两途径须取等量同一药物。"},{"q":"下列关于新斯的明的作用描述正确的是","o":["脂溶性高，易透过血脑屏障进入中枢神经系统","对骨骼肌作用最强，对心血管、腺体作用较弱","对胃肠道和膀胱平滑肌作用较强，可用于前列腺肥大所致尿潴留","滴眼可降低眼内压","可用于解救除极化型肌松药中毒"],"a":1,"e":"新斯的明抑制胆碱酯酶，又对骨骼肌运动终板N2受体有直接兴奋作用，故对骨骼肌作用最强，对心血管、腺体、眼和支气管平滑肌作用较弱。"},{"q":"影响半衰期长短的主要因素是","o":["剂量","吸收速度","原血浆浓度","消除速度","给药时间"],"a":3,"e":"半衰期与消除速率常数成反比，t1/2＝0.693/k，凡影响肝代谢、肾排泄等消除环节的因素均改变半衰期；剂量、吸收速度与给药时间不改变其数值。"},{"q":"以下哪种药物组合对疟原虫有协同治疗作用","o":["青蒿素+乙胺嘧啶","青蒿素+氯喹","青蒿素+甲氟喹","青蒿素+奎宁","氯喹+奎宁"],"a":2,"e":"青蒿素类与甲氟喹配伍可协同抗疟并延缓耐药产生，为疟疾联合用药的常用组合；乙胺嘧啶、氯喹、奎宁与青蒿素的协同性不及甲氟喹。"},{"q":"抗精神病作用强，且锥体外系副作用轻的药物是","o":["氯丙嗪","氯氮平","氟哌啶醇","氯普噻吨","五氟利多"],"a":1,"e":"氯氮平阻断D4与5-HT2A受体，抗精神病作用强而锥体外系反应轻，但可致粒细胞缺乏，需监测血象；氯丙嗪、氟哌啶醇、五氟利多锥体外系反应明显。"},{"q":"目前临床医师推荐常用的抗高血压药不包括","o":["利尿药","钾通道阻滞药","β受体阻断药","ACEI","ARB"],"a":1,"e":"一线降压药为利尿药、β受体阻断药、钙通道阻滞药、ACEI与ARB五类；钾通道阻滞药如米诺地尔仅作二、三线用药，不属推荐常用类别。"},{"q":"化疗药物是指","o":["治疗各种疾病的化学药物","抗菌药物","专门治疗结核病的化学药物","防治病原微生物、寄生虫及恶性肿瘤的化学药物","人工合成的化学药物"],"a":3,"e":"化疗指用化学药物防治病原微生物、寄生虫及恶性肿瘤，与机体细胞密切相关的肿瘤亦属其范围；仅抗菌或仅抗结核均不能概括其定义。"},{"q":"下列药物属于肾素抑制药的是","o":["阿利吉仑","普萘洛尔","卡托普利","氯沙坦","氢氯噻嗪"],"a":0,"e":"阿利吉仑直接抑制肾素，减少血管紧张素原转化为AngⅠ，为口服肾素抑制药；卡托普利抑制ACE，氯沙坦阻断AT1受体，机制均不相同。"},{"q":"金黄色葡萄球菌感染首选的治疗药物是","o":["青霉素G","氨苄西林","苯唑西林","万古霉素","头孢氨苄"],"a":3,"e":"对青霉素耐药的金黄色葡萄球菌感染首选万古霉素，其与细胞壁前体结合、阻碍肽聚糖合成；对青霉素敏感的菌株仍以青霉素G为首选。"},{"q":"某哮喘患者，遵医嘱使用沙丁胺醇治疗哮喘的作用机制是","o":["激动β1受体","激动β2受体","阻断β1受体","阻断β2受体","阻断M受体"],"a":1,"e":"沙丁胺醇选择性激动支气管平滑肌β2受体，激活腺苷酸环化酶使cAMP增多、气道舒张，为哮喘急性发作常用吸入药；对β1受体作用弱，心脏反应轻。"},{"q":"促进胰岛释放胰岛素的药物是","o":["格列苯脲","二甲双胍","阿卡波糖","罗格列酮","苯乙双胍"],"a":0,"e":"格列苯脲属磺酰脲类，阻断胰岛β细胞ATP敏感性钾通道，促细胞去极化、钙内流，触发胰岛素释放；二甲双胍、阿卡波糖、罗格列酮均不促泌。"},{"q":"支原体肺炎首选药物是","o":["青霉素","红霉素","氯霉素","多黏菌素","利福平"],"a":1,"e":"支原体无细胞壁，β-内酰胺类无效；红霉素等大环内酯类抑制50S亚基蛋白质合成，为支原体肺炎首选，亦可选四环素类或氟喹诺酮类。"},{"q":"抗血小板药物不包括","o":["阿司匹林","噻氯匹啶","双嘧达莫","尿激酶","水蛭素"],"a":3,"e":"尿激酶属纤维蛋白溶解药，激活纤溶酶原以溶解已形成的血栓；阿司匹林抑制TXA2、噻氯匹啶阻断P2Y12、双嘧达莫抑制磷酸二酯酶，均为抗血小板药。"},{"q":"具有抗病毒作用的抗帕金森病药物是","o":["左旋多巴","卡比多巴","金刚烷胺","溴隐亭","司来吉兰"],"a":2,"e":"金刚烷胺促进黑质纹状体多巴胺释放，又能阻止病毒脱壳与核酸释放，具抗甲型流感病毒作用；左旋多巴、卡比多巴、溴隐亭、司来吉兰无此作用。"},{"q":"关于吗啡描述错误的是","o":["强而持久的镇痛作用","镇静作用","呼吸抑制","降低胃肠平滑肌张力","引起体位性低血压"],"a":3,"e":"吗啡兴奋胃肠平滑肌及括约肌，使张力升高、蠕动减弱而致便秘，故“降低胃肠平滑肌张力”的说法错误；其镇痛强而持久，并抑制呼吸、致体位性低血压。"},{"q":"普鲁卡因不可用于哪种局麻方式","o":["蛛网膜下腔麻醉","浸润麻醉","表面麻醉","传导麻醉","硬膜外麻醉"],"a":2,"e":"普鲁卡因穿透力弱，不易透过黏膜表面，故不用于表面麻醉，多作浸润、传导、蛛网膜下腔及硬膜外麻醉；表面麻醉宜用丁卡因或利多卡因。"},{"q":"连续服用巴比妥类药物，突然停药，易发生","o":["成瘾性","反跳现象","睡眠改善","呼吸抑制","习惯性"],"a":1,"e":"巴比妥类长期使用产生耐受性与依赖性，突然停药出现焦虑、失眠加重、震颤甚至惊厥，称反跳现象，故须逐渐减量停药。"},{"q":"去甲肾上腺素用于上消化道出血时采用的给药方式是","o":["稀释后口服","皮下注射","静脉注射","肌肉注射","静脉滴注"],"a":0,"e":"去甲肾上腺素稀释后口服，经食管黏膜吸收、经门静脉入肝代谢，收缩局部血管而止血，用于食管胃底静脉破裂出血；注射给药不能达到局部高浓度。"},{"q":"对非甾体类抗炎药引起的消化性溃疡，有特效的药物是","o":["米索前列醇","昂丹司琼","硫糖铝","多潘立酮","三硅酸镁"],"a":0,"e":"米索前列醇为PGE1衍生物，可补充NSAIDs抑制前列腺素合成所致的黏膜保护缺失，促进溃疡愈合，对NSAIDs相关溃疡疗效显著。"},{"q":"阿司匹林用于防治血栓形成的机理是","o":["直接抑制磷脂酶","减少花生四烯酸的堆积","抑制PG合成酶，使TXA2合成减少","直接抑制PGI2生成","直接对抗PG"],"a":2,"e":"阿司匹林不可逆乙酰化血小板环氧化酶即PG合成酶，使TXA2生成减少而抑制血小板聚集；血管内皮PGI2合成可恢复，故小剂量即有效。"},{"q":"氨基糖苷类对下列那类细菌不敏感","o":["大肠埃希菌","铜绿假单胞菌","克雷伯菌","耐甲氧西林金黄色葡萄球菌","厌氧菌"],"a":4,"e":"氨基糖苷类为静止期杀菌药，其跨膜转运依赖氧依赖性主动过程，厌氧菌缺乏该摄取系统故天然耐药；对大肠埃希菌、铜绿假单胞菌、克雷伯菌均敏感。"},{"q":"以下哪种小分子化合物不是多靶点的抗肿瘤药物","o":["索拉非尼","舒尼替尼","厄洛替尼","克唑替尼","拉帕替尼"],"a":2,"e":"厄洛替尼为选择性EGFR酪氨酸激酶抑制剂，作用靶点单一；索拉非尼、舒尼替尼、克唑替尼、拉帕替尼均同时抑制多个激酶靶点。"},{"q":"可用于肾上腺嗜铬细胞瘤鉴别诊断的药物是","o":["育亨宾","酚妥拉明","硝普钠","可乐定","普萘洛尔"],"a":1,"e":"酚妥拉明阻断α受体，静脉注射后血压下降，用于嗜铬细胞瘤的鉴别诊断及术前准备；可乐定、普萘洛尔作用相反，硝普钠为非选择性血管扩张药。"},{"q":"普萘洛尔的禁忌证不包括","o":["严重左室心功能不全","窦性心动过缓","支气管哮喘","重度房室传导阻滞","稳定型心绞痛"],"a":4,"e":"普萘洛尔禁用于严重左室功能不全、窦性心动过缓、重度房室传导阻滞及支气管哮喘；稳定型心绞痛为其适应证，用药可降低心肌耗氧量。"},{"q":"应用华法林时为掌握好剂量，应测定","o":["凝血酶原时间","凝血时间","止血时间","部分凝血质时间","出血时间"],"a":0,"e":"华法林抑制维生素K环氧化物还原酶，阻碍凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成，其中Ⅶ半衰期最短，故以凝血酶原时间及INR监测剂量。"},{"q":"局麻药的作用机制是","o":["局麻药阻碍Ca2＋内流，阻碍复极化","局麻药促进Na＋内流，产生持久去极化","局麻药促进K＋内流，促进复极化","局麻药阻碍Na＋内流，阻碍去极化","局麻药阻碍K＋外流，阻碍去极化"],"a":3,"e":"局麻药阻滞神经细胞膜电压门控钠通道，减少Na＋内流，使动作电位不能产生而阻断冲动传导；对静息电位与钾通道无明显影响。"},{"q":"可用于治疗肝性脑病的药物是","o":["丙环定","溴隐亭","苯海索","卡比多巴","左旋多巴"],"a":4,"e":"左旋多巴易透过血脑屏障，在中枢脱羧生成多巴胺，补充中枢递质，可改善肝性脑病的意识障碍；溴隐亭、苯海索、卡比多巴无此用途。"},{"q":"用药前必须做皮肤过敏试验的局麻药是","o":["罗哌卡因","普鲁卡因","丁卡因","利多卡因","丁哌卡因"],"a":1,"e":"普鲁卡因属对氨基苯甲酸酯类，易致过敏反应，用药前须做皮肤过敏试验；利多卡因、罗哌卡因、丁卡因、丁哌卡因过敏罕见，一般不需皮试。"},{"q":"糖皮质激素类药物隔日疗法宜选用","o":["泼尼松","氟轻松","地塞米松","氢化可的松","曲安西龙"],"a":0,"e":"隔日疗法宜选血浆半衰期较短、对下丘脑-垂体-肾上腺轴抑制较轻的泼尼松，将两日总量于晨间一次顿服；地塞米松半衰期长，不适用。"},{"q":"属于骨吸收抑制药的是","o":["降钙素","甲状旁腺激素","氟化物","钙剂","维生素D"],"a":0,"e":"降钙素抑制破骨细胞活性、减少骨吸收，并促进骨钙沉积，用于骨质疏松与高钙血症；甲状旁腺激素、氟化物属骨形成促进药。"},{"q":"肿瘤化疗后引起的粒细胞缺乏症宜选用","o":["硫酸亚铁","叶酸","非格司亭","红细胞生成素","维生素B12"],"a":2,"e":"非格司亭为重组人粒细胞集落刺激因子，促进中性粒细胞增殖分化，用于化疗后粒细胞缺乏；叶酸、维生素B12、铁剂用于各类贫血。"},{"q":"出现青霉素所致的过敏性休克时，应立即选用","o":["肾上腺素","糖皮质激素","青霉素","苯海拉明","苯巴比妥"],"a":0,"e":"青霉素过敏性休克应立即皮下或肌内注射肾上腺素，激动α受体收缩血管、激动β2受体解除支气管痉挛并兴奋心脏；糖皮质激素与抗组胺药仅作辅助。"},{"q":"毒扁豆碱滴眼后缩瞳的机制是","o":["直接兴奋瞳孔括约肌M受体","直接兴奋睫状肌M受体","直接阻断瞳孔开大肌α受体","促进ACh释放激动M受体","抑制AChE，减少ACh水解"],"a":4,"e":"毒扁豆碱抑制胆碱酯酶，使ACh水解减少、局部堆积而激动瞳孔括约肌M受体，产生缩瞳、降低眼内压及调节痉挛，属间接拟胆碱药。"},{"q":"可用于治疗尿崩症的利尿药是","o":["呋塞米","氢氯噻嗪","螺内酯","氨苯蝶啶","乙酰唑胺"],"a":1,"e":"氢氯噻嗪抑制髓袢升支粗段皮质部Na＋-Cl－共转运体，减少尿液稀释，并降低血浆渗透压、减轻口渴，故可用于肾性尿崩症。"},{"q":"盐皮质激素临床多用于","o":["慢性肾上腺皮质功能减退","糖尿病","甲状腺功能亢进","严重感染/炎症","休克"],"a":0,"e":"盐皮质激素以去氧皮质酮为代表，促进肾远曲小管保钠排钾，主要用于慢性肾上腺皮质功能减退的替代治疗；其无抗炎、抗休克作用。"},{"q":"丁螺环酮抗焦虑的主要作用位点是","o":["GABAA受体","NMDA受体","D2受体","N受体","5-HT1A受体"],"a":4,"e":"丁螺环酮为5-HT1A受体部分激动药，激动突触前自身受体，抗焦虑而不抑制中枢，无镇静与成瘾性；GABAA受体是苯二氮䓬类的作用位点。"},{"q":"下列降压药物中直接抑制血管紧张素转化酶的是","o":["依那普利","缬沙坦","阿利吉仑","利血平","可乐定"],"a":0,"e":"依那普利抑制血管紧张素转化酶，减少AngⅡ生成并减少缓激肽降解；缬沙坦阻断AT1受体，阿利吉仑抑制肾素，利血平耗竭递质。"},{"q":"胸痛剧烈伴刺激性干咳的患者宜选用","o":["喷托维林","可待因","右美沙芬","苯佐那酯","溴己新"],"a":1,"e":"可待因直接抑制延髓咳嗽中枢，镇咳强度约为吗啡的1/4，适用于胸痛伴剧烈干咳，无痰者尤为适宜；喷托维林、右美沙芬镇咳作用较弱。"},{"q":"X药对某受体有亲和力，无内在活性；Y药对该受体既有亲和力，又有内在活性，则X、Y分别是","o":["激动药，拮抗药","拮抗药，激动药","部分激动药，激动药","拮抗药，拮抗药","激动药，激动药"],"a":1,"e":"有亲和力而无内在活性者为拮抗药，占据受体而不激动；既有亲和力又有内在活性者为激动药，与受体结合后产生效应。"},{"q":"不属于碳青霉烯类抗生素的是","o":["硫霉素","亚胺培南","美罗培南","帕尼培南","氨曲南"],"a":4,"e":"氨曲南为单环β-内酰胺类，对革兰阴性菌青霉素结合蛋白亲和力高；硫霉素、亚胺培南、美罗培南、帕尼培南均具青霉烯环，属碳青霉烯类。"},{"q":"治疗青霉素引起的过敏性休克的首选药是","o":["多巴酚丁胺","异丙肾上腺素","去甲肾上腺素","多巴胺","肾上腺素"],"a":4,"e":"肾上腺素激动α受体收缩血管、升高血压，激动β2受体舒张支气管并抑制过敏介质释放，为青霉素过敏性休克的首选急救药。"},{"q":"以下属于骨形成促进药的是","o":["阿仑膦酸钠","甲状旁腺激素","降钙素","替勃龙","雷洛昔芬"],"a":1,"e":"甲状旁腺激素间断小剂量给药可促进成骨细胞活动、增加骨形成，用于严重骨质疏松；阿仑膦酸钠、降钙素抑制骨吸收。"},{"q":"新斯的明最显著的药理作用是","o":["减慢心率","促进腺体分泌","兴奋骨骼肌","兴奋中枢","降低眼内压"],"a":2,"e":"新斯的明抑制胆碱酯酶并对运动终板N2受体有直接激动作用，故兴奋骨骼肌作用最显著，用于重症肌无力、术后腹气胀与尿潴留。"},{"q":"下列不属于麦角生物碱类药物的适应证的是","o":["产后止血","子宫复原","偏头痛","催产引产","人工冬眠"],"a":3,"e":"麦角生物碱用于产后止血、子宫复原、偏头痛及组成冬眠合剂；其引起子宫强直收缩，禁用于催产引产，故不属其适应证。"},{"q":"激动H2受体产生的效应是","o":["胃肠平滑肌收缩","支气管平滑肌收缩","胃壁细胞胃酸分泌增多","心房收缩增强，房室结传导减慢","瞳孔缩小"],"a":2,"e":"H2受体激动使胃壁细胞cAMP增多、质子泵激活，胃酸分泌增加；西咪替丁等H2受体阻断药据此抑制基础胃酸与夜间胃酸分泌。"},{"q":"急性吗啡中毒的特效解毒药是","o":["洛贝林","尼克刹米","纳洛酮","美沙酮","二甲弗林"],"a":2,"e":"纳洛酮为阿片受体竞争性拮抗药，亲和力强，可迅速逆转吗啡中毒所致昏迷与呼吸抑制，成人常用0.4～0.8mg静脉注射。"},{"q":"育亨宾可选择性阻断","o":["M受体","β1受体","β2受体","α1受体","α2受体"],"a":4,"e":"育亨宾选择性阻断突触前膜α2受体，使NA释放增加，用于阳痿的诊断与治疗；其对α1受体作用极弱。"},{"q":"治疗立克次体感染所致斑疹伤寒首选","o":["四环素","庆大霉素","青霉素","链霉素","多黏菌素"],"a":0,"e":"四环素对立克次体、衣原体、支原体、螺旋体等非典型病原体敏感，为斑疹伤寒的首选药；β-内酰胺类与氨基糖苷类对其无效。"},{"q":"硫酸镁没有下述哪项作用","o":["强心作用","下泻作用","降压作用","利胆作用","中枢抑制作用"],"a":0,"e":"硫酸镁口服导泻、利胆，注射给药抑制中枢、松弛骨骼肌并扩张血管降压，过量时用钙剂拮抗；其无强心作用，反可抑制心肌。"},{"q":"下列二氢吡啶类钙拮抗药中半衰期最长的是","o":["硝苯地平","尼莫地平","氨氯地平","尼群地平","尼索地平"],"a":2,"e":"氨氯地平在二氢吡啶类中半衰期最长，约35～50小时，可每日给药一次；硝苯地平、尼群地平、尼莫地平、尼索地平半衰期均较短。"},{"q":"下列药物的作用靶点和药理作用组合正确的是","o":["舒马普坦-5-HT1A受体——抗焦虑","丁螺环酮-5-HT1A受体——抑制食欲","赛庚啶-5-HT2受体——偏头痛","西沙必利-5-HT3受体——胃肠动力","昂丹司琼-5-HT3受体——镇吐"],"a":2,"e":"赛庚啶阻断5-HT2受体，兼有H1受体阻断作用，用于偏头痛预防及荨麻疹、瘙痒症；舒马普坦激动5-HT1B/1D受体治疗偏头痛发作。"},{"q":"有关利多卡因的叙述，错误的是","o":["缩短或不影响浦肯野纤维的动作电位时程","减小动作电位4相去极斜率，降低自律性","使缺血心肌的传导速度加快","主要作用于心室肌和浦氏纤维","仅对室性心律失常有效"],"a":2,"e":"利多卡因阻滞钠通道，使缺血心肌传导速度减慢，故“加快传导”错误；其促K＋外流，缩短浦肯野纤维动作电位时程，降低4相斜率而降低自律性。"},{"q":"几乎无抗炎抗风湿作用的药物是","o":["阿司匹林","对乙酰氨基酚","保泰松","吲哚美辛","布洛芬"],"a":1,"e":"对乙酰氨基酚抑制中枢前列腺素合成而解热镇痛，对外周环氧化酶作用弱，几乎无抗炎抗风湿作用；阿司匹林、吲哚美辛、布洛芬抗炎作用明显。"},{"q":"竞争性抑制磺胺类药物抗菌作用的是","o":["PABA","6-APA","TMP","7-ACA","GABA"],"a":0,"e":"磺胺类与PABA结构相似，竞争性抑制细菌二氢蝶酸合酶，阻碍二氢叶酸合成；PABA增多可竞争性拮抗其抗菌作用。"},{"q":"下列属于抗癫痫药物的作用机制的是","o":["增强乙酰胆碱的作用","增强γ-氨基丁酸的作用","阻断儿茶酚胺的作用","阻断天冬氨酸的作用","阻断多巴胺的作用"],"a":1,"e":"抗癫痫药通过增强GABA介导的抑制或阻滞钠、钙通道而降低神经元异常放电，如苯二氮䓬类增强GABAA受体功能；增强胆碱能作用反促发惊厥。"},{"q":"阿糖胞苷抗代谢作用机制是","o":["阻止嘧啶核苷酸合成","抑制DNA多聚酶","抑制二氢叶酸还原酶","抑制核苷酸还原酶","抑制拓扑异构酶"],"a":1,"e":"阿糖胞苷在体内磷酸化为三磷酸阿糖胞苷，抑制DNA多聚酶并掺入DNA链，阻碍DNA合成，属嘧啶类抗代谢药，主用于急性粒细胞白血病。"},{"q":"氨基糖苷类抗生素用于治疗泌尿系统感染，是因为","o":["对尿道感染常见致病菌敏感","大量原形药物由肾排出","使肾皮质激素分泌增加","对肾毒性低","尿碱化可提高疗效"],"a":1,"e":"氨基糖苷类口服吸收少，静脉给药后约90%以原形经肾小球滤过排出，尿中浓度高，故对尿路感染有效；其肾毒性源于肾小管蓄积。"},{"q":"血浆蛋白低下的老年人，应用两种能与血浆白蛋白高度结合的药物时，应注意","o":["降低一种药物剂量","增加一种药物剂量","两种药物剂量都要适当减少","两种药物剂量都要增加","两种药物剂量不变"],"a":2,"e":"血浆白蛋白减少使游离型药物增多、作用增强甚至中毒，两药均高度结合时又竞争同一结合位点，故两种药物剂量都应适当减少。"},{"q":"下列属于非选择性钙通道阻滞药的一组药物是","o":["奎尼丁、普萘洛尔、氟桂利嗪","尼莫地平、哌克昔林、氟桂利嗪","地尔硫䓬、哌克昔林、普尼拉明","维拉帕米、地尔硫䓬、硝苯地平","普尼拉明、哌克昔林、氟桂利嗪"],"a":4,"e":"非选择性钙通道阻滞药包括普尼拉明、哌克昔林与氟桂利嗪，对血管和心脏钙通道均有作用；维拉帕米、地尔硫䓬、硝苯地平为选择性阻滞药。"},{"q":"下列药物长期使用可引起高钾血症的是","o":["氢氯噻嗪","呋塞米","甘露醇","氨苯蝶啶","乙酰唑胺"],"a":3,"e":"氨苯蝶啶阻断远曲小管和集合管钠通道，保钾排钠，长期使用可致高钾血症；氢氯噻嗪、呋塞米、乙酰唑胺均致低钾，甘露醇为渗透性利尿药。"},{"q":"下列不能通过口服途径给药的药物是","o":["青霉素G","青霉素V","氨苄西林","头孢氨苄","头孢拉定"],"a":0,"e":"青霉素G不耐酸，口服易被胃酸破坏且吸收不规则，须注射给药；青霉素V、氨苄西林、头孢氨苄、头孢拉定均耐酸，可口服。"},{"q":"新斯的明用于重症肌无力，是由于","o":["对中枢的兴奋作用","增加乙酰胆碱的合成","兴奋骨骼肌中的M受体","抑制胆碱酯酶和兴奋骨骼肌","促进Ca2+内流"],"a":3,"e":"新斯的明抑制胆碱酯酶使ACh堆积，又直接激动运动终板N2受体，增强骨骼肌收缩力，故可改善重症肌无力；其对中枢作用弱。"},{"q":"治疗强心苷中毒引起的窦性心动过缓宜选用","o":["阿托品","奎尼丁","普萘洛尔","维拉帕米","氯化钾"],"a":0,"e":"强心苷中毒致窦性心动过缓或房室传导阻滞时，用阿托品阻断M受体，解除迷走神经对窦房结的抑制；氯化钾用于室性早搏等快速型心律失常。"},{"q":"异烟肼抗结核杆菌的机制是","o":["破坏细菌细胞壁","影响细菌胞质膜的通透性","抑制细胞核酸代谢","抑制细菌分枝菌酸合成","抑制DNA螺旋酶"],"a":3,"e":"异烟肼抑制结核分枝杆菌的分枝菌酸合成，使细胞壁缺损而杀菌，对繁殖期细菌作用强；其需经菌体内过氧化氢酶激活。"},{"q":"对华法林不正确的论述是","o":["在体内有抗凝作用","可口服","抗凝作用由ATⅢ介导","能防止血栓的形成和扩大","在体外无抗凝作用"],"a":2,"e":"华法林抑制维生素K依赖凝血因子的合成，须体内完整合成系统才起效，体外无抗凝作用；其作用不经ATⅢ介导，ATⅢ是肝素抗凝的介导物。"},{"q":"硝苯地平的主要作用机制是","o":["阻滞钠通道","阻滞钾通道","阻滞钙通道","促进NO生成","减少血管紧张素生成"],"a":2,"e":"硝苯地平阻滞L型钙通道，减少Ca2＋内流，使血管平滑肌舒张、外周阻力下降而降压；对钠、钾通道无阻滞作用。"},{"q":"静脉注射某药，引起心率加快，平均血压无变化，瞳孔散大，皮肤干燥，该药物可能是","o":["α受体激动药","β受体激动药","M受体阻断药","N受体阻断药","M受体激动药"],"a":2,"e":"阻断M受体使瞳孔括约肌松弛而散瞳、腺体分泌减少致皮肤干燥，并解除迷走神经对心脏的抑制使心率加快；血压无明显变化符合阿托品样作用。"},{"q":"琥珀胆碱用于气管镜操作时，其给药途径是","o":["口服","静脉注射","肌内注射","皮下注射","吸入"],"a":1,"e":"琥珀胆碱为去极化型肌松药，静脉注射后约1分钟起效、维持时间短，适用于气管镜、气管插管等短时操作；口服无效。"},{"q":"具有降血脂及抗氧化作用的药物是","o":["美伐他汀","烟酸","非诺贝特","普罗布考","吉非贝齐"],"a":3,"e":"普罗布考降低血浆TC和LDL-C，并抑制LDL氧化修饰，具抗氧化作用，用于动脉粥样硬化；他汀类、贝特类、烟酸无此抗氧化特性。"},{"q":"万古霉素不具有下列哪种特点","o":["口服易吸收","抗菌机制为阻碍细菌细胞壁合成","对革兰氏阳性细菌有强大杀菌作用","口服给药用于治疗假膜性肠炎","较大剂量，可引起听力损害"],"a":0,"e":"万古霉素口服难吸收，仅用于假膜性肠炎等肠道感染，全身感染须静脉滴注；其阻碍细胞壁肽聚糖合成，对革兰阳性菌杀菌力强，大剂量可损听力。"},{"q":"具有中枢性降压作用的药物","o":["可乐定","美卡拉明","利舍平","卡托普利","氢氯噻嗪"],"a":0,"e":"可乐定激动中枢孤束核α2受体和延髓腹外侧区咪唑啉I1受体，减少交感冲动传出而降压；利舍平为耗竭递质，美卡拉明为神经节阻断药。"},{"q":"下列关于异丙肾上腺素作用的叙述，不正确的是","o":["激动β1受体","激动β2受体","收缩冠状动脉","舒张冠状动脉","松弛支气管平滑肌"],"a":2,"e":"异丙肾上腺素激动β1、β2受体，使心率加快、心肌收缩力增强、支气管舒张，其代谢产物腺苷还扩张冠状动脉，故“收缩冠脉”错误。"},{"q":"阿托品解除平滑肌痉挛，疗效最好的是","o":["胆绞痛","肾绞痛","胃肠绞痛","膀胱刺激征","支气管哮喘"],"a":2,"e":"阿托品阻断M受体，解除胃肠平滑肌痉挛的作用最强，用于胃肠绞痛；对胆绞痛、肾绞痛疗效较差，须与阿片类镇痛药合用。"},{"q":"甲氨蝶呤的抗癌作用机制是","o":["抑制二氢叶酸还原酶，干扰核酸合成","抑制二氢蝶酸合成酶，干扰核酸合成","抑制DNA多聚酶，干扰核酸合成","抑制转录酶，干扰核酸合成","抑制胸苷酸合成酶，干扰核酸合成"],"a":0,"e":"甲氨蝶呤与二氢叶酸还原酶结合，使四氢叶酸生成受阻，抑制胸苷酸及嘌呤合成，干扰DNA合成，用于急性白血病等。"},{"q":"苯妥英钠的应用是","o":["抗高血压","抗癫痫，抗心律失常","镇静","治疗窦性心动过速","催眠"],"a":1,"e":"苯妥英钠阻滞钠通道，抑制异常放电的扩散，为癫痫大发作和部分性发作的首选药，也用于强心苷中毒所致室性心律失常。"},{"q":"因短时外科手术使用某肌松药，使用后导致肌肉酸痛的药物是","o":["阿托品","筒箭毒碱","硫喷妥钠","琥珀胆碱","酚妥拉明"],"a":3,"e":"琥珀胆碱使肌细胞去极化时释放钾并引起肌束颤动，术后常出现肩背、胸腹肌肉酸痛，数日自行消失；筒箭毒碱为非去极化型，无此现象。"},{"q":"下列关于钙通道阻滞剂药动学特性，说法正确的是","o":["钙通道阻滞药口服均能吸收，首过效应不明显，因此生物利用度较高","钙通道阻滞药与血浆蛋白结合率较低","维拉帕米、硝苯地平、地尔硫䓬的半衰期较短","氨氯地平的生物利用度较低，一般不超过60%","钙通道阻滞药通常在体内不代谢，通过肾脏排出"],"a":2,"e":"维拉帕米、硝苯地平、地尔硫䓬首过效应明显、半衰期较短，需每日多次给药；氨氯地平半衰期长达35～50小时，生物利用度较高。"},{"q":"某药按一级动力学消除，给药间隔为一个半衰期。为了迅速达到稳态的血药浓度，首次给药剂量应该是常规每次药量的","o":["0.5倍","1倍","2倍","3倍","4倍"],"a":2,"e":"一级动力学药物按恒量比消除，给药间隔等于一个半衰期时，首次给予2倍常规量即负荷剂量，可迅速达到稳态血药浓度。"},{"q":"以下关于非甾体类抗炎药对体温影响的描述，正确的是","o":["使升高的体温恢复到正常水平","使正常体温进一步降低","导致体温调定点下移","使体温调节中枢失灵","增加下丘脑的PGE2合成"],"a":0,"e":"NSAIDs抑制中枢环氧化酶，减少下丘脑PGE2合成，使发热者的体温调定点回落至正常，对正常体温无明显影响。"},{"q":"关于考来烯胺对血脂的影响正确的是","o":["主要降低血浆TG","明显降低血浆HDL","明显降低VLDL，轻度升高HDL","降低血浆TC、LDL-C ，明显升高HDL","降低TC、LDL-C，对HDL影响小"],"a":4,"e":"考来烯胺在肠道与胆酸结合、阻断其重吸收，促使胆固醇转化为胆酸，降低TC和LDL-C，对HDL影响小，也可轻度升高TG。"},{"q":"关于氨茶碱，下列描述哪一项是错误的","o":["可兴奋心脏","为迅速控制哮喘，应快速静脉注射","可兴奋中枢","具有一定的利尿作用","可松弛支气管和其他平滑肌"],"a":1,"e":"氨茶碱安全范围窄，静脉注射须稀释后缓慢推注，快速静注可致心律失常、血压骤降甚至猝死；其可兴奋心脏与中枢、利尿并松弛支气管平滑肌。"},{"q":"用于哮喘预防性治疗及过敏性鼻炎的药物是","o":["沙丁胺醇","氨茶碱","色甘酸钠","肾上腺素","异丙托溴铵"],"a":2,"e":"色甘酸钠稳定肥大细胞膜，抑制抗原激发时的脱颗粒与介质释放，用于哮喘预防性治疗及过敏性鼻炎；对已发作的哮喘无效。"},{"q":"关于强心苷的论述，下述哪项是错误的","o":["口服吸收率与极性成反比","安全范围小，易中毒","治疗量可有心电图改变","具有负性频率作用","对肺源性心脏病的心力衰竭疗效最好"],"a":4,"e":"强心苷对伴心房颤动或心室率快的心力衰竭疗效最好，对肺源性心脏病心衰疗效差且易中毒；其口服吸收率与极性成反比，安全范围小，治疗量即可致心电图改变。"},{"q":"局麻药中加用肾上腺素能达到的目的是","o":["加快局麻药的吸收速率","提高血内局麻药浓度","延长局麻药维持时间","减少腺体分泌以防误吸","增加腺体分泌"],"a":2,"e":"局麻药液中加微量肾上腺素收缩局部血管，延缓药物吸收、延长局麻作用时间并减少吸收中毒，与腺体分泌无关。"},{"q":"不具有肾毒性的药物是","o":["头孢唑林","磺胺嘧啶","庆大霉素","多黏菌素","青霉素"],"a":4,"e":"青霉素主要经肾小管分泌排泄，对肾无明显毒性；头孢唑林、磺胺嘧啶、庆大霉素、多黏菌素均可损害肾脏。"},{"q":"金黄色葡萄球菌引起的急慢性骨髓炎最好选用","o":["阿莫西林","红霉素","头孢曲松","克林霉素","克拉霉素"],"a":3,"e":"克林霉素对金黄色葡萄球菌等革兰阳性菌作用强，且易渗入骨组织、骨内浓度高，为金葡菌所致急慢性骨髓炎的首选药。"},{"q":"中枢抗胆碱药物中毒解救宜用","o":["新斯的明","毒扁豆碱","吡斯的明","依酚氯铵","安贝氯铵"],"a":1,"e":"毒扁豆碱为叔胺类抗胆碱酯酶药，脂溶性高，易透过血脑屏障，可拮抗中枢抗胆碱药中毒所致谵妄与昏迷；新斯的明等季铵类不入脑。"},{"q":"关于普萘洛尔的抗心律失常作用机制，下列描述错误的是","o":["延长房室结有效不应期","治疗剂量延长浦肯野纤维的动作电位时程和有效不应期","阻断心脏β受体","降低窦房结、浦肯野纤维的自律性","降低儿茶酚胺所致的迟后除极幅度，防止触发活动"],"a":1,"e":"普萘洛尔治疗量并不延长浦肯野纤维的动作电位时程和有效不应期，该说法错误；其阻断β受体，减慢4相除极而降低自律性。"},{"q":"下列平喘药中属于M胆碱受体阻断药是","o":["特布他林","丙酸倍氯米松","酮替芬","异丙托溴铵","克伦特罗"],"a":3,"e":"异丙托溴铵为吸入性M胆碱受体阻断药，阻断气道平滑肌M3受体而舒张支气管，用于慢性阻塞性肺疾病；特布他林、克伦特罗为β2受体激动药。"},{"q":"治疗闭角型青光眼应选用","o":["筒箭毒碱","乙酰胆碱","琥珀胆碱","毛果芸香碱","新斯的明"],"a":3,"e":"毛果芸香碱直接激动瞳孔括约肌M受体使瞳孔缩小，虹膜根部变薄、前房角扩大，房水回流增加而降低眼内压，为闭角型青光眼首选。"},{"q":"阵发性室上性心动过速并发变异型心绞痛，宜采用的治疗药物是","o":["维拉帕米","利多卡因","普鲁卡因胺","奎尼丁","普萘洛尔"],"a":0,"e":"维拉帕米阻滞钙通道，延长房室结不应期而终止室上性心动过速，又能扩张冠状动脉、解除冠脉痉挛，故适用于并发变异型心绞痛者。"},{"q":"用药剂量过大时，对机体产生的危害性反应称为","o":["后遗效应","变态反应","毒性反应","质反应","特异质反应"],"a":2,"e":"毒性反应指剂量过大或体内蓄积过多时对机体造成的危害性反应，可预知并避免；后遗效应、变态反应与剂量关系不大。"},{"q":"适于治疗铜绿假单胞菌感染的药物是","o":["链霉素","四环素","氯霉素","妥布霉素","卡那霉素"],"a":3,"e":"妥布霉素属氨基糖苷类，对铜绿假单胞菌作用强，为该菌感染的常用药；链霉素、卡那霉素、四环素、氯霉素对其无效或作用弱。"},{"q":"阿托品对眼的作用为","o":["缩瞳，眼内压升高，调节痉挛","扩瞳，眼内压降低，调节痉挛","缩瞳，眼内压降低，调节痉挛","扩瞳，眼内压升高，调节麻痹","缩瞳，眼内压升高，调节麻痹"],"a":3,"e":"阿托品阻断瞳孔括约肌M受体使瞳孔散大，虹膜退向周边、压迫前房角致眼内压升高，并麻痹睫状肌产生调节麻痹。"},{"q":"磺胺类药物抗菌作用机理是","o":["阻碍核酸的功能","阻碍细胞壁的合成","干扰胞浆膜的功能","阻碍蛋白质的合成","竞争二氢蝶酸合酶"],"a":4,"e":"磺胺类与PABA结构相似，竞争性抑制细菌二氢蝶酸合酶，阻碍二氢叶酸合成，使核酸与蛋白质合成受阻而抑菌。"},{"q":"氨基糖苷类抗生素消除的主要途径是","o":["经肝微粒体酶灭活","经肾小管分泌排出","以原形经肾小球滤过排出","与葡糖醛酸结合后经肾排出","经乙酰化灭活"],"a":2,"e":"氨基糖苷类几乎不被代谢，主要经肾小球滤过以原形排出，尿中浓度高；肾功能减退时易蓄积中毒，须调整剂量。"},{"q":"青霉素的抗菌谱不包括","o":["肺炎球菌","脑膜炎双球菌","破伤风杆菌","伤寒杆菌","钩端螺旋体"],"a":3,"e":"青霉素G对多数革兰阳性菌、脑膜炎双球菌、破伤风杆菌及钩端螺旋体有效，对伤寒杆菌等革兰阴性肠道杆菌无效，伤寒宜选氟喹诺酮类或头孢曲松。"},{"q":"下列药物中，预防或治疗脑血管痉挛效果好的是","o":["普萘洛尔","硝苯地平","氟桂利嗪","维拉帕米","地高辛"],"a":2,"e":"氟桂利嗪脂溶性高，易透过血脑屏障，扩张脑血管、解除脑血管痉挛，用于偏头痛预防及蛛网膜下腔出血后的脑血管痉挛。"},{"q":"可激动N受体的是","o":["醋甲胆碱","毛果芸香碱","毒蕈碱","氯贝胆碱","占诺美林"],"a":0,"e":"醋甲胆碱对M、N受体均有激动作用，可激动神经节N受体；毛果芸香碱、毒蕈碱、氯贝胆碱、占诺美林主要激动M受体。"},{"q":"不属于钙通道阻滞药的是","o":["维拉帕米","地尔硫䓬","米诺地尔","硝苯地平","氟桂利嗪"],"a":2,"e":"米诺地尔为钾通道开放药，使血管平滑肌超极化而舒张降压，不属钙通道阻滞药；维拉帕米、地尔硫䓬、硝苯地平、氟桂利嗪均阻滞钙通道。"},{"q":"氟喹诺酮类药物临床应用广泛，但是要警惕滥用现象，以下不属于它的不良反应是","o":["骨髓抑制","中枢神经系统毒性","心脏毒性","软骨损伤","光敏反应"],"a":0,"e":"氟喹诺酮类可致中枢神经兴奋、心脏QT间期延长、幼年动物软骨损伤及光敏反应，骨髓抑制不是其典型不良反应。"},{"q":"临床上酚妥拉明常采用的给药方式是","o":["直肠给药","雾化吸入","皮下注射","口服","静脉注射"],"a":4,"e":"酚妥拉明口服生物利用度低、作用弱，临床多静脉注射给药，用于血管痉挛性疾病、感染性休克及嗜铬细胞瘤的诊断与术前准备。"},{"q":"下列关于离子通道特征说法正确的是","o":["离子通道有三大特征，离子选择性，门控特性，离子电流特性","某一种离子可以通过大多数通道进行跨膜转运","通道激活，允许某些离子顺浓度差和电位差通过膜","通道失活时通道关闭，外来刺激强可以进入开放状态","通道关闭，遇到刺激后，转为失活状态"],"a":2,"e":"离子通道激活时开放，允许特定离子顺浓度差与电位差跨膜流动而产生离子电流；其具离子选择性、门控性与离子电流三大特征。"},{"q":"解热镇痛药适用于治疗","o":["慢性钝痛","内脏绞痛","分娩止痛","外伤剧痛","术后剧痛"],"a":0,"e":"解热镇痛药具中等程度镇痛作用，对慢性钝痛如头痛、牙痛、关节痛、神经痛有效，对内脏绞痛与创伤剧痛无效。"},{"q":"硝酸酯类药物与普萘洛尔合用治疗心绞痛，下列说法不正确的是","o":["协同降低心肌耗氧量","避免心室容积增加","避免心肌收缩力增强","避免心率加快","避免普萘洛尔抑制心脏"],"a":4,"e":"两药合用可协同降低心肌耗氧量：硝酸酯类缩小心室容积，抵消普萘洛尔所致的心脏增大；普萘洛尔减慢心率，抵消硝酸酯类的反射性心率加快，但不能避免其对心脏的抑制。"},{"q":"苯海拉明不具备的药理作用是","o":["镇静作用","抗胆碱作用","减少胃酸分泌作用","局麻作用","止吐作用"],"a":2,"e":"苯海拉明阻断H1受体，具镇静、抗胆碱、局麻及止吐作用；减少胃酸分泌由H2受体阻断药实现，苯海拉明无此作用。"},{"q":"氟西汀主要的药理作用是","o":["抗抑郁作用","抗躁狂作用","抗精神分裂症作用","催眠作用","抗癫痫作用"],"a":0,"e":"氟西汀选择性抑制突触前膜对5-HT的再摄取，提高突触间隙5-HT浓度而抗抑郁，为SSRI类代表药。"},{"q":"心律失常的治疗方式不包括","o":["药物治疗","安装起搏器","电复律","导管消融","支架手术"],"a":4,"e":"心律失常治疗包括药物、电复律、导管消融与起搏器植入；支架手术用于冠心病冠脉狭窄的再通，不属抗心律失常治疗方式。"},{"q":"利福平的抗菌作用机制是","o":["抗叶酸代谢","抑制细菌细胞壁合成","影响胞质膜通透性","抑制蛋白质合成","抑制核酸代谢"],"a":4,"e":"利福平与细菌DNA依赖的RNA聚合酶β亚单位结合，抑制mRNA转录，阻碍核酸代谢，对结核分枝杆菌及革兰阳性菌均有强大杀菌作用。"},{"q":"丙咪嗪抗抑郁作用机制正确的是","o":["耗竭体内儿茶酚胺","抑制突触前膜对NA和5-HT的再摄取","抑制突出前膜NA的释放","阻断M胆碱受体","中枢兴奋作用"],"a":1,"e":"丙咪嗪阻断突触前膜对NA和5-HT的再摄取，使突触间隙递质浓度升高而抗抑郁；其兼有M受体阻断作用，但非抗抑郁主要机制。"},{"q":"金刚烷胺治疗帕金森的原理是","o":["促多巴胺释放","激动D2受体","抑制胆碱酯酶","阻断中枢M胆碱受体","抑制氨基酸脱羧酶"],"a":0,"e":"金刚烷胺促进黑质纹状体多巴胺能神经元释放多巴胺并减少其再摄取，改善帕金森病症状，其作用不依赖受体激动或胆碱酯酶抑制。"},{"q":"利多卡因降低心肌自律性的机制是","o":["抑制Na＋内流","促进Na＋内流","抑制K＋外流","抑制Ca2＋内流","促进Ca2＋内流"],"a":0,"e":"利多卡因阻滞浦肯野纤维钠通道，减少4相Na＋内流，使4相除极斜率减小、自律性降低，对缺血心肌作用明显。"},{"q":"有关抗血小板药的叙述，正确的是","o":["阿昔单抗是P2Y12受体拮抗药","利多格雷通过促进TXA2合酶活性发挥作用","阿司匹林的剂量超过300mg，抗血小板作用强","双嘧达莫可诱发心绞痛发作","噻氯匹定主要与纤维蛋白原竞争血小板膜糖蛋白受体"],"a":3,"e":"双嘧达莫抑制腺苷摄取使腺苷增多，扩张冠状动脉，可发生冠脉窃血而诱发心绞痛；阿昔单抗为糖蛋白Ⅱb/Ⅲa受体拮抗药，噻氯匹定为P2Y12阻断药。"},{"q":"解热镇痛药的解热特点是","o":["可降低正常体温","可降低直接注入PG引起的发热","仅降低致热原引起的发热","解热作用受环境温度影响","外界温度高可升高体温"],"a":2,"e":"解热镇痛药抑制中枢前列腺素合成，仅使发热者升高的体温降至正常，对正常体温无影响，也不能降低直接注入PG所致的发热。"},{"q":"无内在拟交感活性的选择性β1受体阻断药是","o":["普萘洛尔","美托洛尔","醋丁洛尔","吲哚洛尔","普拉洛尔"],"a":1,"e":"美托洛尔为选择性β1受体阻断药，无内在拟交感活性；普萘洛尔为非选择性，醋丁洛尔、吲哚洛尔、普拉洛尔有内在拟交感活性。"},{"q":"对肾脏毒性最小的头孢菌素是","o":["头孢氨苄","头孢唑林","头孢噻吩","头孢匹罗","头孢呋辛"],"a":3,"e":"头孢匹罗为第四代头孢菌素，对β-内酰胺酶稳定、肾毒性最低；头孢噻吩、头孢唑林等第一代品种肾毒性相对较大。"},{"q":"治疗梅毒首选","o":["氨苄西林","青霉素","四环素","庆大霉素","红霉素"],"a":1,"e":"青霉素G对梅毒螺旋体高度敏感，至今仍是各期梅毒的首选药，常用苄星青霉素肌内注射；青霉素过敏者改用四环素或多西环素。"},{"q":"长期应用广谱抗生素，为预防出血，应补充","o":["铁剂","叶酸","维生素B12","维生素K","维生素C"],"a":3,"e":"广谱抗生素抑制肠道菌群，使维生素K合成减少，凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的γ-羧化受阻而致出血，故应补充维生素K。"},{"q":"阿司匹林哪组作用与相应机制不符","o":["解热作用是抑制中枢PG合成","抗炎作用是抑制炎症部位PG合成","镇痛作用主要是抑制中枢PG合成","水杨酸反应是过量中毒表现","预防血栓形成是抑制TXA2大于PGI2"],"a":2,"e":"阿司匹林的镇痛作用主要是抑制外周炎症部位前列腺素合成、降低痛觉感受器对缓激肽的敏感性，并非抑制中枢PG合成，故该项与机制不符。"},{"q":"某感染中毒性休克患者，伴尿少，宜选用的措施是","o":["地塞米松＋多巴胺＋头孢他啶","地塞米松＋肾上腺素＋螺旋霉素","地塞米松＋硝苯地平＋四环素","地塞米松＋普萘洛尔＋SMZ","地塞米松＋去甲肾上腺素"],"a":0,"e":"感染中毒性休克伴尿少宜用糖皮质激素抗炎抗休克，多巴胺激动DA受体扩张肾血管以增加尿量，并联合对铜绿假单胞菌有效的头孢他啶控制感染。"},{"q":"在胃肠道，脂溶性药物主要的吸收方式是","o":["易化扩散","简单扩散","主动转运","膜孔滤过","胞吞"],"a":1,"e":"脂溶性药物以简单扩散即被动转运方式，顺浓度梯度经脂质双分子层吸收，不需载体与能量，为胃肠道吸收的主要方式。"},{"q":"氢氯噻嗪可引起的不良反应是","o":["低血糖","水和电解质紊乱","高钾血症","低血脂","耳聋"],"a":1,"e":"氢氯噻嗪抑制Na＋-Cl－共转运体，长期使用可致低血钾、低血钠、低氯性碱中毒及血容量不足，即水和电解质紊乱；其还可致高血糖、高血脂。"},{"q":"A B C三药的LD50分别为20 20 30mg/kg，ED50分别为10 20 20mg/kg，则三药的安全性大小顺序为","o":["A＝B＞C","A＞B＝C","A＞B＞C","A＞C＞B","A＜B＜C"],"a":3,"e":"治疗指数为LD50与ED50的比值，A为2、B为1、C为1.5，故安全性顺序为A＞C＞B，指数越大越安全。"},{"q":"作浸润麻醉时，对普鲁卡因过敏者可选用","o":["丁卡因","利多卡因","溴丙胺太林","普鲁卡因胺","对氨基苯甲酸"],"a":1,"e":"对普鲁卡因过敏者作浸润麻醉可改用酰胺类的利多卡因，两者化学结构不同，无交叉过敏；丁卡因同属酯类，可发生交叉过敏。"},{"q":"普萘洛尔治疗心绞痛的主要药理作用是","o":["抑制心肌收缩力，减慢心率","扩张冠脉","降低心脏前负荷","降低左室壁张力","以上都不是"],"a":0,"e":"普萘洛尔阻断心脏β1受体，减慢心率、抑制心肌收缩力、降低心肌耗氧量，从而缓解心绞痛；其无直接扩张冠状动脉作用。"},{"q":"糖皮质激素和抗生素合用治疗严重感染的目的是","o":["增强机体的对疾病的防御能力","增强抗生素的抗菌活性","增强机体应激性","抗毒素、抗休克、缓解毒血症状","拮抗抗生素的副作用"],"a":3,"e":"糖皮质激素抗炎、抗毒素、抗休克，可缓解严重感染的中毒症状并提高机体对缺氧的耐受，同时须用足量抗生素防止感染扩散。"},{"q":"抗心律失常药物的作用机制不包括","o":["降低自律性","减少后除极","延长ERP","消除折返","提高自律性"],"a":4,"e":"抗心律失常药通过降低自律性、减少后除极与触发活动、延长有效不应期、消除折返而发挥作用；提高自律性反而促发心律失常。"},{"q":"以下哪种药物能够对蛔虫、钩虫、蛲虫、鞭虫以及绦虫等多种肠道蠕虫产生良好的治疗效果","o":["哌嗪","甲硝唑","甲苯达唑","恩波吡维胺","吡喹酮"],"a":2,"e":"甲苯达唑抑制虫体微管聚集，阻断葡萄糖摄取与利用，对蛔虫、钩虫、蛲虫、鞭虫及绦虫均有良好疗效，为广谱驱肠虫药。"},{"q":"糖皮质激素类药物对中枢神经具有","o":["镇静作用","抑制作用","兴奋作用","抗抑郁作用","催眠作用"],"a":2,"e":"糖皮质激素提高中枢神经系统兴奋性，可致欣快、失眠、激动甚至精神失常，与镇静抑制作用相反。"},{"q":"哌替啶不引起","o":["恶心，呕吐","便秘","镇静","体位性低血压","呼吸抑制"],"a":1,"e":"哌替啶兴奋胃肠平滑肌作用弱，不引起便秘，也无止泻作用；其可致恶心呕吐、镇静、体位性低血压及呼吸抑制。"},{"q":"与局麻药合用，可延长局麻药作用时间的药物是","o":["肾上腺素","酚妥拉明","麻黄碱","多巴胺","异丙肾上腺素"],"a":0,"e":"肾上腺素收缩局部血管，延缓局麻药吸收，延长其作用时间并降低吸收中毒风险，为局麻药最常配伍的血管收缩药。"},{"q":"用左旋多巴治疗震颤麻痹时，应与下列何药合用","o":["维生素B6","多巴胺","苯乙肼","卡比多巴","多巴脱羧酶"],"a":3,"e":"卡比多巴为外周脱羧酶抑制药，不易入脑，可减少左旋多巴在外周脱羧，使更多药物进入中枢，增强疗效并减轻外周不良反应。"},{"q":"抑制肿瘤细胞脱氧胸苷酸合成酶的药物是","o":["甲氨蝶呤","氟尿嘧啶","阿糖胞苷","放线菌素D","L-门冬酰胺酶"],"a":1,"e":"氟尿嘧啶在体内转化为氟尿嘧啶脱氧核苷酸，抑制胸苷酸合成酶，阻断脱氧胸苷酸生成、干扰DNA合成，属嘧啶类抗代谢药。"},{"q":"治疗罕见真菌感染的首选药物是","o":["伊曲康唑","氟康唑","咪康唑","酮康唑","氟胞嘧啶"],"a":0,"e":"伊曲康唑为三唑类广谱抗真菌药，对深部真菌及少见、罕见真菌感染均有较好疗效，为治疗罕见真菌感染的首选药。"},{"q":"治疗白喉杆菌感染的首选药是","o":["青霉素","红霉素","四环素","氯霉素","庆大霉素"],"a":0,"e":"白喉杆菌对青霉素G敏感，青霉素为首选，并应同时注射白喉抗毒素中和外毒素；青霉素过敏者可改用红霉素。"},{"q":"关于阿司匹林的不良反应，错误的叙述是","o":["胃肠道反应最为常见","凝血障碍，术前1周应停用","过敏反应，哮喘、慢性荨麻疹患者不宜用","水钠潴留，引起局部水肿","水杨酸反应是中毒表现"],"a":3,"e":"阿司匹林不引起水钠潴留和水肿，该反应见于保泰松、吲哚美辛等；其不良反应为胃肠道反应、凝血障碍、过敏反应及水杨酸反应。"},{"q":"属于抗雌激素类药物的是","o":["氯米芬","己烯雌酚","黄体酮","米非司酮","环丙孕酮"],"a":0,"e":"氯米芬为雌激素受体部分激动药，阻断下丘脑雌激素负反馈，促促性腺激素释放而诱发排卵，属抗雌激素药；米非司酮为抗孕激素药。"},{"q":"甲状腺素的主要适应证是","o":["甲状腺危象","轻、中度甲状腺功能亢进","甲亢的手术前准备","交感神经活性增强引起的病变","黏液性水肿"],"a":4,"e":"甲状腺素用于甲状腺功能减退的替代治疗，黏液性水肿为其典型适应证；甲状腺危象与甲亢须用抗甲状腺药，术前准备亦不用甲状腺素。"},{"q":"红霉素是下列哪种细菌感染的首选药","o":["溶血链球菌","金黄色葡萄球菌","军团菌","沙眼衣原体","大肠杆菌"],"a":2,"e":"红霉素等大环内酯类对军团菌、支原体、衣原体及百日咳鲍特菌作用强，为军团菌肺炎的首选药；溶血链球菌感染则首选青霉素。"},{"q":"药物的pKa是指","o":["药物完全解离时的pH","药物解离30%时的pH","药物解离50%时的pH","药物解离80%时的pH","药物未解离时的pH"],"a":1,"e":"官方答案为【药物解离30%时的pH】，但依据教材，正确答案为【药物解离50%时的pH】。pKa是弱酸或弱碱药物解离达50%时的pH，此时解离型与非解离型浓度相等。"},{"q":"卡托普利的降压作用与下列哪种机制无关","o":["抑制整体RAAS的AngⅡ形成","减少AngⅡ的对AT1受体的激动","加速缓激肽的水解","减少P物质的水解","促进前列腺素的合成"],"a":2,"e":"卡托普利抑制血管紧张素转化酶，减少AngⅡ生成，同时抑制激肽酶Ⅱ使缓激肽降解减少、水解减慢，故“加速缓激肽水解”与其降压机制无关。"},{"q":"异丙肾上腺素没有下述哪种作用","o":["松弛支气管平滑肌","激动β受体","收缩支气管黏膜血管","促使ATP转变为cAMP","抑制组胺等过敏性介质释放"],"a":2,"e":"异丙肾上腺素激动β受体，舒张支气管平滑肌并抑制过敏介质释放；收缩支气管黏膜血管由α受体介导，该药无α受体作用。"},{"q":"硝苯地平常见的不良反应是","o":["心率减慢","降低心肌耗氧量","面红、头痛","皮疹","失眠"],"a":2,"e":"硝苯地平扩张外周血管，反射性心率加快，常见面部潮红、头痛、踝部水肿及心悸；降低心肌耗氧量属药理作用而非不良反应。"},{"q":"下列抗高血压药物不良反应错误的是","o":["哌唑嗪——首次用药发生了体位性低血压","可乐定——突然停药而发生的反跳性高血压危象","利舍平——抑郁性精神病","氢氯噻嗪——低血钾","氯沙坦——低血钾"],"a":4,"e":"氯沙坦阻断AT1受体，减少醛固酮分泌，可致高钾血症而非低血钾；氢氯噻嗪致低血钾，哌唑嗪首次用药可致体位性低血压。"},{"q":"氯丙嗪引起的口干、便秘和视力模糊是由于","o":["阻断M胆碱受体","阻断α肾上腺素受体","阻断组胺受体","阻断β肾上腺素受体","阻断DA受体"],"a":0,"e":"氯丙嗪阻断M胆碱受体，出现口干、便秘、视力模糊及尿潴留；其阻断α受体致体位性低血压，阻断DA受体产生锥体外系反应。"},{"q":"容易导致灰婴综合征，新生儿、早产儿、孕妇、哺乳期妇女禁用的抗菌药物是","o":["阿司匹林","磺胺嘧啶","氯霉素","左氧氟沙星","庆大霉素"],"a":2,"e":"氯霉素抑制细菌蛋白质合成，新生儿肝脏葡萄糖醛酸转移酶不足、肾脏排泄能力差，易致血药浓度过高而发生灰婴综合征，故新生儿、早产儿及孕妇、哺乳期妇女禁用。"},{"q":"Vaughan Williams分类法中的Ⅲ类抗心律失常药是","o":["钠通道阻滞药","β受体阻滞药","钙通道阻滞药","延长动作电位时程药","腺苷"],"a":3,"e":"Vaughan Williams分类中Ⅰ类阻滞钠通道，Ⅱ类为β受体阻滞药，Ⅲ类为延长动作电位时程药，Ⅳ类为钙通道阻滞药，胺碘酮、索他洛尔属Ⅲ类。"},{"q":"机体连续多次用药后对药物的反应性降低，该现象称为","o":["依赖性","耐药性","耐受性","后遗效应","继发反应"],"a":2,"e":"耐受性指连续多次用药后机体对药物反应性降低，需加大剂量才能维持原效应；耐药性则针对病原体或肿瘤细胞，二者概念不同。"},{"q":"瘤型麻风杆菌感染治疗的首选药是","o":["异烟肼","氨苯砜","利福平","链霉素","氯法齐明"],"a":4,"e":"氯法齐明对瘤型麻风杆菌有较强杀菌作用，并能抑制麻风结节性红斑反应，为瘤型麻风及麻风反应的首选药，常与氨苯砜、利福平联合应用。"},{"q":"强心苷中毒引起的心律失常，不宜用氯化钾的是","o":["房室结性心动过速","室性心动过速","室性期前收缩","房室传导阻滞","房性心动过速"],"a":3,"e":"强心苷中毒时细胞外钾升高可加重房室传导阻滞，故伴房室传导阻滞者禁用氯化钾；室性期前收缩、室性心动过速等异位节律则可用钾盐纠正。"},{"q":"预防严重创伤后可能出现的应激性溃疡应选用","o":["奥美拉唑","哌仑西平","NaHCO3","阿托品","阿司咪唑"],"a":0,"e":"奥美拉唑为质子泵抑制药，抑制胃壁细胞H+-K+-ATP酶，减少胃酸分泌，对应激性溃疡既有预防作用又有治疗作用。"},{"q":"中枢抗胆碱药不能缓解长期应用氯丙嗪出现的","o":["帕金森综合征","迟发性运动障碍","静坐不能","面容呆板","急性肌张力障碍"],"a":1,"e":"氯丙嗪长期阻断黑质-纹状体通路D2受体致迟发性运动障碍，其发生与受体上调有关，中枢抗胆碱药不能缓解，反而可能加重症状。"},{"q":"治疗阿尔茨海默病的NMDA受体拮抗药是","o":["石杉碱甲","利斯的明","多奈哌齐","氯胺酮","美金刚"],"a":4,"e":"美金刚为谷氨酸NMDA受体非竞争性拮抗药，阻断病理性钙内流，用于中重度阿尔茨海默病，可改善认知功能与行为症状。"},{"q":"治疗手术后腹胀及尿潴留可用","o":["乙酰胆碱","毛果芸香碱","毒扁豆碱","新斯的明","加兰他敏"],"a":3,"e":"新斯的明抑制胆碱酯酶并直接兴奋骨骼肌N2受体，增强肠蠕动和膀胱逼尿肌收缩，故用于治疗术后腹胀及尿潴留。"},{"q":"左旋多巴治疗帕金森病的机制是","o":["补充纹状体内多巴胺","抑制外周多巴脱羧酶","直接激动多巴胺受体","阻断中枢胆碱受体","兴奋中枢NA受体"],"a":0,"e":"左旋多巴透过血脑屏障后经多巴脱羧酶转化为多巴胺，补充纹状体内多巴胺的不足，从而改善帕金森病的症状。"},{"q":"治疗单纯疱疹脑炎有效的药物是","o":["金刚烷胺","阿昔洛韦","利巴韦林","碘苷","盐酸吗啉胍"],"a":1,"e":"阿昔洛韦在体内转化为三磷酸型，选择性抑制疱疹病毒DNA聚合酶并终止DNA链延伸，对单纯疱疹病毒性脑炎疗效确切。"},{"q":"含有巯基的血管紧张素转化酶抑制药是","o":["依那普利","福辛普利","赖诺普利","卡托普利","雷米普利"],"a":3,"e":"卡托普利分子中含巯基，可与血管紧张素转化酶活性中心的锌离子结合；依那普利、赖诺普利不含巯基，福辛普利含膦酸基。"},{"q":"可促进肾上腺素能神经递质释放的是","o":["毛果芸香碱","肾上腺素","麻黄碱","胍乙啶","利舍平"],"a":2,"e":"麻黄碱除直接激动α、β受体外，还能促进肾上腺素能神经末梢释放去甲肾上腺素，故作用较肾上腺素持久。"},{"q":"可抑制前庭神经内耳功能的药物是","o":["阿托品","东莨菪碱","山莨菪碱","毒扁豆碱","筒箭毒碱"],"a":1,"e":"东莨菪碱阻断M受体并抑制前庭神经内耳功能，兼有中枢镇静作用，为晕动病及眩晕的常用药物。"},{"q":"糖皮质激素可治疗","o":["角膜溃疡","真菌感染","接触性皮炎","水痘","肾上腺皮质功能亢进"],"a":2,"e":"糖皮质激素抑制局部炎症反应与免疫反应，接触性皮炎属变态反应性皮肤病，局部或全身应用均有明显疗效。"},{"q":"慢性钝痛时，不宜用吗啡的主要原因是","o":["对钝痛效果差","治疗量即抑制呼吸","可致便秘","易成瘾","易引起体位性低血压"],"a":3,"e":"吗啡镇痛作用强，但反复使用易产生成瘾性，慢性钝痛病程长，应首选非甾体抗炎药，以避免成瘾。"},{"q":"五氟利多的适应证是","o":["躁狂症","精神分裂症","抑郁症","焦虑症","帕金森病"],"a":1,"e":"五氟利多属二苯基丁酰哌啶类长效抗精神病药，每周给药一次，主要用于精神分裂症尤其是慢性患者的维持治疗。"},{"q":"以下哪项不是形成肿瘤多药耐药的机制","o":["化疗药物转运及摄取障碍","肿瘤细胞分解酶水平增加","抑制p-糖蛋白外排泵","化疗药物活化障碍","肿瘤细胞修复机制增加"],"a":2,"e":"多药耐药机制包括药物转运及摄取障碍、活化障碍、分解酶增加、修复机制增强和p-糖蛋白外排增加，抑制外排泵并非耐药机制。"},{"q":"药物达到一定效应时所需要的相对剂量，称为","o":["效价强度","效能","阈剂量","治疗量","极量"],"a":0,"e":"效价强度指产生一定效应所需的相对剂量，所需剂量越小效价强度越大；效能则指药物所能产生的最大效应。"},{"q":"误服有机磷酸酯类农药后，导致体内某物质蓄积，进而激动骨骼肌中NM受体，出现骨骼肌震颤。该物质是","o":["琥珀胆碱","筒箭毒碱","乙酰胆碱","卡巴胆碱","贝胆碱"],"a":2,"e":"有机磷酸酯抑制胆碱酯酶，使乙酰胆碱在突触间隙蓄积，蓄积的乙酰胆碱激动骨骼肌N2受体，引起肌束颤动。"},{"q":"钙拮抗药对心脏的作用是","o":["加快心率","加快传导","减弱心肌收缩力","扩张血管","抑制血小板聚集"],"a":2,"e":"钙拮抗药阻滞L型钙通道，减少钙内流，使心肌收缩力减弱、心率减慢、传导减慢；扩张血管属其对血管的作用。"},{"q":"中和胃酸作用强、吸收后引起碱血症的抗酸药是","o":["氢氧化铝","氢氧化镁","三硅酸镁","碳酸氢钠","碳酸钙"],"a":3,"e":"碳酸氢钠中和胃酸迅速而强，但产生大量二氧化碳，且吸收后使血液碱储备增加，长期大量应用可致碱血症。"},{"q":"主要作用于髓袢升支粗段髓质部和皮质部的利尿药是","o":["呋塞米","氢氯噻嗪","螺内脂","乙酰唑胺","甘露醇"],"a":0,"e":"呋塞米抑制髓袢升支粗段髓质部和皮质部的Na+-K+-2Cl-同向转运体，排钠排水作用强，属高效能利尿药。"},{"q":"某感染患者，青霉素过敏，不宜选用的药物是","o":["四环素","红霉素","磺胺类","氯霉素","阿莫西林"],"a":4,"e":"阿莫西林为青霉素类，与青霉素G存在交叉过敏，青霉素过敏者禁用，可改用红霉素、四环素等非β-内酰胺类。"},{"q":"某药物在口服和静注相同剂量后的时量曲线下面积相等，表明其","o":["口服吸收迅速","口服吸收完全","口服的生物利用度低","口服药物未经肝门脉吸收","属一室分布模型"],"a":1,"e":"药时曲线下面积反映进入体循环的药量，口服与静注等剂量时面积相等，说明口服药物全部进入体循环，即吸收完全。"},{"q":"贝特类对血脂的影响正确的是","o":["明显降低TC","轻度升高HDL-C","对VLDL影响小","明显降低LDL-C","对TG作用不定"],"a":1,"e":"贝特类主要降低甘油三酯和VLDL，同时轻度升高HDL-C，降低TC和LDL-C的作用弱，与他汀类调脂特点不同。"},{"q":"易燃易爆的吸入性全麻药是","o":["氧化亚氮","乙醚","氟烷","恩氟烷","异氟烷"],"a":1,"e":"乙醚为挥发性液体，蒸气与空气混合后遇火可燃烧爆炸，现已少用；氧化亚氮及含氟烷烃类麻醉药不易燃易爆。"},{"q":"长期用异烟肼引起的周围神经炎可合用下列何种药物防治","o":["维生素B2","维生素B6","维生素K","维生素C","维生素B12"],"a":1,"e":"异烟肼结构与维生素B6相似，竞争性干扰其利用并增加排泄，长期用药可致周围神经炎，同服维生素B6可防治。"},{"q":"氨基糖苷类抗生素对以下哪类细菌无效","o":["厌氧菌","铜绿假单胞菌","革兰氏阴性菌","革兰氏阳性菌","结核杆菌"],"a":0,"e":"氨基糖苷类为静止期杀菌药，其进入菌体依赖氧依赖性主动转运，厌氧菌缺乏该转运系统，故对厌氧菌无效。"},{"q":"治疗军团菌感染首选的药物是","o":["红霉素","氯霉素","青霉素","麦白霉素","四环素"],"a":0,"e":"红霉素等大环内酯类在肺组织及巨噬细胞内浓度高，对军团菌有良好抗菌活性，为军团菌肺炎的首选药物。"},{"q":"军团菌病的首选药是","o":["头孢曲松","阿莫西林","四环素","庆大霉素","红霉素"],"a":4,"e":"军团菌为胞内寄生菌，红霉素在肺泡巨噬细胞内浓度高、抗菌作用强，故为军团菌病的首选药。"},{"q":"阿司匹林与双香豆素合用可增加出血倾向的原因是","o":["降低双香豆素的代谢","降低双香豆素的排泄","竞争与血浆蛋白结合","增加双香豆素的吸收","抑制肝药酶"],"a":2,"e":"阿司匹林与双香豆素均与血浆白蛋白结合，合用后竞争结合位点，使游离双香豆素增多，抗凝作用增强而致出血。"},{"q":"利福平的抗菌机制","o":["抑制DNA螺旋霉","抑制二氢叶酸还原酶","抑制DNA依赖的RNA多聚酶","抑制细菌分枝菌酸合成","抑制细菌蛋白质合成"],"a":2,"e":"利福平与细菌DNA依赖性RNA多聚酶的β亚基结合，抑制mRNA转录，从而阻断细菌蛋白质合成。"},{"q":"氟喹诺酮类作用机制是","o":["抑制细菌的转肽酶而影响细菌黏肽合成","抑制细菌二氢蝶酸合成酶","抑制细菌DNA回旋酶，阻碍DNA复制产生抗菌作用","抑制细菌蛋白合成","破坏细菌的细胞壁"],"a":2,"e":"氟喹诺酮类抑制细菌DNA回旋酶和拓扑异构酶Ⅳ，阻碍DNA复制而杀菌；抑制转肽酶、二氢蝶酸合成酶属其他药物机制。"},{"q":"缩宫素兴奋子宫平滑肌的作用机制是","o":["直接兴奋","作用于缩宫素受体","激动M受体","激动H受体","阻断β受体"],"a":1,"e":"缩宫素与子宫平滑肌上的缩宫素受体结合，激活磷脂酶C使细胞内钙增加而兴奋子宫，对非妊娠子宫作用弱。"},{"q":"维拉帕米对下列哪种心律失常的疗效最好","o":["房室传导阻滞","室性期前收缩","强心苷中毒所致心律失常","室性心动过速","房室结折返性心律失常"],"a":4,"e":"维拉帕米阻滞房室结慢反应细胞钙通道，减慢传导并延长有效不应期，对房室结折返性心动过速疗效最佳。"},{"q":"胆碱M受体激动可导致","o":["瞳孔开大肌收缩，支气管平滑肌舒张","血管平滑肌收缩，胃肠道平滑肌舒张","瞳孔括约肌收缩，膀胱逼尿肌舒张","睫状肌收缩，膀胱括约肌舒张","骨骼肌收缩，子宫平滑肌舒张"],"a":3,"e":"M受体激动使瞳孔括约肌和睫状肌收缩，膀胱逼尿肌收缩而括约肌舒张，故表现为缩瞳、调节痉挛及排尿。"},{"q":"治疗急性肺水肿时宜选用的利尿药是","o":["氯酞酮","乙酰唑胺","呋塞米","氨苯蝶啶","阿米洛利"],"a":2,"e":"呋塞米静脉注射可迅速减少血容量、降低心脏前负荷，并扩张静脉，为急性肺水肿的首选利尿药。"},{"q":"氯丙嗪引起乳房肿胀、溢乳是由于阻滞","o":["脑干网状结构上行激活系统α受体","中脑边缘和中脑皮层通路的D2受体","结节-漏斗通路D2受体","黑质-纹状体通路D2受体","M胆碱受体"],"a":2,"e":"氯丙嗪阻断结节-漏斗通路D2受体，解除多巴胺对催乳素释放的抑制，使催乳素分泌增加，引起乳房肿胀和溢乳。"},{"q":"叶酸对抗剂甲氨蝶呤所致的巨幼细胞贫血首选","o":["维生素","亚叶酸钙","维生素B12","叶酸","氨苯甲酸"],"a":1,"e":"甲氨蝶呤抑制二氢叶酸还原酶，阻断四氢叶酸生成；亚叶酸钙可绕过该酶直接提供四氢叶酸，解救其所致巨幼细胞贫血。"},{"q":"目前癫痫的治疗原则是","o":["减少或防止发作","对因治疗","症状消失后可立即停药","手术治疗为主","仅发作时给药"],"a":0,"e":"现有抗癫痫药多不能根治，治疗以长期规律服药控制发作为目标，故治疗原则是减少或防止发作。"},{"q":"钾通道开放药通常作用于哪种钾通道","o":["IK","Ito","KCa","IK1","IK（ATP）"],"a":4,"e":"钾通道开放药如米诺地尔、二氮嗪主要开放ATP敏感性钾通道即KATP，使细胞膜超极化而舒张血管平滑肌。"},{"q":"治疗有机磷酸酯类急性中毒时，阿托品不能缓解的症状是","o":["瞳孔缩小","出汗","恶心、呕吐","呼吸困难","肌肉颤动"],"a":4,"e":"阿托品阻断M受体，可缓解瞳孔缩小、出汗、恶心呕吐及呼吸困难等毒蕈碱样症状，对N2受体介导的肌束颤动无效。"},{"q":"丙米嗪的药理作用是","o":["抗抑郁作用","抗躁狂作用","抗精神分裂症作用","抗惊厥作用","抗癫痫作用"],"a":0,"e":"丙米嗪为三环类抗抑郁药，抑制突触前膜对去甲肾上腺素和5-羟色胺的再摄取，用于治疗各型抑郁症。"},{"q":"强心苷中毒所致的心脏毒性，不能用钾盐治疗的是","o":["室上性阵发性心动过速","室性心动过速","室性期前收缩","心房纤颤","房室传导阻滞"],"a":4,"e":"钾盐可提高细胞外钾浓度，加重房室传导阻滞，故强心苷中毒伴房室传导阻滞时禁用钾盐，宜用阿托品或人工起搏。"},{"q":"维拉帕米首选治疗的心律失常是","o":["房室传导阻滞","阵发性室上性心动过速","室性心动过速","室性期前收缩","强心苷中毒所致心律失常"],"a":1,"e":"维拉帕米抑制房室结慢钙通道并延长其不应期，对房室结折返所致阵发性室上性心动过速首选，对室性心律失常效果差。"},{"q":"以下药物中不具有抑制免疫系统效果的是","o":["泼尼松","环孢素","他克莫司","环磷酰胺","胸腺肽"],"a":4,"e":"胸腺肽为免疫增强剂，可促进T细胞分化成熟；泼尼松、环孢素、他克莫司及环磷酰胺均具有免疫抑制作用。"},{"q":"诱发甲状腺功能紊乱的药物是","o":["甲硫氧嘧啶","碘化物","三碘甲状腺原氨酸","卡比马唑","普萘洛尔"],"a":1,"e":"碘化物长期或过量应用可干扰甲状腺激素的合成与释放，既可引起甲亢也可引起甲减，诱发甲状腺功能紊乱。"},{"q":"皮肤癣菌临床感染常选用","o":["灰黄霉素","两性霉素B","制霉菌素","林可霉素","青霉素"],"a":0,"e":"灰黄霉素干扰真菌微管蛋白聚合，对表皮癣菌等皮肤癣菌有较强抑制作用，口服用于头癣、体癣及股癣。"},{"q":"有机磷酸酯类中毒，必须马上用胆碱酯酶复活药抢救，是因为","o":["胆碱酯酶不易复活","胆碱酯酶复活药起效慢","被抑制的胆碱酯酶很快“老化”","需要立即对抗乙酰胆碱作用","该药药效持续时间短，需迅速注射"],"a":2,"e":"有机磷酸酯与胆碱酯酶结合形成的磷酰化胆碱酯酶可迅速老化，老化后不能再复活，故须尽早使用胆碱酯酶复活药。"},{"q":"对脑水肿病人静注50%高渗葡萄糖的主要目的是","o":["补充能量","使脑组织脱水","增加血容量，防止休克","渗透性利尿","保护脑细胞，减慢脑死亡"],"a":1,"e":"50%高渗葡萄糖静注提高血浆渗透压，使脑组织水分向血管内转移，从而减轻脑水肿、降低颅内压。"},{"q":"促进药物生物转化的主要酶系统是","o":["单胺氧化酶","细胞色素P450酶系统","辅酶Ⅱ","水解酶","葡萄糖醛酸转移酶"],"a":1,"e":"肝药酶主要为细胞色素P450酶系统，催化药物的氧化、还原和水解反应，是药物生物转化的主要酶系统。"},{"q":"有关AT1受体拮抗剂氯沙坦不良反应，叙述错误的是","o":["避免与补钾药合用","对血液中脂质及葡萄糖含量无影响","不引起直立性低血压","刺激性干咳","禁用于肾动脉狭窄者"],"a":3,"e":"氯沙坦为AT1受体拮抗药，不影响缓激肽降解，很少引起刺激性干咳，干咳是ACE抑制药的典型不良反应。"},{"q":"阻滞钠通道而减少Na＋再吸收，同时减少K＋分泌的利尿药是","o":["乙酰唑胺","氢氯噻嗪","螺内酯","阿米洛利","呋塞米"],"a":3,"e":"阿米洛利阻滞肾小管远端及集合管钠通道，减少Na+重吸收和K+分泌，属保钾利尿药；螺内酯则为醛固酮受体拮抗药。"},{"q":"阿托品不会引起的不良反应是","o":["恶心、呕吐","视力模糊","口干","排尿困难","心悸"],"a":0,"e":"阿托品阻断M受体，可抑制胃肠平滑肌收缩、减少腺体分泌，治疗量常见口干、视力模糊、心悸和排尿困难。"},{"q":"首次剂量加倍的原因是","o":["为了使血药浓度迅速达到Css","为了使血药浓度持续高水平","为了增强药理作用","为了延长半衰期","为了提高生物利用度"],"a":0,"e":"首剂加倍可使血药浓度迅速达到稳态浓度，缩短达到有效治疗浓度所需时间，其后按维持量给药即可。"},{"q":"强心苷增强心肌收缩性的作用机制与下列哪种离子变化有关","o":["心肌细胞内K＋增加","心肌细胞内Na＋减少","心肌细胞内Ca2＋增加","心肌细胞内Mg2＋增加","心肌细胞内Cl－增加"],"a":2,"e":"强心苷抑制Na+-K+-ATP酶，使细胞内Na+增多，经Na+-Ca2+交换使细胞内Ca2+增加，从而增强心肌收缩力。"},{"q":"对脑血管有选择性扩张作用的钙拮抗药是","o":["硝苯地平","尼莫地平","尼群地平","维拉帕米","地尔硫䓬"],"a":1,"e":"尼莫地平脂溶性高，易透过血脑屏障，对脑血管的选择性扩张作用强，用于脑血管痉挛和脑缺血性疾病。"},{"q":"下列关于胺碘酮的叙述，错误的是","o":["对α、β肾上腺素受体无阻断作用","降低窦房结和浦肯野纤维的自律性","阻滞心肌细胞钠、钙及钾通道","减慢浦肯野纤维和房室结的传导速度","延长心房肌、心室肌、浦肯野纤维的动作电位时程、有效不应期"],"a":0,"e":"胺碘酮除阻滞钠、钙、钾通道并延长动作电位时程外，尚具有非竞争性阻断α、β肾上腺素受体的作用。"},{"q":"下列可激动M和N胆碱受体的是","o":["毛果芸香碱、氯贝胆碱","毒蕈碱、筒箭毒碱","烟碱、乙酰胆碱","卡巴胆碱、醋甲胆碱","琥珀胆碱、毒扁豆碱"],"a":3,"e":"卡巴胆碱和醋甲胆碱均能激动M、N胆碱受体，对胃肠及膀胱平滑肌作用明显，可用于术后腹胀和尿潴留。"},{"q":"对于应用甲氨蝶呤引起的巨幼红细胞性贫血，治疗时宜选用","o":["亚叶酸钙","叶酸＋维生素B12","红细胞生成素","叶酸","维生素B12"],"a":0,"e":"甲氨蝶呤抑制二氢叶酸还原酶，亚叶酸钙作为四氢叶酸的前体可绕过该环节，为治疗其所致巨幼红细胞贫血的首选。"},{"q":"以下抗恶性肿瘤药为细胞周期非特异性药物的是","o":["羟基脲","阿糖胞苷","长春碱","烷化剂","甲氨蝶呤"],"a":3,"e":"烷化剂可作用于细胞周期各时相，属细胞周期非特异性药物；羟基脲、阿糖胞苷、甲氨蝶呤及长春碱均属周期特异性药物。"},{"q":"丙磺舒延长青霉素药效的原因是","o":["也有杀菌作用","能减慢青霉素的代谢","能延缓耐药性的产生","能减慢青霉素的排泄","能减少青霉素的分布"],"a":3,"e":"丙磺舒竞争肾小管有机酸转运载体，抑制青霉素的主动分泌，减慢其排泄，从而延长并增强青霉素的疗效。"},{"q":"对于人类免疫缺陷病毒感染，以下药物对其无治疗效果的是","o":["转移因子","齐多夫定","胸腺素","泼尼松","白细胞介素-2"],"a":3,"e":"泼尼松为糖皮质激素，无抗人类免疫缺陷病毒作用，反因抑制免疫而加重感染；齐多夫定抑制逆转录酶，转移因子等属免疫调节药。"},{"q":"唑类抗真菌药物的主要作用机制是","o":["抑制核酸合成","抑制二氢叶酸合成酶","抑制二氢叶酸还原酶","抑制蛋白质合成","抑制细胞膜麦角固醇的合成，使其通透性增加"],"a":4,"e":"唑类抗真菌药抑制真菌细胞色素P450依赖的14α-去甲基化酶，阻碍细胞膜麦角固醇合成，使膜通透性增加。"},{"q":"下列药物哪种是繁殖期杀菌药","o":["青霉素","庆大霉素","多黏菌素","四环素","阿米卡星"],"a":0,"e":"青霉素属β-内酰胺类，通过抑制细胞壁合成发挥繁殖期杀菌作用；庆大霉素、阿米卡星为静止期杀菌药，四环素为抑菌药。"},{"q":"呋塞米对尿中离子排泄的影响不正确的是","o":["Na＋排出增加","K＋排出增加","Mg2＋排出增加","Ca2＋排出增加","HCO3－排出减少"],"a":4,"e":"呋塞米抑制髓袢升支粗段Na+-K+-2Cl-转运体，Na+、K+、Ca2+、Mg2+排出均增加，HCO3-排出也增多而非减少。"},{"q":"解热镇痛药的主要镇痛机理","o":["激活阿片受体","抑制下丘脑的前列腺素合成","抑制外周组织前列腺素合成","抑制外周组织组胺合成","抑制外周组织缓激肽合成"],"a":2,"e":"解热镇痛药抑制外周炎症组织中环氧酶，减少前列腺素合成，降低痛觉感受器对缓激肽等致痛物质的敏感性。"},{"q":"脑血管痉挛性疾病宜选用","o":["地尔硫䓬","普萘洛尔","维拉帕米","硝苯地平","尼莫地平"],"a":4,"e":"尼莫地平脂溶性高，易透过血脑屏障，选择性扩张脑血管，为脑血管痉挛性疾病的首选钙拮抗药。"},{"q":"不宜用于变异型心绞痛的药物","o":["硝酸甘油","硝苯地平","普萘洛尔","维拉帕尔","地尔硫䓬"],"a":2,"e":"普萘洛尔阻断β受体，使冠状动脉α受体作用相对占优，可诱发或加重冠脉痉挛，故不宜用于变异型心绞痛。"},{"q":"肝素的抗凝机制是","o":["拮抗维生素K","特异性抑制凝血酶活性","依赖抗凝血酶Ⅲ，抑制多种凝血因子、凝血酶","抗血小板聚集","络合钙离子"],"a":2,"e":"肝素与抗凝血酶Ⅲ结合并增强其活性，灭活凝血酶及Ⅹa、Ⅸa、Ⅺa、Ⅻa等多种凝血因子而发挥抗凝作用。"},{"q":"下列哪类药物常作为基础降压药应用","o":["肾上腺素受体阻断药","中枢交感神经抑制药","血管扩张药","血管紧张素转化酶抑制药","利尿降压药"],"a":4,"e":"利尿降压药价格低、降压平稳，并能增强其他降压药的疗效，常作为基础降压药与各类降压药联合应用。"},{"q":"肝功能障碍病人正常情况下，可以使用的抗菌药是","o":["红霉素","氯霉素","青霉素","利福平","林可霉素"],"a":2,"e":"青霉素主要经肾排泄，对肝药酶影响小，肝功能不良时无须调整剂量；红霉素、氯霉素、利福平及林可霉素均需经肝代谢。"},{"q":"排钠效能最高的利尿药是","o":["氢氯噻嗪","阿米洛利","呋塞米","环戊噻嗪","苄氟噻嗪"],"a":2,"e":"呋塞米抑制髓袢升支粗段转运体，排钠量可达滤过钠的20%～30%，为排钠效能最高的利尿药。"},{"q":"pKa＜4的弱酸性药物如地西泮，在胃肠道pH范围内基本都是","o":["离子型，吸收快而完全","非离子型，吸收快而完全","离子型，吸收慢而不完全","非离子型，吸收慢而不完全","离子型和非离子型相等"],"a":1,"e":"pKa小于4的弱酸性药物在胃液pH条件下解离少，多以非离子型存在，脂溶性高，易透过胃黏膜吸收，故吸收快而完全。"},{"q":"对伴有心律失常的心绞痛患者最好选用","o":["硝酸甘油","普萘洛尔","硝酸异山梨酯","氨氯地平","硝苯地平"],"a":1,"e":"普萘洛尔阻断β受体，减慢心率、降低心肌收缩力和耗氧量，兼有抗心律失常作用，适于伴心律失常的心绞痛。"},{"q":"利用玻璃微电极测定细胞膜对离子的通透性，可记录单个通道的电活动，并可应用于直径较小的细胞的技术是","o":["电压钳","电流钳","脑片钳","膜片钳","电位钳"],"a":3,"e":"膜片钳技术以玻璃微电极吸附细胞膜小片，记录单个离子通道电流，可研究直径较小细胞上的单通道电活动。"},{"q":"抑制5-羟色胺再摄取的口服抗抑郁药是","o":["阿米替林","氟西汀","丙咪嗪","地昔帕明","曲唑酮"],"a":1,"e":"氟西汀选择性抑制突触前膜对5-羟色胺的再摄取，为口服SSRI类抗抑郁药；阿米替林、丙米嗪、地昔帕明属三环类。"},{"q":"糖皮质激素治疗过敏性支气管哮喘的主要作用机制是","o":["直接扩张支气管平滑肌","兴奋β2受体","稳定肥大细胞膜，抑制炎性介质释放","使细胞内cAMP增加","抑制补体参与免疫反应"],"a":2,"e":"糖皮质激素稳定肥大细胞和溶酶体膜，抑制组胺、白三烯等炎性介质释放，并抑制炎性细胞浸润，从而发挥平喘作用。"},{"q":"格列本脲降血糖的主要作用机制是","o":["拮抗胰高血糖素的作用","增强肌肉组织糖的无氧酵解","妨碍葡萄糖的肠道吸收","刺激胰岛β细胞释放胰岛素","升高血清糖原水平"],"a":3,"e":"格列本脲为磺脲类降糖药，与胰岛β细胞膜磺脲受体结合，关闭ATP敏感性钾通道，促使胰岛素释放。"},{"q":"关于硝酸酯类，描述错误的是","o":["舌下含服避免首过消除","硝酸异山梨酯作用持久与代谢产物活性有关","其作用机制与释放NO有关","剂量过大时，血压降低可致反射性心率加快","增加心室内压，改善心内膜供血"],"a":4,"e":"硝酸酯类扩张静脉和动脉，降低心室充盈压与心室壁张力，使心室内压下降而非增加，从而改善心内膜下供血。"},{"q":"耳、肾毒性最小的氨基糖苷药物是","o":["链霉素","卡那霉素","庆大霉素","新霉素","奈替米星"],"a":4,"e":"奈替米星为氨基糖苷类中耳毒性和肾毒性最低者，链霉素、卡那霉素、庆大霉素及新霉素的耳肾毒性相对较大。"},{"q":"流行性脑脊髓膜炎治疗应选用哪种药物","o":["甲氧苄啶","磺胺嘧啶","庆大霉素","万古霉素","多黏菌素"],"a":1,"e":"磺胺嘧啶易透过血脑屏障，脑脊液浓度高，对脑膜炎球菌作用强，为流行性脑脊髓膜炎的首选药物。"},{"q":"药物的副作用是指","o":["专指反应程度较高的过敏反应","因用量过大所致","治疗剂量下产生的与治疗目的无关作用","指剧毒药所产生的毒性","由于患者高度敏感所致"],"a":2,"e":"副作用指药物在治疗剂量下出现的与治疗目的无关的作用，与药物选择性低有关，一般较轻微且可预知。"},{"q":"舌下给药的特点是","o":["可避免胃肠刺激作用","可避免肝肠循环","可避免药物副作用","可避免不良反应","可避免首过消除"],"a":4,"e":"舌下黏膜血流丰富，药物经舌下静脉直接进入体循环，避开胃肠及肝脏，避免首过消除，起效迅速。"},{"q":"药动学研究的内容是","o":["机体对药物的处置","药物剂量与药物效应强弱关系","药物化学结构的变化","药物对机体的作用","药物作用的两重性作用"],"a":0,"e":"药动学研究药物在体内的吸收、分布、代谢和排泄过程及其规律，即机体对药物的处置，与药效学研究内容不同。"},{"q":"氯丙嗪使下列哪种激素释放增加","o":["生长激素","促性腺激素","催乳素","甲状腺激素","促肾上腺皮质激素"],"a":2,"e":"氯丙嗪阻断结节-漏斗通路D2受体，减弱多巴胺对催乳素细胞的抑制，使催乳素释放增加。"},{"q":"硝酸甘油与普萘洛尔联合应用治疗心绞痛，药理作用相同的因素是","o":["心率","心室容积","心肌耗氧量","射血时间","心肌收缩力"],"a":2,"e":"硝酸甘油主要扩张静脉降低前负荷，普萘洛尔减慢心率、减弱心肌收缩力，二者均使心肌耗氧量降低。"},{"q":"属于子宫平滑肌抑制药的是","o":["前列腺素","麦角胺","缩宫素","利托君","垂体后叶素"],"a":3,"e":"利托君为β2受体激动药，可抑制子宫平滑肌收缩，用于防治早产；缩宫素、前列腺素及麦角类均兴奋子宫平滑肌。"},{"q":"下列关于钠通道阻滞药的说法，正确的是","o":["Ⅰa类适度阻滞钠通道，代表药物有利多卡因、苯妥英钠等","Ⅰa类轻度阻滞钠通道，轻度降低动作电位0期除极速率","Ⅰb类明显阻滞钠通道，显著降低动作电位0期除极速率和幅度","Ⅰb类代表药物有奎尼丁、普鲁卡因胺等","Ⅰc类代表药有普罗帕酮、氟卡尼等"],"a":4,"e":"Ⅰc类为重度阻滞钠通道药，代表药有普罗帕酮、氟卡尼；奎尼丁、普鲁卡因胺属Ⅰa类，利多卡因、苯妥英钠属Ⅰb类。"},{"q":"维拉帕米的抗心律失常作用机制是","o":["促进K＋外流","促进Na＋内流","促进Cl－内流","抑制Ca2＋内流","抑制K＋外流"],"a":3,"e":"维拉帕米阻滞心肌细胞L型钙通道，抑制Ca2+内流，减慢窦房结和房室结传导，延长其有效不应期。"},{"q":"去氧肾上腺素的扩瞳作用机制是","o":["激动虹膜括约肌的M受体","阻断虹膜括约肌的M受体","激动虹膜开大肌的α受体","阻断虹膜开大肌的α受体","激动睫状肌的M受体"],"a":2,"e":"去氧肾上腺素激动虹膜开大肌α1受体，使瞳孔开大肌收缩而扩瞳，不引起睫状肌麻痹，故无调节麻痹。"},{"q":"下列疾病宜选用选择性M3受体阻断药治疗的是","o":["消化性溃疡","膀胱过度活动症","青光眼","妊娠呕吐","心律失常"],"a":1,"e":"索利那新等选择性M3受体阻断药抑制膀胱逼尿肌收缩，用于膀胱过度活动症，对唾液腺等腺体影响小。"},{"q":"下列不属于作用于肾素-血管紧张素-醛固酮系统的药物是","o":["阿利吉仑","卡托普利","替米沙坦","氨氯地平","螺内酯"],"a":3,"e":"氨氯地平为二氢吡啶类钙拮抗药，作用于L型钙通道；阿利吉仑、卡托普利、替米沙坦、螺内酯均作用于肾素-血管紧张素-醛固酮系统。"},{"q":"兼具抗肿瘤、抗病毒以及免疫调节功能的免疫增强剂是","o":["泼尼松","胸腺素","左旋咪唑","干扰素","环孢素"],"a":3,"e":"干扰素兼有抗病毒、抗肿瘤和免疫调节作用，属免疫增强剂；泼尼松、环孢素属免疫抑制药。"},{"q":"耐青霉素酶的半合成青霉素是","o":["苯唑西林","氨苄西林","阿莫西林","羧苄西林","哌拉西林"],"a":0,"e":"苯唑西林侧链有异噁唑基团，空间位阻保护β-内酰胺环，耐青霉素酶，用于耐酶金黄色葡萄球菌感染。"},{"q":"下列哪一项不属于呋塞米的不良反应","o":["低钾血症","低镁血症","耳毒性","低氯性碱血症","灰婴综合征"],"a":4,"e":"呋塞米可引起低钾血症、低镁血症、低氯性碱血症及耳毒性；灰婴综合征是氯霉素在新生儿引起的不良反应。"},{"q":"下列药物中属于吩噻嗪类抗精神分裂症药的是","o":["氯丙嗪","氟哌啶醇","氯氮平","舒必利","利培酮"],"a":0,"e":"氯丙嗪为吩噻嗪类抗精神病药；氟哌啶醇属丁酰苯类，氯氮平属二苯二氮䓬类，舒必利属苯甲酰胺类，利培酮属非典型抗精神病药。"},{"q":"治疗甲氨蝶呤所致巨幼红细胞贫血，宜选用","o":["铁剂","维生素B12","叶酸","双香豆素","亚叶酸钙"],"a":4,"e":"甲氨蝶呤抑制二氢叶酸还原酶，亚叶酸钙可直接提供四氢叶酸，故用于解救其所致巨幼红细胞性贫血。"},{"q":"具有黏痰溶解作用的祛痰药是","o":["乙酰半胱氨酸","苯丙哌林","氯化铵","苯佐那酯","山梨醇"],"a":0,"e":"乙酰半胱氨酸含巯基，可断裂痰液中糖蛋白的二硫键，使痰液黏稠度降低而易于咳出，为黏痰溶解药。"},{"q":"酮替芬属于下述哪种药物","o":["茶碱类","β2肾上腺素受体激动药","糖皮质激素","抗过敏平喘药","M胆碱受体阻断药"],"a":3,"e":"酮替芬为抗过敏平喘药，兼有H1受体阻断和稳定肥大细胞膜作用，主要用于预防支气管哮喘发作。"},{"q":"高血压危象可选用下列哪种药物","o":["硝普钠","氯沙坦","卡托普利","氢氯噻嗪","普萘洛尔"],"a":0,"e":"硝普钠直接扩张动脉和静脉，起效快、作用维持短，静脉滴注可迅速控制血压，为高血压危象的首选药。"},{"q":"青霉素最适于治疗下列哪种细菌引起的感染","o":["溶血性链球菌","肺炎克雷伯菌","铜绿假单孢菌","变形杆菌","鼠疫杆菌"],"a":0,"e":"青霉素对溶血性链球菌高度敏感，为首选药；肺炎克雷伯菌、铜绿假单胞菌及变形杆菌多产β-内酰胺酶而耐药。"},{"q":"使用吗啡治疗能产生欣快与觅药行为，在脑内主要激活的神经通路是","o":["5-HT能神经通路","Ach能神经通路","NA能神经通路","Glu能神经通路","DA能神经通路"],"a":4,"e":"吗啡激动μ受体，间接激活中脑边缘多巴胺能神经通路，引起欣快感并促成觅药行为，此为阿片类成瘾的基础。"},{"q":"毛果芸香碱主要用于","o":["重症肌无力","感冒发汗","心动过速","青光眼","术后腹胀"],"a":3,"e":"毛果芸香碱激动M受体，使瞳孔括约肌和睫状肌收缩，房水排出增加、眼压下降，为青光眼的常用药。"},{"q":"去甲肾上腺素能神经兴奋可引起","o":["心收缩力减弱","血压下降","皮肤黏膜血管收缩","支气管平滑肌收缩","骨骼肌血管收缩"],"a":2,"e":"去甲肾上腺素能神经兴奋时，α1受体介导皮肤黏膜血管强烈收缩，骨骼肌血管则以β2受体介导舒张为主。"},{"q":"有关哌替啶的用途，叙述错误的是","o":["镇痛","人工冬眠","麻醉前给药","心源性哮喘","止泻"],"a":4,"e":"哌替啶可用于镇痛、麻醉前给药、人工冬眠及心源性哮喘；其不抑制肠蠕动，无止泻用途，反可致便秘。"},{"q":"儿童验光配镜检查宜选用","o":["东莨菪碱","溴丙胺太林","去氧肾上腺素","阿托品","吗噻洛尔"],"a":3,"e":"阿托品阻断睫状肌M受体，使睫状肌麻痹、调节功能丧失，儿童验光配镜需充分麻痹调节，故选用阿托品。"},{"q":"胆碱能神经兴奋不能介导的生理效应是","o":["缩瞳","心率减慢","促脂肪分解","汗腺分泌增加","子宫平滑肌收缩"],"a":2,"e":"胆碱能神经兴奋表现为缩瞳、心率减慢、腺体分泌增加及子宫平滑肌收缩；促脂肪分解由β肾上腺素受体介导。"},{"q":"药物的排泄途径不包括","o":["汗腺","肾脏","胆汁","肺","肝脏"],"a":4,"e":"药物排泄途径包括肾、胆道、肺、汗腺、唾液及乳汁等；肝脏是药物生物转化即代谢的主要器官。"},{"q":"对青霉素G不敏感的细菌是","o":["溶血性链球菌","脑膜炎球菌","肠球菌","炭疽杆菌","破伤风杆菌"],"a":2,"e":"青霉素G对溶血性链球菌、脑膜炎球菌、炭疽杆菌及破伤风杆菌敏感；肠球菌对其敏感性差，常需联合氨基糖苷类。"},{"q":"几乎没有抗炎作用的药物是","o":["保泰松","布洛芬","阿司匹林","对乙酰氨基酚","吡罗昔康"],"a":3,"e":"对乙酰氨基酚抑制中枢前列腺素合成而解热镇痛，对外周环氧酶作用弱，几乎无抗炎抗风湿作用。"},{"q":"铁剂治疗缺铁性贫血，说法错误的是","o":["口服1周，血中网织红细胞即可上升","2～4周后，血红蛋白明显增加","血红蛋白达正常值约需4～8周","血红蛋白正常后，应继续服用2～3个月","肌内注射吸收率高于口服吸收率"],"a":4,"e":"铁剂口服1周网织红细胞上升，2～4周血红蛋白明显增加；肌内注射虽吸收快，但吸收率并不高于口服。"},{"q":"既能降低LDL也能降低HDL的药物是","o":["辛伐他汀","苯扎贝齐","普罗布考","考来烯胺","烟酸"],"a":2,"e":"普罗布考抗氧化，降低LDL-C的同时也降低HDL-C；他汀类、贝特类、烟酸及考来烯胺均不降低HDL-C。"},{"q":"鲑降钙素的特点是","o":["可以口服治疗骨质疏松症","不可以皮下给药","主要靶器官是小肠","与破骨细胞结合抑制骨吸收","升高血浆钙离子浓度"],"a":3,"e":"鲑降钙素与破骨细胞上的降钙素受体结合，抑制骨吸收并降低血钙，须注射给药，主要用于骨质疏松及骨痛。"},{"q":"对肝素的正确描述是","o":["可抑制多种凝血因子的活化","可以口服给药","用于DIC的晚期治疗","仅在体内有抗凝作用","可抑制血小板聚集"],"a":0,"e":"肝素与抗凝血酶Ⅲ结合，加速灭活凝血酶及多种活化凝血因子；口服无效，体内外均有抗凝作用。"},{"q":"下列哪个抗癫痫药物起效缓慢，使用时需逐渐加量","o":["苯妥英钠","苯巴比妥","地西泮","乙琥胺","丙戊酸钠"],"a":0,"e":"苯妥英钠呈非线性动力学，起效缓慢，需从小剂量开始逐渐加量，以免血药浓度骤升引起中毒。"},{"q":"病原体或肿瘤细胞对反复应用的化疗药物的敏感性降低，称为","o":["耐受性","耐药性","精神依赖性","生理依赖性","停药症状"],"a":1,"e":"耐药性指病原体或肿瘤细胞对反复应用的化疗药物敏感性降低；耐受性则指机体对药物反应性的降低。"},{"q":"防治静脉血栓的口服药是","o":["链激酶","尿激酶","肝素","华法林","枸橼酸钠"],"a":3,"e":"华法林为口服香豆素类抗凝药，抑制维生素K环氧化物还原酶，用于静脉血栓的预防和治疗。"},{"q":"药物的首过消除是指","o":["肾脏对体内药物的首次排泄","肠黏膜及肝脏对药物的转化","药物与血浆蛋白的牢固结合","胃酸对药物化学结构的破坏","皮肤给药后药物的吸收作用"],"a":1,"e":"首过消除指药物经胃肠吸收后，在肠黏膜和肝脏被代谢灭活，使进入体循环的药量减少，生物利用度降低。"},{"q":"下列哪种药通过抑制蛋白质合成而起抗肿瘤作用","o":["喜树碱","L-门冬酰胺酶","博来霉素","羟基脲","氮芥"],"a":1,"e":"L-门冬酰胺酶水解血浆门冬酰胺，使肿瘤细胞缺乏必需氨基酸而抑制蛋白质合成；喜树碱、羟基脲则抑制核酸合成。"},{"q":"伴糖尿病肾病的高血压患者最好选用","o":["可乐定","卡托普利","哌唑嗪","氢氯噻嗪","硝普钠"],"a":1,"e":"卡托普利抑制血管紧张素转化酶，扩张肾出球小动脉，降低肾小球内压，减少尿蛋白，对糖尿病肾病有保护作用。"},{"q":"下列哪种药物只激动N受体","o":["乙酰胆碱","毛果芸香碱","毒蕈碱","卡巴胆碱","烟碱"],"a":4,"e":"烟碱选择性激动N胆碱受体，对M受体无作用；乙酰胆碱、卡巴胆碱激动M和N受体，毛果芸香碱只激动M受体。"},{"q":"强心苷对下列何种原因所致的心衰不仅疗效差且易中毒","o":["高血压性心脏病","甲亢风湿性心脏病","房颤伴心功能不全贫血","肺源性心脏病","冠状动脉粥样硬化性心脏病"],"a":3,"e":"肺源性心脏病时心肌缺氧、能量代谢障碍，强心苷疗效差且易诱发中毒；贫血、甲亢所致心衰疗效亦差。"},{"q":"强心苷疗效最好的适应证是","o":["肺源性心脏病引起的心衰","严重二尖瓣病引起的心衰","严重贫血引起的心衰","甲状腺功能亢进引起的心衰","高血压性心衰伴有房颤"],"a":4,"e":"高血压性心衰伴房颤时，强心苷既增强心肌收缩力，又减慢房室传导、控制心室率，故疗效最好。"},{"q":"贝特类降低VLDL的机制是","o":["增加脂蛋白脂酶活性","抑制脂肪分解","抑制肝脏TG酯化","使肝脏合成Apo B增加","减少Apo A的基因表达"],"a":0,"e":"贝特类激动过氧化物酶体增殖物激活受体α，增加脂蛋白脂酶活性，加速VLDL和甘油三酯分解。"},{"q":"通过阻断H2受体减少胃酸分泌的药物是","o":["苯海拉明","哌仑西平","阿托品","雷尼替丁","阿司咪唑"],"a":3,"e":"雷尼替丁阻断胃壁细胞H2受体，减少胃酸分泌；苯海拉明、阿司咪唑阻断H1受体，哌仑西平阻断M1受体。"},{"q":"哌仑西平抑制胃酸分泌的主要作用是阻断或抑制","o":["M1受体","H2受体","胃泌素受体","H1受体","质子泵"],"a":0,"e":"哌仑西平选择性阻断胃壁细胞M1受体，减少胃酸分泌，对心血管等部位的M2、M3受体影响小，不良反应轻。"},{"q":"抗铜绿假单胞菌作用最强的头孢菌素是","o":["头孢克洛","头孢他啶","头孢孟多","头孢噻吩","头孢氨苄"],"a":1,"e":"头孢他啶为第三代头孢菌素，对铜绿假单胞菌的活性在头孢菌素类中最强，常用于铜绿假单胞菌感染。"},{"q":"有机磷酸农药中毒后，碘解磷定解救无效的是","o":["内吸磷","马拉硫磷","对硫磷","敌百虫","乐果"],"a":4,"e":"乐果与胆碱酯酶结合后形成的磷酰化胆碱酯酶老化快，碘解磷定复活作用差，故解救无效，应以阿托品治疗为主。"},{"q":"阿司匹林的抗血小板作用机制是","o":["激活环氧酶","促进血小板中PGI2的合成","促进内皮细胞中PGI2的合成","抑制内皮细胞中TXA2的合成","抑制血小板中TXA2的合成"],"a":4,"e":"阿司匹林不可逆抑制血小板环氧酶，减少血栓素A2生成，从而抑制血小板聚集，作用持续于整个血小板寿命。"},{"q":"下列药物中对支原体肺炎首选药是","o":["红霉素","利福平","磺胺嘧啶","链霉素","青霉素"],"a":0,"e":"红霉素等大环内酯类对支原体有较强作用，且在肺组织浓度高，为支原体肺炎的首选药物。"},{"q":"可兼治脑血管病的抗高血压药是","o":["维拉帕米","尼莫地平","尼群地平","硝苯地平","地尔硫䓬"],"a":1,"e":"尼莫地平脂溶性高、易透过血脑屏障，选择性扩张脑血管，兼有降压作用，适用于高血压合并脑血管病。"},{"q":"肾上腺素扩张支气管的机理是","o":["阻断α1受体","阻断β1受体","兴奋β1受体","兴奋β2受体","兴奋多巴胺受体"],"a":3,"e":"肾上腺素激动支气管平滑肌β2受体，使平滑肌舒张而扩张支气管，同时激动α受体减轻黏膜水肿。"},{"q":"糖皮质激素诱发和加重感染的主要原因是","o":["抑制炎症反应和免疫反应、降低机体的防御能力","用量不足，无法控制症状所致","患者对激素不敏感","促使许多病原微生物繁殖所致","抑制ACTH的释放"],"a":0,"e":"糖皮质激素抑制炎症反应和免疫反应，降低机体防御能力，使原有感染扩散或诱发新的感染。"},{"q":"焦虑紧张引起的失眠宜用","o":["硫喷妥钠","苯妥英钠","水合氯醛","地西泮","氯丙嗪"],"a":3,"e":"地西泮属苯二氮䓬类，具有抗焦虑、镇静催眠和中枢性肌松作用，适于焦虑紧张所致的失眠。"},{"q":"将卡巴多巴与左旋多巴按1∶10剂量合用，可使左旋多巴的使用剂量减少","o":["35%","45%","55%","65%","75%"],"a":4,"e":"卡比多巴抑制外周多巴脱羧酶，与左旋多巴按1∶10合用可增加后者进入脑内的量，使左旋多巴剂量减少约75%。"},{"q":"易引起二重感染的药物是","o":["青霉素","链霉素","红霉素","四环素","异烟肼"],"a":3,"e":"四环素抗菌谱广，长期应用可抑制敏感菌而使耐药菌和真菌大量繁殖，引起二重感染，以口腔、肠道及肺部多见。"},{"q":"属于繁殖期杀菌药的是","o":["青霉素类、头孢菌素类","氯霉素类、四环素类","磺胺类、喹诺酮类","氨基糖苷类、多黏菌素类","四环素类、大环内酯类"],"a":0,"e":"青霉素类、头孢菌素类属β-内酰胺类，抑制细胞壁合成而发挥繁殖期杀菌作用；氨基糖苷类和多黏菌素为静止期杀菌药。"},{"q":"高血压伴支气管哮喘的患者宜选用","o":["地高辛","普萘洛尔","维拉帕米","硝苯地平","氟桂利嗪"],"a":3,"e":"硝苯地平为二氢吡啶类钙拮抗药，扩张血管降压而不阻断β受体，不诱发支气管痉挛，适于高血压伴支气管哮喘者。"},{"q":"唑吡坦对睡眠时相的影响是","o":["对正常睡眠时相干扰少","延长NERMS第2期","缩短REMS睡眠","“反跳性”延长REMS睡眠","引起非生理性睡眠"],"a":0,"e":"唑吡坦选择性作用于苯二氮䓬ω1受体，催眠作用强而次日残留少，对正常睡眠时相结构干扰小。"},{"q":"苯二氮卓受体阻断剂是","o":["氟马西尼","阿托品","三唑仑","硫喷妥钠","甲丙氨酯"],"a":0,"e":"氟马西尼为苯二氮䓬受体拮抗药，可特异性逆转地西泮、三唑仑等所致的中枢抑制，用于中毒解救。"},{"q":"除极化型肌松药具备下列哪项特点","o":["药后无短暂肌颤","连续用药不产生快速耐受性","过量时不导致呼吸肌麻痹","治疗量有神经节阻断作用","其中毒症状不被新斯的明解除"],"a":4,"e":"除极化型肌松药如琥珀胆碱持续激动N2受体，使终板膜持久除极化而肌松，中毒时新斯的明不能拮抗反而加重。"},{"q":"氨基糖苷类药物的不良反应，不包括","o":["耳毒性","肾毒性","再生障碍性贫血","神经肌肉麻痹","过敏反应"],"a":2,"e":"氨基糖苷类主要不良反应为耳毒性、肾毒性、神经肌肉麻痹和过敏反应，再生障碍性贫血多见于氯霉素。"},{"q":"下列是胆碱酯酶复活药的是","o":["新斯的明","碘解磷定","阿托品","地美溴铵","贝胆碱"],"a":1,"e":"碘解磷定与磷酰化胆碱酯酶结合，使胆碱酯酶游离而复活，属胆碱酯酶复活药；新斯的明为可逆性胆碱酯酶抑制药。"},{"q":"药物是","o":["专指可以治疗疾病的化学物质","能干扰细胞代谢活动的化学物质","能影响机体生理功能的物质","用以防治及诊断疾病的物质","有滋补营养、保健作用的物质"],"a":3,"e":"药物指用于预防、治疗和诊断疾病的物质，无防治作用的滋补保健品不属药物；干扰细胞代谢仅是部分药物的作用方式。"},{"q":"表示药物在体内分布程度的药物代谢动力学参数是","o":["表观分布容积","曲线下面积","生物利用度","血浆半衰期","清除率"],"a":0,"e":"表观分布容积为体内药量与血药浓度之比，反映药物在体内分布的广泛程度，并非真实的解剖容积。"},{"q":"具有耳毒性的利尿药是","o":["呋塞米","氢氯噻嗪","氨苯蝶啶","螺内酯","乙酰唑胺"],"a":0,"e":"呋塞米可致耳毒性，表现为耳鸣、听力减退甚至暂时性耳聋，与剂量过大或合用其他耳毒性药物有关。"},{"q":"诺氟沙星属于哪类化合物","o":["磺胺类","硝基呋喃类","吡喹酮类","喹诺酮类","4-氨基喹啉类"],"a":3,"e":"诺氟沙星为第三代含氟喹诺酮类抗菌药，抗菌谱广，对革兰阴性菌作用强，口服用于泌尿系统和肠道感染。"},{"q":"不属于应用胰岛素后出现的不良反应的是","o":["低血糖","过敏反应","胰岛素抵抗","脂肪萎缩","头痛"],"a":4,"e":"胰岛素常见不良反应为低血糖、过敏反应、胰岛素抵抗和注射部位脂肪萎缩或增生，头痛不属于其不良反应。"},{"q":"Ⅰ类抗心律失常药物为","o":["钙通道阻滞药","钠通道阻滞药","肾上腺素受体阻滞药","选择地延长复极过程的药","钾通道开放药"],"a":1,"e":"Ⅰ类抗心律失常药阻滞心肌细胞Na+通道，减慢0相除极速度，按阻滞强度分为Ⅰa、Ⅰb、Ⅰc三亚类；Ⅱ类为β受体阻断药，Ⅳ类为钙通道阻滞药。"},{"q":"属于浓度依赖性抗菌药物，可1日给药1次的是","o":["氨苄西林","莫西沙星","头孢他啶","红霉素","氯霉素"],"a":1,"e":"莫西沙星属氟喹诺酮类，抗菌活性呈浓度依赖性，抗生素后效应长，可1日给药1次；β-内酰胺类与大环内酯类多属时间依赖性药物。"},{"q":"对α和β受体均有阻断作用的药物是","o":["阿替洛尔","吲哚洛尔","拉贝洛尔","普萘洛尔","美托洛尔"],"a":2,"e":"拉贝洛尔兼有α1受体和非选择性β受体阻断作用，属α、β受体阻断药；阿替洛尔、美托洛尔为选择性β1受体阻断药，普萘洛尔仅阻断β受体。"},{"q":"利多卡因最适于治疗的心律失常是","o":["房性期前收缩","心房扑动","心室纤颤","心房纤颤","室上性心动过速"],"a":2,"e":"利多卡因为Ⅰb类钠通道阻滞药，主要作用于希-浦系统，降低心室异位节律点自律性，是心室纤颤及室性期前收缩的首选药，对房性心律失常疗效差。"},{"q":"吗啡抑制呼吸的作用是由于","o":["中毒引起呼吸麻痹","阻滞神经肌肉接头","拮抗Ca2＋使运动神经释放递质减少","阻断N2受体","降低呼吸中枢对CO2张力敏感性"],"a":4,"e":"吗啡激动延髓孤束核等部位阿片受体，降低呼吸中枢对CO2张力的敏感性，抑制呼吸调节中枢，治疗量即可使呼吸频率减慢、潮气量减少。"},{"q":"强心苷引起心脏毒性的原理是","o":["抑制心肌细胞膜Na＋-K＋-ATP酶","兴奋心肌细胞膜Na＋-K＋-ATP酶","增加心肌细胞内K＋","增加心肌细胞内Ca2＋","增加心肌抑制因子的形成和释放"],"a":0,"e":"强心苷重度抑制心肌细胞膜Na+-K+-ATP酶，使细胞内K+减少、Ca2+超载并诱发迟后除极，是中毒时出现各类心律失常的主要原因。"},{"q":"硝酸酯类舒张血管的机制是","o":["直接松弛血管平滑肌","阻断α1受体","阻滞Ca2＋通道","在平滑肌细胞及血管内皮细胞中产生NO","阻断血管平滑肌β2受体"],"a":3,"e":"硝酸酯类在平滑肌细胞及血管内皮细胞中释放NO，NO激活鸟苷酸环化酶使cGMP增多，从而松弛血管平滑肌，并非直接松弛或阻断受体所致。"},{"q":"下列哪项不是氨基糖苷类抗生素的共同特点","o":["由氨基糖分子和非糖部分的苷元结合而成","水溶性好、性质稳定","对革兰氏阳性菌具有高度抗菌活性","对革兰氏阴性需氧菌具有高度抗菌活性","可结合核糖体30S亚基"],"a":2,"e":"氨基糖苷类对革兰阴性需氧杆菌有强大抗菌活性，对革兰阳性菌作用较弱，仅部分品种对阳性菌有效，故对革兰阳性菌高度活性不是其共同特点。"},{"q":"大量或久用可损伤血管内皮细胞的药物是","o":["利托君","缩宫素","麦角胺","前列腺素","垂体后叶素"],"a":2,"e":"麦角胺大剂量或久用可损伤血管内皮细胞，引起血管痉挛、血栓形成及肢端干性坏疽，故血管闭塞性疾病患者禁用。"},{"q":"为预防急性高山病，下列药物可在开始攀登前24小时口服的是","o":["呋塞米","甘露醇","氢氯噻嗪","乙酰唑胺","螺内酯"],"a":3,"e":"乙酰唑胺抑制碳酸酐酶，减少脑脊液生成并纠正呼吸性碱中毒，可减轻急性高山病的头痛、恶心等症状，攀登前24小时口服起预防作用。"},{"q":"ACEI类的药理作用不包括","o":["抑制血管紧张素转化酶，减少AngⅡ的生成","减少醛固酮的生成，降低血压，逆转心血管重构","保存缓激肽活性","增敏胰岛素受体","兴奋AT2受体"],"a":4,"e":"ACEI抑制血管紧张素转化酶，减少AngⅡ生成、保存缓激肽并增敏胰岛素受体；AngⅡ减少后对AT1、AT2受体的激动均减弱，并不兴奋AT2受体。"},{"q":"毛果芸香碱的不良反应不包括","o":["加重哮喘","恶心呕吐","呼吸困难","视物模糊","血压上升"],"a":4,"e":"毛果芸香碱激动M受体，可致腺体分泌增多、恶心呕吐、瞳孔缩小及调节痉挛性视物模糊，大剂量反因迷走神经兴奋使心率减慢、血压下降而非升高。"},{"q":"子痫患者使用硫酸镁治疗后产生呼吸循环抑制，此时应给予何种药物对抗","o":["KCl","NaCl","CaCl2","MgCl2","AlCl3"],"a":2,"e":"硫酸镁过量时Mg2+拮抗Ca2+参与的神经肌肉传递，静脉注射氯化钙可直接补充Ca2+，迅速拮抗其呼吸循环抑制，葡萄糖酸钙亦可应用。"},{"q":"体液的pH影响药物的转运及分布，是由于它改变了药物的","o":["水溶性","脂溶性","pKa","解离度","溶解度"],"a":3,"e":"体液pH改变可改变药物的解离度，非解离型脂溶性高、易跨膜转运，解离型不易通过细胞膜，从而影响药物的吸收、分布和排泄。"},{"q":"异烟肼不具备的优点是","o":["疗效高","穿透力强","易透入细胞内，作用于被吞噬的结核杆菌","无肝毒性","口服吸收快而完全"],"a":3,"e":"异烟肼疗效高、穿透力强、可透入细胞内作用于被吞噬的结核杆菌，口服吸收快而完全；其主要经肝乙酰化代谢，可致肝损害，无肝毒性并非其优点。"},{"q":"下列关于阿司匹林加重出血倾向的描述，错误的是","o":["阿司匹林能不可逆地抑制环氧化酶","对血小板合成TXA2有强大而持久的抑制作用","对血管内皮合成PGI2有强大而持久的抑制作用","大剂量阿司匹林可抑制凝血酶原的形成","手术患者术前1周应停用阿司匹林"],"a":2,"e":"阿司匹林不可逆抑制环氧化酶，对血小板合成TXA2呈强大而持久的抑制；对血管内皮合成PGI2的影响短暂且较弱，故该描述错误。"},{"q":"铁剂用于治疗","o":["溶血性贫血","再生障碍性贫血","小细胞低色素性贫血","巨幼细胞贫血","恶性贫血"],"a":2,"e":"铁剂补充造血原料铁，用于缺铁性贫血，即小细胞低色素性贫血；巨幼细胞贫血用叶酸和维生素B12，再生障碍性贫血则用雄激素、免疫抑制药。"},{"q":"具有对抗醛固酮而引起利尿作用的药物是","o":["呋塞米","氢氯噻嗪","螺内酯","氢苯蝶啶","乙酰唑胺"],"a":2,"e":"螺内酯在远曲小管末端和集合管竞争性拮抗醛固酮受体，减少Na+重吸收和K+排出，产生排钠保钾的利尿作用。"},{"q":"利福平、异烟肼、吡嗪酰胺均可引起哪种不良反应","o":["胃肠道刺激症状","激活肝药酶","视神经炎","肝损害","周围神经炎"],"a":3,"e":"异烟肼经肝乙酰化代谢、利福平干扰肝细胞功能、吡嗪酰胺代谢产物均可损伤肝细胞，三者联用时肝损害风险更高，须监测肝功能。"},{"q":"下列离子通道中，其激活与突触神经递质的释放有关的是","o":["电压依赖性Na+通道","电压依赖性Ca2+通道","配体门控性Ca2+通道","Ca2+依赖性K+通道","配体门控性Cl-通道"],"a":1,"e":"动作电位到达神经末梢时电压依赖性Ca2+通道开放，Ca2+内流触发突触囊泡与前膜融合，是神经递质释放的关键环节。"},{"q":"奥美拉唑是","o":["H2受体阻断剂","H＋-K＋-ATP酶抑制剂","M受体阻断剂","胃泌素受体阻断剂","Na＋-K＋-ATP酶抑制剂"],"a":1,"e":"奥美拉唑在壁细胞泌酸小管酸性环境中转化为活性亚磺酰胺，与H+-K+-ATP酶不可逆结合，抑制胃酸分泌的最后环节。"},{"q":"糖皮质激素类药物对血液和造血系统的作用是","o":["血小板减少","使红细胞与血红蛋白减少","使中性粒细胞减少","刺激骨髓造血机能","淋巴细胞增加"],"a":3,"e":"糖皮质激素刺激骨髓造血机能，使红细胞、血红蛋白、中性粒细胞和血小板增多，同时使淋巴细胞减少，可用于急性淋巴细胞白血病。"},{"q":"下列药物中口服生物利用度最低的是","o":["头孢拉定","头孢氨苄","氨苄西林","阿莫西林","青霉素G"],"a":4,"e":"青霉素G不耐酸，口服易被胃酸破坏，吸收少而不规则，须注射给药；氨苄西林、阿莫西林及头孢氨苄等耐酸可口服。"},{"q":"下列药物中易通过血脑屏障的是","o":["异丙托溴铵","东莨菪碱","山莨菪碱","溴甲东莨菪碱","索利那新"],"a":1,"e":"东莨菪碱为叔胺类生物碱，脂溶性高，易透过血脑屏障，治疗量即有明显中枢镇静和防晕动作用；山莨菪碱及季铵类较难入脑。"},{"q":"下列哪种药物不是镇静催眠药","o":["卡马西平","奥沙西泮","水合氯醛","甲丙氨酯","三唑仑"],"a":0,"e":"卡马西平为抗癫痫药，用于复杂部分性发作和三叉神经痛；奥沙西泮、三唑仑属苯二氮䓬类，水合氯醛、甲丙氨酯亦为镇静催眠药。"},{"q":"增加左旋多巴抗帕金森病疗效，减少不良反应的药物是","o":["卡比多巴","维生素B6","利舍平","苯乙肼","丙胺太林"],"a":0,"e":"卡比多巴为外周脱羧酶抑制剂，不易进入中枢，可减少左旋多巴在外周脱羧，使更多药物入脑，从而增强疗效并减轻外周不良反应。"},{"q":"青霉素G过敏的患者，G＋菌感染时可选用","o":["链霉素","头孢菌素","红霉素","氨苄西林","多黏菌素"],"a":2,"e":"红霉素属大环内酯类，抗菌谱与青霉素相近而略广，对革兰阳性球菌有效，可作青霉素过敏者的替代药；头孢菌素与青霉素存在交叉过敏。"},{"q":"影响胆固醇吸收的药物是","o":["普罗布考","考来烯胺","洛伐他汀","烟酸","苯扎贝特"],"a":1,"e":"考来烯胺为碱性阴离子交换树脂，在肠道与胆酸结合阻断其重吸收，促使胆固醇转化为胆酸排出，从而降低血浆胆固醇。"},{"q":"干扰皮质醇及皮质酮生物合成的皮质激素抑制剂是","o":["美替拉酮","ACTH","氢化可的松","去氧皮质酮","曲安西龙"],"a":0,"e":"美替拉酮抑制11β-羟化酶，阻断11-脱氧皮质醇转化为皮质醇、11-脱氧皮质酮转化为皮质酮，用于库欣综合征的诊断和治疗。"},{"q":"能补充纹状体中多巴胺的药物是","o":["多巴胺","卡比多巴","左旋多巴","苯海索","金刚烷胺"],"a":2,"e":"左旋多巴易透过血脑屏障，在脑内脱羧生成多巴胺，补充纹状体多巴胺不足；多巴胺本身不能透过血脑屏障，无治疗作用。"},{"q":"糖皮质激素抗炎作用机制不包括","o":["对抗细胞因子介导的炎症","直接收缩血管，减少渗出","抑制炎性介质介导的炎症","抑制NO介导的炎症","诱导脂皮素-1的生成"],"a":1,"e":"糖皮质激素诱导脂皮素-1抑制磷脂酶A2，并抑制细胞因子和NO介导的炎症；其减少渗出是降低血管通透性的结果，并非直接收缩血管。"},{"q":"胃肠反应较轻的解热镇痛抗炎药是","o":["阿司匹林","保泰松","吲哚美辛","布洛芬","甲芬那酸"],"a":3,"e":"布洛芬为丙酸类非甾体抗炎药，对胃肠黏膜的刺激性较阿司匹林、吲哚美辛和保泰松轻，患者耐受性较好。"},{"q":"解磷定对有机磷中毒症状作用最明显的是","o":["大小便失禁","视物不清","骨骼肌震颤及麻痹","血压下降","中枢神经兴奋"],"a":2,"e":"解磷定复活被抑制的胆碱酯酶，主要解除有机磷中毒的烟碱样症状，对骨骼肌震颤、肌无力和呼吸肌麻痹疗效最明显；M样症状需合用阿托品。"},{"q":"关于甘露醇的描述不正确的是","o":["不良反应以水、电解质紊乱最常见","体内不被代谢","不易通过毛细血管","提高血浆渗透压","易被肾小管重吸收"],"a":4,"e":"甘露醇为多醇糖，体内不被代谢，经肾小球滤过后几乎不被肾小管重吸收，产生渗透性利尿，并提高血浆渗透压而脱水。"},{"q":"哪项不是苯妥英钠的不良反应","o":["胃肠反应","齿龈增生","过敏反应","共济失调","肾脏严重损害"],"a":4,"e":"苯妥英钠常见胃肠反应、齿龈增生、过敏反应及剂量过大所致共济失调、眼球震颤；肾严重损害不是其典型不良反应。"},{"q":"不直接引起药效的药物是","o":["经肝脏代谢的药物","与血浆蛋白结合的药物","在血循环的药物","达到膀胱的药物","不被肾小管重吸收的药物"],"a":1,"e":"药物与血浆蛋白结合后分子变大，暂时失去活性，不能到达靶部位发挥作用，属药物在体内的贮存形式，须解离为游离型才产生效应。"},{"q":"口服后药物在皮肤、毛发及指（趾）甲等处含量较高的抗真菌药有","o":["两性霉素B","制霉菌素","水杨酸","灰黄霉素","特比萘芬"],"a":3,"e":"灰黄霉素吸收后沉积于皮肤角质层、毛发和指（趾）甲，与角蛋白结合，故对皮肤癣菌所致头癣、体癣、甲癣有效。"},{"q":"强心苷中毒所致的室性期前收缩最宜采用的药物是","o":["利多卡因","阿托品","普鲁帕酮","奎尼丁","胺碘酮"],"a":0,"e":"利多卡因对希-浦系统作用明显，能抑制心室异位节律，为强心苷中毒所致室性期前收缩和室性心动过速的首选药。"},{"q":"以下哪个药物属于国内自主研发的抗阿尔茨海默病的药物","o":["左旋多巴","加兰他敏","多奈哌齐","石杉碱甲","利斯的明"],"a":3,"e":"石杉碱甲是我国学者从千层塔中提取的生物碱，为可逆性胆碱酯酶抑制剂，属国内自主研发的抗阿尔茨海默病药物。"},{"q":"小剂量阿托品即可引起的药理作用是","o":["血管扩张","平滑肌松弛","扩瞳","腺体分泌减少","心率加快"],"a":3,"e":"阿托品对腺体分泌最敏感，小剂量即抑制唾液腺、汗腺和呼吸道腺体分泌，引起口干、皮肤干燥；扩瞳、加快心率需较大剂量。"},{"q":"组胺H1受体阻断药不能治疗的疾病是","o":["晕动病","变态反应性疾病","过敏性休克","失眠","过敏性鼻炎"],"a":2,"e":"H1受体阻断药仅能竞争性阻断组胺与H1受体结合，不能拮抗已释放组胺的强烈作用，过敏性休克须首选肾上腺素抢救。"},{"q":"关于α受体阻断药体内过程的描述正确的是","o":["酚妥拉明生物利用度高","酚妥拉明肌内注射作用维持时间长达数小时","酚苄明脂溶性高，作用持久","酚苄明常作肌内注射或皮下注射","妥拉唑林以口服给药为主"],"a":2,"e":"酚苄明脂溶性高，与α受体结合牢固、解离缓慢，故作用持久，一次给药可维持3～4日；其局部刺激性大，只能静脉给药。"},{"q":"下列哪种不是华法林的禁忌证","o":["心房颤动患者","消化性溃疡活动期","严重高血压","对华法林过敏患者","血友病患者"],"a":0,"e":"华法林用于心房颤动、瓣膜置换术后等血栓栓塞性疾病的防治；消化性溃疡活动期、严重高血压、血友病及过敏者禁用。"},{"q":"通过利尿发挥降压作用的药物是","o":["可乐定","美卡拉明","利舍平","卡托普利","氢氯噻嗪"],"a":4,"e":"氢氯噻嗪抑制远曲小管Na+-Cl-同向转运，排钠利尿使血容量减少、血管张力下降，为一线基础降压药。"},{"q":"氨甲苯酸的作用机制为","o":["抗血小板聚集","激活纤溶酶原","激活凝血酶","竞争性对抗纤溶酶原激活因子","灭活凝血酶"],"a":3,"e":"氨甲苯酸与纤溶酶原激活因子的赖氨酸结合位点结合，竞争性阻止纤溶酶原转变为纤溶酶，用于纤溶亢进所致出血。"},{"q":"能竞争性阻断NM受体的药物是","o":["筒箭毒碱","阿托品","乙酰胆碱","琥珀胆碱","酚妥拉明"],"a":0,"e":"筒箭毒碱为非除极化型肌松药，竞争性阻断骨骼肌运动终板N2受体，使肌松；琥珀胆碱则属除极化型肌松药。"},{"q":"关于硝酸甘油的药理作用正确的是","o":["收缩静脉","降低回心血量","减慢心率","增加室壁肌张力","增加前负荷"],"a":1,"e":"硝酸甘油扩张容量血管，使静脉回心血量减少、前负荷降低，心室壁张力下降，心肌耗氧量减少，从而缓解心绞痛。"},{"q":"强心苷治疗房颤的机制主要是","o":["减慢房室传导","缩短心房有效不应期","抑制窦房结","降低浦氏纤维自律性","降低心室率"],"a":0,"e":"强心苷兴奋迷走神经并直接抑制房室结传导，使房颤时过多冲动不能下传心室，从而减慢心室率，并不能终止房颤。"},{"q":"低温麻醉需要配合进行降温的药物是","o":["氯丙嗪","左旋多巴","琥珀胆碱","芬太尼","氟哌利多"],"a":0,"e":"氯丙嗪抑制下丘脑体温调节中枢，使体温随环境温度下降，配合物理降温可用于低温麻醉和人工冬眠。"},{"q":"氨苯喋啶的利尿作用机制是","o":["抑制K＋-Na＋-2Cl－共同转运系统","抑制Na＋-K＋转运系统","拮抗醛固酮","抑制碳酸酐酶","抑制远曲小管及集合管对NaCl的重吸收"],"a":1,"e":"氨苯蝶啶直接抑制远曲小管末端和集合管的Na+-K+交换，减少Na+重吸收与K+分泌，产生排钠保钾的利尿作用。"},{"q":"与阿托品阻断M受体无关的药理作用是","o":["扩大瞳孔","松弛内脏平滑肌","加快心率","扩张血管","抑制腺体分泌"],"a":3,"e":"阿托品大剂量扩张血管与阻断M受体无关，可能系直接扩张血管或抑制汗腺分泌致体温升高所致；扩瞳、抑制腺体、松弛平滑肌和加快心率均为M受体阻断所致。"},{"q":"可引起金鸡纳反应的抗心律失常药是","o":["奎宁","胺碘酮","奎尼丁","利多卡因","多非利特"],"a":2,"e":"奎尼丁为奎宁的右旋体，长期或大剂量应用可致金鸡纳反应，表现为耳鸣、听力减退、恶心呕吐、头痛及视力模糊。"},{"q":"以下容易造成二重感染的广谱抗菌药物是","o":["氯霉素","红霉素","克拉维酸","甲氧苄啶","链霉素"],"a":0,"e":"氯霉素为广谱抗生素，长期应用可致菌群失调，敏感菌被抑制而耐药菌或真菌大量繁殖，引起二重感染。"},{"q":"硝酸甘油抗心绞痛的主要作用原理是","o":["收缩冠状动脉，降低心肌自身负荷","减慢心率，降低心肌耗氧量","减少NO对心肌的损伤","扩张外周血管，降低心脏负荷和心肌耗氧量","降低血压，反射性兴奋交感神经改善心肌供血"],"a":3,"e":"硝酸甘油释放NO松弛血管平滑肌，扩张静脉和动脉，降低前后负荷及心室壁张力，减少心肌耗氧，并扩张冠脉侧支改善缺血区供血。"},{"q":"全身麻醉前给予阿托品的目的是","o":["镇静","增强麻醉药的作用","减少患者对术中的不良刺激的记忆","减少呼吸道腺体分泌","松弛骨骼肌"],"a":3,"e":"阿托品阻断M受体，抑制唾液腺和呼吸道腺体分泌，减少全麻时分泌物积聚与误吸，并防止术中迷走神经反射所致心动过缓。"},{"q":"腺垂体分泌的FSH、LH，可使下丘脑的GnRH释放减少，这一过程被称为","o":["长反馈","短反馈","超短反馈","正反馈","允许作用"],"a":1,"e":"腺垂体分泌的FSH、LH对下丘脑GnRH分泌的负反馈称短反馈；靶腺激素对下丘脑和腺垂体的反馈为长反馈，GnRH对自身分泌的反馈为超短反馈。"},{"q":"灰黄霉素对哪种真菌病无效","o":["甲癣","牛皮癣","头癣","体癣","深部真菌病"],"a":4,"e":"灰黄霉素仅对皮肤癣菌等浅部真菌有效，对念珠菌、隐球菌等深部真菌无效，故不能用于深部真菌病。"},{"q":"阿司匹林解热作用机制是","o":["抑制环氧酶，减少PG合成","抑制下丘脑体温调节中枢","抑制致炎因子的合成","杀菌作用","中和内毒素"],"a":0,"e":"阿司匹林抑制下丘脑体温调节中枢的环氧酶，减少前列腺素E合成，使升高的体温调定点下移，只降低发热体温而不影响正常体温。"},{"q":"羟甲唑啉用于鼻充血时应采用的剂型是","o":["口服制剂","注射制剂","气雾剂","滴鼻剂","缓释剂"],"a":3,"e":"羟甲唑啉为α受体激动药，收缩鼻黏膜血管、减轻充血水肿，局部应用制成滴鼻剂；口服无效且易引起全身不良反应。"},{"q":"甲巯咪唑最严重的不良反应是","o":["药疹","关节痛","粒细胞缺乏","血管神经性水肿","腹痛、腹泻"],"a":2,"e":"甲巯咪唑最严重的不良反应是粒细胞缺乏症，多发生于用药后2～3个月内，用药期间应定期查血象，出现咽痛发热立即停药。"},{"q":"巴比妥类药物随剂量由小到大依次表现为","o":["镇静、催眠、抗惊厥、麻醉","催眠、镇静、麻醉、抗惊厥","镇静、催眠、麻醉、抗惊厥","镇静、抗惊厥、麻醉、催眠","镇静、麻醉、抗惊厥、催眠"],"a":0,"e":"巴比妥类随剂量增大依次产生镇静、催眠、抗惊厥和麻醉作用，剂量过大则抑制延髓生命中枢，引起呼吸循环衰竭。"},{"q":"青霉素G不是治疗下列哪种病原体所致感染的主要药物","o":["溶血性链球菌","螺旋体","白喉杆菌","淋病奈瑟菌","军团菌"],"a":4,"e":"军团菌为胞内寄生菌，青霉素G对其无效，应选大环内酯类或氟喹诺酮类；溶血性链球菌、螺旋体、白喉杆菌和淋病奈瑟菌均对青霉素G敏感。"},{"q":"可取消迟后除极所引起的触发活动的药物是","o":["地高辛","维拉帕米","阿托品","异丙肾上腺素","肾上腺素"],"a":1,"e":"迟后除极由细胞内Ca2+超载引起，维拉帕米阻滞L型钙通道，减少Ca2+内流，可取消迟后除极所致的触发活动。"},{"q":"主要合成和分泌盐皮质激素的部位是","o":["垂体前叶","下丘脑","球状带","束状带","网状带"],"a":2,"e":"肾上腺皮质球状带合成醛固酮等盐皮质激素，束状带合成糖皮质激素，网状带分泌性激素，三带结构不同、分泌功能各异。"},{"q":"毛果芸香碱不适用于治疗","o":["开角型青光眼","闭角型青光眼","阿托品中毒","虹膜睫状体炎","重症肌无力"],"a":4,"e":"毛果芸香碱为M受体激动药，用于开角型及闭角型青光眼、虹膜睫状体炎和阿托品中毒；重症肌无力属神经肌肉接头病变，须用新斯的明等抗胆碱酯酶药。"},{"q":"肥胖或超重的2型糖尿病患者推荐的一线治疗药物是","o":["阿卡波糖","胰高血糖素","二甲双胍","格列苯脲","罗格列酮"],"a":2,"e":"二甲双胍减少肝糖输出、增加外周组织对葡萄糖的摄取利用，不刺激胰岛素分泌，不增加体重，为肥胖或超重2型糖尿病的首选药。"},{"q":"可待因是","o":["兼有镇痛作用的镇咳药","兼有中枢和外周作用的镇咳药","非成瘾性镇咳药","外周性镇咳药","镇咳效果较吗啡好的镇咳药"],"a":0,"e":"可待因抑制延髓咳嗽中枢，镇咳作用强而迅速，同时激动阿片受体产生中等程度镇痛，属兼有镇痛作用的成瘾性镇咳药。"},{"q":"初发轻症高血压患者可首选使用的降压药物是","o":["中枢性降压药","血管平滑肌扩张药","利尿药","钾通道开放药","中枢降压药"],"a":2,"e":"利尿药降压作用温和、持久，可单用于轻中度高血压，尤适用于老年人及合并心力衰竭者，为一线基础降压药。"},{"q":"对革兰氏阴性及革兰氏阳性厌氧菌均具有较强的抗菌作用是","o":["多黏菌素B","青霉素G","阿米卡星","万古霉素","林可霉素"],"a":4,"e":"林可霉素对革兰阳性菌及各类厌氧菌包括脆弱拟杆菌均有较强抗菌作用，对革兰阴性需氧菌无效，可用于厌氧菌感染。"},{"q":"高血压合并支气管哮喘的患者不宜用","o":["β受体阻断药","α受体阻断药","利尿药","扩血管药","钙通道阻断药"],"a":0,"e":"β受体阻断药阻断支气管β2受体，使支气管平滑肌收缩，可诱发或加重哮喘，故高血压合并支气管哮喘者禁用。"},{"q":"筒箭毒碱过量致死的主要原因是","o":["直接抑制心脏","肋间肌和膈肌麻痹","严重损害肝肾功能","过敏性休克","显著抑制呼吸中枢"],"a":1,"e":"筒箭毒碱阻断运动终板N2受体，过量时呼吸肌受累，肋间肌和膈肌麻痹导致呼吸衰竭，为致死主因，应及时人工呼吸并用新斯的明解救。"},{"q":"毛果芸香碱引起调节痉挛的原因是","o":["兴奋瞳孔括约肌上的M受体","兴奋瞳孔开大肌上的α受体","兴奋睫状肌上的M受体","兴奋睫状肌上的α受体","兴奋睫状肌上的N受体"],"a":2,"e":"毛果芸香碱激动睫状肌环行纤维的M受体，使睫状肌收缩、悬韧带松弛、晶状体变凸，屈光度增加，出现视近清晰而视远模糊的调节痉挛。"},{"q":"下列哪种药物与呋塞米合用可增强耳毒性","o":["四环素","红霉素","链霉素","青霉素","氯霉素"],"a":2,"e":"链霉素本身具有耳毒性，与呋塞米合用可协同损伤内耳毛细胞，加重听力损害，两者联用应避免或减量。"},{"q":"强心苷减慢房颤时的心室率主要是由于","o":["减少房室结中的隐匿性传导","降低心房自律性","增加房室结中的隐匿性传导","降低心室自律性","降低窦房结自律性"],"a":2,"e":"强心苷减慢房室结传导并延长其不应期，使进入房室结的冲动隐匿性传导增多，更多冲动不能下传心室，从而减慢房颤时的心室率。"},{"q":"由于情绪激动引起的窦性心动过速最好选用","o":["苯妥英钠","奎尼丁","普萘洛尔","氟卡尼","利多卡因"],"a":2,"e":"普萘洛尔阻断窦房结β1受体，减慢4相自动除极速率，降低窦房结自律性，对交感神经兴奋所致窦性心动过速疗效好。"},{"q":"治疗精神分裂症的药物是","o":["地西泮","氟奋乃静","碳酸锂","哌唑嗪","阿米替林"],"a":1,"e":"氟奋乃静为吩噻嗪类抗精神病药，阻断中脑-皮质和中脑-边缘系统D2受体，控制精神分裂症的阳性症状；碳酸锂主要用于躁狂症。"},{"q":"下列抗高血压药物中，对心脏有明显的抑制作用的是","o":["维拉帕米","卡托普利","尼莫地平","硝苯地平","氯沙坦"],"a":0,"e":"维拉帕米对窦房结和房室结的钙通道阻滞作用强，明显抑制心肌收缩力和传导，可致心动过缓、传导阻滞；硝苯地平以扩血管为主，心脏抑制轻。"},{"q":"糖皮质激素引起的负氮平衡可选用的治疗药物是","o":["雌激素","雄激素","甲状腺素","胰岛素","ACTH"],"a":1,"e":"雄激素促进蛋白质合成，可纠正糖皮质激素所致蛋白质分解增强引起的负氮平衡，并有助于防治骨质疏松。"},{"q":"行胸部手术全麻，需要辅助使用除极化型肌松药，下列属于该类的药物是","o":["筒箭毒碱","琥珀胆碱","阿曲库铵","多库铵","米库铵"],"a":1,"e":"琥珀胆碱为除极化型肌松药，与运动终板N2受体结合后产生持久除极化，使终板对递质失去反应而肌松；筒箭毒碱等属非除极化型。"},{"q":"奥美拉唑属于","o":["H2受体阻断药","H＋-K＋-ATP酶抑制剂","M受体阻断药","胃泌素受体阻断药","抗幽门螺旋菌药"],"a":1,"e":"奥美拉唑为质子泵抑制药，在壁细胞泌酸小管的酸性环境中活化后与H+-K+-ATP酶共价结合，不可逆抑制胃酸分泌。"},{"q":"具有抗氧化作用的抗动脉粥样硬化药物是","o":["辛伐他汀","环丙贝特","普罗布考","考来烯胺","烟酸"],"a":2,"e":"普罗布考抗氧化作用强，能抑制LDL氧化修饰并促进胆固醇逆转运，降低血浆胆固醇，用于动脉粥样硬化及其并发症。"},{"q":"心房纤颤转律可使用的药物是","o":["奎尼丁","维拉帕米","腺苷","胺碘酮","普萘洛尔"],"a":0,"e":"奎尼丁阻滞Na+通道、延长心房有效不应期，抑制异位节律，可用于心房颤动和心房扑动的复律，转律前宜先用强心苷控制心室率。"},{"q":"预防过敏性哮喘最好选用","o":["麻黄碱","氨茶碱","色甘酸钠","沙丁胺醇","肾上腺素"],"a":2,"e":"色甘酸钠稳定肥大细胞膜，抑制抗原激发时过敏介质释放，只起预防作用，对已发作的哮喘无效，适用于过敏性哮喘的预防。"},{"q":"下列不属于胰岛素常见不良反应的是","o":["过敏反应","胃肠道反应","低血糖症","胰岛素耐受性","注射部位脂肪萎缩"],"a":1,"e":"胰岛素常见不良反应为低血糖、过敏反应、胰岛素耐受性和注射部位脂肪萎缩；胰岛素口服易被消化酶破坏，胃肠道反应不是其典型不良反应。"},{"q":"下列药物可首选治疗急性肺水肿的是","o":["氢氯噻嗪","乙酰唑胺","呋塞米","氨苯喋啶","螺内酯"],"a":2,"e":"呋塞米为高效能利尿药，静脉注射后迅速利尿并扩张静脉，降低心脏前负荷，是急性肺水肿的首选利尿药。"},{"q":"胺碘酮在分类上属于","o":["钠通道阻滞药","促钾外流药","延长动作电位时程药","β受体阻断药","钙通道阻滞药"],"a":2,"e":"胺碘酮属Ⅲ类抗心律失常药，阻滞钾通道，延长心房、心室及浦肯野纤维的动作电位时程和有效不应期。"},{"q":"长期大量应用糖皮质激素的不良反应是","o":["枯草热","骨质疏松","过敏性紫癜","血小板减少症","粒细胞减少症"],"a":1,"e":"长期大量应用糖皮质激素抑制成骨细胞、促进骨吸收并减少肠钙吸收，引起骨质疏松，以脊椎骨最明显，重者可致病理性骨折。"},{"q":"下列何为脑内最重要的抑制性递质","o":["5-HT","GABA","ACh","DA","NA"],"a":1,"e":"GABA是脑内含量最高的抑制性神经递质，作用于GABAA受体使Cl-通道开放，产生抑制性突触后电位。"},{"q":"下列哪点是镇静催眠药的共同不良反应","o":["明显缩短快动眼睡眠时间","视力模糊","明显诱导肝药酶","久用产生依赖性和成瘾","肝功能损害"],"a":3,"e":"各类镇静催眠药长期应用均可产生耐受性、依赖性和成瘾性，停药出现戒断症状，故应短期、间断使用。"},{"q":"子痫所致的惊厥可用下列哪种药物","o":["氯丙嗪","硝西泮","硫酸镁","地西泮","苯巴比妥"],"a":2,"e":"硫酸镁注射后Mg2+拮抗Ca2+参与的神经肌肉传递，抑制中枢神经系统和子宫平滑肌，是子痫所致惊厥的首选抗惊厥药。"},{"q":"相对生物利用度等于","o":["（AUC试药/AUC标准药）×100%","（AUC标准药/AUC试药）×100%","（AUC口服等量药后/AUC静脉注射等量药后）×100%","（AUC静脉注射等量药后/AUC口服等量药后）×100%","（AUC口服标准药后/AUC静脉注射等量药后）×100%"],"a":0,"e":"相对生物利用度以同一药物的标准制剂为参比，用待测试药与标准药的AUC比值计算，反映两种制剂吸收程度的差异。"},{"q":"钙拮抗药可用于治疗","o":["低血压","心绞痛","心力衰竭","肥厚性心肌病","心动过缓"],"a":1,"e":"钙通道阻滞药扩张外周血管和冠状动脉，降低心脏后负荷与心肌收缩力，增加心肌供血，用于各型心绞痛，对变异型心绞痛尤佳。"},{"q":"药理学效应可包括","o":["治疗作用与预防作用","选择作用","兴奋作用与抑制作用","特异性作用","治疗作用与毒性反应"],"a":2,"e":"药理效应是药物作用于机体后引起的机能改变，表现为兴奋和抑制两种基本形式，如心率加快为兴奋、心率减慢为抑制。"},{"q":"以下哪一项是胰岛素治疗的目标","o":["减少胰岛素的降解","增加胰岛素释放","抑制机体的生长","增加肌肉细胞对葡萄糖的摄取","促进胰岛素的合成"],"a":3,"e":"胰岛素与肌肉、脂肪细胞膜受体结合，促进葡萄糖转运体转位，增加外周组织对葡萄糖的摄取和利用，从而降低血糖。"},{"q":"抗菌药物是","o":["对病原菌有杀灭作用的药物","对病原菌有抑制作用的药物","对病原菌有杀灭或抑制作用的药物","能用于预防细菌性感染的药物","能治疗细菌性感染的药物"],"a":2,"e":"抗菌药物指对病原菌具有杀灭或抑制作用、用于防治细菌感染性疾病的药物，包括各类抗生素和人工合成抗菌药。"},{"q":"治疗阿尔茨海默病的药物不包括","o":["左旋多巴","他克林","多奈哌齐","石杉碱甲","占诺美林"],"a":0,"e":"左旋多巴用于帕金森病；阿尔茨海默病治疗药包括胆碱酯酶抑制药他克林、多奈哌齐、石杉碱甲、利斯的明及M受体激动药占诺美林。"},{"q":"下列哪一个利尿药不引起失钾","o":["阿米洛利","氯酞酮","呋塞米","布美他尼","氯噻嗪"],"a":0,"e":"阿米洛利阻断远曲小管和集合管Na+通道，减少Na+重吸收与K+分泌，属保钾利尿药，不引起失钾；呋塞米和噻嗪类均致低血钾。"},{"q":"抑制Na+-K+-2Cl-同向转运子的利尿药是","o":["氢氯噻嗪","呋塞米","氨苯蝶啶","螺内酯","甘露醇"],"a":1,"e":"呋塞米作用于髓袢升支粗段，抑制管腔膜上Na+-K+-2Cl-同向转运子，使NaCl重吸收减少，产生强大利尿作用。"},{"q":"甲氨蝶呤抗代谢作用机制是","o":["阻止嘧啶核苷酸合成","抑制DA多聚酶","抑制二氢叶酸还原酶","抑制核苷酸还原酶","抑制拓扑异构酶"],"a":2,"e":"甲氨蝶呤与二氢叶酸还原酶结合，阻止二氢叶酸还原为四氢叶酸，使胸腺嘧啶核苷酸和嘌呤合成受阻，属抗叶酸代谢药。"},{"q":"糖皮质激素可通过增加下列哪种物质抑制合成白三烯","o":["脂皮素","磷脂酶A2","前列腺素","白细胞介素","血小板活化因子"],"a":0,"e":"糖皮质激素诱导脂皮素-1生成，脂皮素-1抑制磷脂酶A2，减少花生四烯酸释放，从而减少白三烯和前列腺素合成。"},{"q":"治疗麻风病的首选药物是","o":["利福平","氨苯砜","乙胺丁醇","巯苯咪唑","氯法齐明"],"a":1,"e":"氨苯砜为砜类抗麻风病药，对麻风分枝杆菌有较强抑制作用，是治疗各型麻风病的首选药，常与利福平、氯法齐明联合应用。"},{"q":"可耗竭肾上腺素能神经末梢递质的药物","o":["可乐定","美卡拉明","利舍平","卡托普利","氢氯噻嗪"],"a":2,"e":"利舍平抑制囊泡膜胺泵，使去甲肾上腺素不能进入囊泡而被单胺氧化酶破坏，耗竭神经末梢递质，产生降压作用。"},{"q":"肾功能不全的病人患铜绿假单胞菌感染，治疗可选用","o":["多黏菌素E","氨苄西林","庆大霉素","羧苄西林","林可霉素"],"a":3,"e":"羧苄西林为抗铜绿假单胞菌的青霉素类，主要经肾排泄而肾毒性低，可用于肾功能不全者的铜绿假单胞菌感染；庆大霉素肾毒性大。"},{"q":"可用于治疗伤寒和副伤寒的药物是","o":["氯霉素","金霉素","四环素","红霉素","米诺环素"],"a":0,"e":"氯霉素对伤寒沙门菌有强大抗菌作用，曾为治疗伤寒、副伤寒的首选药，现仍可用于敏感菌所致伤寒。"},{"q":"可用于预防高原反应的利尿药是","o":["阿米洛利","螺内酯","美托拉宗","乙酰唑胺","呋塞米"],"a":3,"e":"乙酰唑胺抑制碳酸酐酶，减少脑脊液生成并纠正呼吸性碱中毒，可减轻头痛、恶心等症状，用于高原反应的预防。"},{"q":"以下药物无法对疟原虫提供有效预防效果的药物是","o":["氯喹","乙胺嘧啶","磺胺多辛","氨苯砜","甲硝唑"],"a":0,"e":"氯喹主要作用于红细胞内期裂体增殖，用于控制疟疾症状及间日疟根治，对红外期无效，不能作病因性预防；乙胺嘧啶等可杀灭红外期。"},{"q":"下列哪种强心苷口服后吸收最完全","o":["洋地黄毒苷","地高辛","黄夹苷","毛花苷C","毒毛花苷K"],"a":0,"e":"洋地黄毒苷脂溶性高，口服吸收率可达90%以上，是强心苷中口服吸收最完全者；地高辛吸收约60%～80%，毒毛花苷K口服吸收极少。"},{"q":"有关异烟肼的错误叙述是","o":["对结核杆菌有高度的选择性","肝毒性以快代谢型者较多见","口服易吸收","单用时结核杆菌不易产生耐药性","适用于治疗各种类型结核病的首选药"],"a":3,"e":"异烟肼单用易使结核杆菌产生耐药性，故须与其他抗结核药联合应用；其对结核杆菌选择性高、口服吸收好，肝毒性以快代谢型者多见。"},{"q":"静脉注射除极化型肌松药用于食道镜检查，该药具备的特点是","o":["产生肌松作用前无短暂的肌束颤动","连续用药不产生快速耐受性","过量不导致呼吸肌麻痹","新斯的明无法解救其中毒反应","治疗量有神经节阻断作用"],"a":3,"e":"琥珀胆碱为除极化型肌松药，其肌松作用不能被新斯的明拮抗，反可加重阻滞；过量应人工呼吸并输新鲜血补充胆碱酯酶。"},{"q":"药物进入细胞最常见的方式是","o":["特殊载体摄入","脂溶性跨膜扩散","胞饮现象","水溶扩散","氨基酸载体转运"],"a":1,"e":"大多数药物以简单扩散方式顺浓度差通过脂质双层，脂溶性高、解离度低的药物易跨膜转运，是药物吸收和分布的主要方式。"},{"q":"氨基糖苷类抗生素的体内过程，下列哪点不正确","o":["部分从肾脏排泄，部分在肝脏代谢","口服不易吸收","主要分布在细胞外液","脑脊液中浓度较低","内耳淋巴液浓度高"],"a":0,"e":"氨基糖苷类几乎全部以原形经肾小球滤过排出，在体内不被代谢；口服吸收少，主要分布于细胞外液，内耳淋巴液和肾皮质浓度高。"},{"q":"糖皮质激素用于炎症后期应用的目的在于","o":["具有强大抗炎作用，促进炎症消散","抑制肉芽组织生长，防止粘连和疤痕形成","促进炎症区血管收缩，降低通透性","稳定溶酶体膜，减少蛋白水解酶释放","抑制花生四烯酸释放，使PG合成减少"],"a":1,"e":"炎症后期糖皮质激素抑制成纤维细胞增生和肉芽组织形成，减少粘连和瘢痕，但同时也延缓创口愈合。"},{"q":"哌仑西平有下述哪项药理作用","o":["阻断H2受体，抑制胃酸分泌","阻断胃泌素受体，减少胃酸分泌","促进胃黏液分泌，保护胃黏膜","抗幽门螺杆菌","阻断M胆碱受体，抑制胃酸分泌"],"a":4,"e":"哌仑西平选择性阻断胃壁细胞M1受体，抑制基础胃酸和刺激性胃酸分泌，抑制胃酸作用较西咪替丁弱，用于消化性溃疡。"},{"q":"碳酸锂主要用于治疗","o":["躁狂症","抑郁症","焦虑症","精神分裂症","神经官能症"],"a":0,"e":"碳酸锂抑制肌醇磷酸酶，耗竭脑内磷脂酰肌醇，是治疗躁狂症的首选药，也可用于双相情感障碍的维持治疗。"},{"q":"下列药物中既能降低TG和VLDL，又能降低Lp(a)的是","o":["考来烯胺","普伐他汀","硫酸软骨素","二十二碳六烯酸","烟酸"],"a":4,"e":"烟酸抑制脂肪组织脂解，减少肝脏合成VLDL，使TG和VLDL降低，并减少ApoA-Ⅰ分解、降低Lp(a)，是升高HDL最强的调血脂药。"},{"q":"不属于哌替啶适应证的是","o":["术后镇痛","人工冬眠","心源性哮喘","麻醉前给药","支气管哮喘"],"a":4,"e":"哌替啶激动阿片受体，抑制呼吸并释放组胺，可诱发支气管痉挛，支气管哮喘者禁用；可用于术后镇痛、心源性哮喘及麻醉前给药。"},{"q":"不具有内在拟交感活性的选择性β受体阻断药是","o":["美托洛尔","普萘洛尔","醋丁洛尔","纳多洛尔","普拉洛尔"],"a":0,"e":"美托洛尔为选择性β1受体阻断药，无内在拟交感活性；醋丁洛尔、普拉洛尔有内在拟交感活性，普萘洛尔和纳多洛尔为非选择性。"},{"q":"普萘洛尔不能治疗","o":["室上性心动过速","心绞痛","高血压","心房颤动","房窒传导阻滞"],"a":4,"e":"普萘洛尔阻断β受体，抑制窦房结和房室结传导，可加重房室传导阻滞，故Ⅱ度以上房室传导阻滞禁用。"},{"q":"卡托普利的主要降压机制是","o":["利尿降压","血管扩张","阻滞钙通道","抑制血管紧张素转化酶","α受体阻断"],"a":3,"e":"卡托普利抑制血管紧张素转化酶，减少AngⅡ生成和醛固酮分泌，同时减少缓激肽降解，扩张血管、降低外周阻力而降压。"},{"q":"下列属于特异质反应的是","o":["高血压患者突然停用普萘洛尔出现血压升高","患者服用伯氨喹发生急性溶血性贫血","患者接受青霉素注射发生休克","患者使用阿托品后出现口干、视力模糊","患者使用巴比妥类药物次晨仍嗜睡、困倦"],"a":1,"e":"特异质反应与遗传性酶缺陷有关，葡萄糖-6-磷酸脱氢酶缺乏者服用伯氨喹可发生急性溶血性贫血，属典型特异质反应。"},{"q":"可以用双膦酸盐类治疗的疾病不包括","o":["原发性骨质疏松","糖皮质激素继发的骨质疏松","绝经后骨质疏松","骨质疏松性骨折","低钙血症"],"a":4,"e":"双膦酸盐抑制破骨细胞活性，用于原发性、绝经后及糖皮质激素所致骨质疏松和骨质疏松性骨折；其降低血钙，低钙血症者禁用。"},{"q":"糖皮质激素治疗哮喘的主要药理学作用是","o":["兴奋呼吸中枢","直接松弛支气管平滑肌","增强气道纤毛摆动","抗炎作用","增强哮喘患者的免疫功能"],"a":3,"e":"糖皮质激素抑制气道炎症细胞浸润和炎性介质释放，减轻黏膜水肿与黏液分泌，降低气道高反应性，是哮喘抗炎治疗的核心药物。"},{"q":"耐药性是指","o":["连续用药后药物在体内的蓄积现象","连续用药后机体对药物产生敏感现象","连续用药后细菌对药物的敏感性降低甚至消失","反复用药患者对药物产生生理依赖性","反复用药患者对药物产生精神依赖性"],"a":2,"e":"耐药性指长期应用抗菌药后病原体对药物的敏感性降低甚至消失，与机体反复用药产生的耐受性不同。"},{"q":"下列药物中属于选择性α2受体阻断药的是","o":["哌唑嗪","育亨宾","坦洛新","酚妥拉明","酚苄明"],"a":1,"e":"育亨宾选择性阻断α2受体，促进去甲肾上腺素释放；哌唑嗪、坦洛新阻断α1受体，酚妥拉明和酚苄明对α1、α2受体均有作用。"},{"q":"复方新诺明是以下哪两种药物的复方制剂","o":["新斯的明 + 诺氟沙星","甲氧苄啶 + 磺胺甲噁唑","新斯的明 + 甲氧苄啶","磺胺嘧啶 + 诺氟沙星","呋喃妥因 + 甲氧苄啶"],"a":1,"e":"复方新诺明由磺胺甲噁唑与甲氧苄啶按5∶1组成，二者分别抑制二氢蝶酸合酶和二氢叶酸还原酶，双重阻断叶酸合成，抗菌作用增强。"},{"q":"青霉素的抗菌作用机制主要是","o":["影响细菌叶酸代谢","抑制细菌细胞壁的合成","抑制细菌蛋白质的合成","抑制细菌DNA的合成","抑制细菌RNA的合成"],"a":1,"e":"青霉素与细菌青霉素结合蛋白结合，抑制转肽酶，阻碍肽聚糖交联，使细胞壁缺损，菌体膨胀破裂死亡，对繁殖期细菌作用强。"},{"q":"常用于抗心律失常的局麻药是","o":["普罗帕酮","罗哌卡因","利多卡因","丁卡因","丁哌卡因"],"a":2,"e":"利多卡因既是酰胺类局麻药，又是Ⅰb类抗心律失常药，静脉给药用于室性心律失常；罗哌卡因、丁卡因等仅作局部麻醉用。"},{"q":"卡托普利的抗高血压作用的机制是","o":["抑制肾素活性","抑制血管紧张素转化酶活性","抑制血管紧张素Ⅰ的生成","抑制β-羟化酶的活性","阻滞血管紧张素受体"],"a":1,"e":"卡托普利抑制血管紧张素转化酶活性，减少血管紧张素Ⅱ生成，并减少缓激肽降解，使血管扩张、血压下降。"},{"q":"长期使用血管紧张素转化酶抑制药最常见的不良反应是","o":["首剂低血压","咳嗽","高血钾","低血糖","肾功能损伤"],"a":1,"e":"ACEI抑制缓激肽降解，使缓激肽、前列腺素等在肺内蓄积，引起刺激性干咳，为最常见的不良反应，停药后多可消失。"},{"q":"下列药物具有降糖和抗利尿作用的是","o":["甲苯磺丁脲","格列吡嗪","苯乙双胍","二甲双胍","氯磺丙脲"],"a":4,"e":"氯磺丙脲为第一代磺酰脲类，刺激胰岛β细胞分泌胰岛素而降糖，同时促进抗利尿激素分泌，可用于尿崩症。"},{"q":"青霉素对下列何种疾病基本无效","o":["梅毒","非典型性肺炎","破伤风","猩红热","大叶性肺炎"],"a":1,"e":"非典型肺炎多由支原体、衣原体、军团菌引起，青霉素对其无效，应选大环内酯类或氟喹诺酮类；梅毒、破伤风、猩红热等青霉素有效。"},{"q":"强心苷中毒最常见的早期症状是","o":["心动过缓","室性早搏","视物模糊","头痛、失眠","厌食、恶心、呕吐"],"a":4,"e":"强心苷中毒早期以胃肠道反应最常见，表现为厌食、恶心、呕吐，常为中毒的最早表现；黄视、绿视等视觉异常属中毒先兆。"},{"q":"具有抗动脉粥样硬化作用的脂蛋白是","o":["LDL","HDL","IDL","Apo B","VLDL"],"a":1,"e":"HDL将外周组织胆固醇逆向转运至肝脏代谢，具有抗动脉粥样硬化作用，其水平升高为保护性因素；LDL升高则促进粥样斑块形成。"},{"q":"能与强心苷竞争Na＋-K＋-ATP酶的抗心律失常药是","o":["利多卡因","苯妥英钠","普萘洛尔","普罗帕酮","胺碘酮"],"a":1,"e":"苯妥英钠能与强心苷竞争心肌细胞膜Na+-K+-ATP酶，恢复酶活性、改善传导，用于强心苷中毒所致室性心律失常。"},{"q":"双嘧达莫是","o":["纤溶药","抗纤维蛋白溶解药","抗血小板药","促凝血药","抗贫血药"],"a":2,"e":"双嘧达莫抑制磷酸二酯酶使cAMP增多，并抑制腺苷摄取，从而抑制血小板聚集，属抗血小板药，用于血栓栓塞性疾病的防治。"},{"q":"抑制胆固醇在肝脏合成的药物是","o":["考来烯胺","烟酸","非诺贝特","阿托伐他汀","阿昔莫司"],"a":3,"e":"阿托伐他汀抑制HMG-CoA还原酶，阻断肝脏胆固醇合成，并上调LDL受体，使血浆LDL-C明显降低。"},{"q":"乙酰胆碱可引起","o":["心率增加","血管舒张","胃肠平滑肌舒张","瞳孔扩大","腺体分泌减少"],"a":1,"e":"乙酰胆碱激动血管内皮M3受体，使内皮细胞释放NO，松弛血管平滑肌引起血管舒张；对心脏则表现为负性频率和负性传导作用。"},{"q":"非甾体类抗炎药对以下哪种疼痛类型无效","o":["牙痛","痛经","一过性刺痛","癌症骨转移痛","产后疼痛"],"a":2,"e":"非甾体抗炎药通过抑制前列腺素合成缓解炎症性疼痛，对一过性刺痛无效，此类疼痛由直接刺激神经末梢引起，前列腺素不参与。"},{"q":"合并重度感染的糖尿病患者应选用的药物是","o":["甲苯磺丁脲","格列苯脲","苯乙双胍","正规胰岛素","精蛋白锌胰岛素"],"a":3,"e":"合并重度感染时应激使血糖升高、口服降糖药难以奏效，须用短效正规胰岛素控制血糖，便于按血糖水平随时调整剂量。"},{"q":"下列哪个药物因肝毒性较大目前已撤出治疗阿尔茨海默症的市场","o":["石杉碱甲","加兰他敏","多奈哌齐","利斯的明","他克林"],"a":4,"e":"他克林为第一代胆碱酯酶抑制药，肝毒性大，用药需监测肝功能，现已退出阿尔茨海默病治疗市场。"},{"q":"强心苷的临床应用有","o":["窦性心动过缓","心房扑动","传导阻滞","室性心动过速","室颤"],"a":1,"e":"强心苷用于慢性心力衰竭及心房颤动、心房扑动，通过减慢房室传导控制心室率；室性心动过速、传导阻滞和窦性心动过缓禁用。"},{"q":"氨基糖苷类抗生素的不良反应不包括","o":["耳毒性","肾毒性","肝毒性","过敏反应","神经肌肉阻断作用"],"a":2,"e":"氨基糖苷类主要不良反应为耳毒性、肾毒性、神经肌肉阻断和过敏反应；其在体内不被代谢，肝毒性不是其典型不良反应。"},{"q":"主要毒性是视神经炎的药物","o":["乙胺丁醇","异烟肼","利福平","链霉素","吡嗪酰胺"],"a":0,"e":"乙胺丁醇的主要毒性为球后视神经炎，表现为视敏度下降、红绿色盲，用药期间应定期检查视力和视野。"},{"q":"治疗月经痛可选用药","o":["对乙酰氨基酚","吗啡","哌替啶","阿托品","可待因"],"a":0,"e":"痛经与子宫内膜前列腺素增多引起子宫痉挛性收缩有关，对乙酰氨基酚抑制前列腺素合成，可缓解轻中度疼痛且胃肠刺激小。"},{"q":"高血压患者口服普萘洛尔吸收良好，但经过肝脏后仅有30%的药量达体循环，以致血药浓度较低，原因是","o":["化疗指数低","效价强度高","药物效能低","首过消除多","药物排泄快"],"a":3,"e":"普萘洛尔口服后经肠壁和肝脏代谢，首过消除显著，生物利用度仅约30%，故需加大口服剂量才能达到有效血药浓度。"},{"q":"磺胺类药物的作用机制是","o":["与PABA竞争二氢蝶酸合酶，阻止细菌二氢叶酸合成","抑制二氢叶酸还原酶","与PBP结合，抑制细菌细胞壁合成","抑制细菌蛋白质合成","抑制细菌DNA回旋酶"],"a":0,"e":"磺胺药与对氨基苯甲酸结构相似，竞争性抑制细菌二氢蝶酸合酶，阻止二氢叶酸合成；人体可直接利用叶酸，故不受影响。"},{"q":"华法林过量出血时可用的拮抗药是","o":["维生素C","维生素K","鱼精蛋白","氨甲苯酸","氨甲环酸"],"a":1,"e":"华法林抑制维生素K环氧化物还原酶，阻碍凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的γ-羧化；维生素K可逆转其抗凝作用，用于过量出血。"},{"q":"酚妥拉明兴奋心脏的主要机理是","o":["直接兴奋心肌","反射性兴奋交感神经","直接激动心脏β1受体","阻断心脏M受体","直接兴奋交感神经中枢"],"a":1,"e":"酚妥拉明阻断血管α1受体使血压下降，通过压力感受器反射性兴奋交感神经，使心率加快、心肌收缩力增强。"},{"q":"属于二氢吡啶类钙通道阻滞药的是","o":["维拉帕米","地尔硫䓬","硝苯地平","氟桂利嗪","普尼拉明"],"a":2,"e":"硝苯地平属二氢吡啶类钙通道阻滞药，选择性作用于血管平滑肌L型钙通道；维拉帕米和地尔硫䓬属非二氢吡啶类。"},{"q":"丙硫氧嘧啶最严重的不良反应是","o":["药疹、药热","关节痛、淋巴结肿大","腹痛、腹泻、恶心、呕吐","血管神经性水肿，喉头水肿","粒细胞缺乏症"],"a":4,"e":"丙硫氧嘧啶最严重的不良反应为粒细胞缺乏症，多见于用药后2～3个月，用药期间须定期查血象；其还可引起肝损害。"},{"q":"属于n-6型多烯脂肪酸的药物是","o":["亚油酸","α-亚麻油酸","二十碳五烯酸","二十二碳六烯酸","烟酸"],"a":0,"e":"亚油酸属n-6型多烯脂肪酸，在体内可转化为花生四烯酸；α-亚麻油酸、二十碳五烯酸和二十二碳六烯酸均属n-3型，烟酸为水溶性维生素。"},{"q":"叶酸在体内的活性形式是","o":["四氢叶酸","5-甲基四氢叶酸","叶酸","二氢叶酸","5，10-甲烯四氢叶酸"],"a":0,"e":"叶酸在体内经二氢叶酸还原酶两次还原生成四氢叶酸才具活性，后者作为一碳单位传递体参与嘌呤与嘧啶核苷酸合成。"},{"q":"对支气管平滑肌选择性较高的药物是","o":["异丙托溴铵","溴丙胺太林","溴甲东莨菪碱","溴甲后马托品","溴化甲哌佐酯"],"a":0,"e":"异丙托溴铵为吸入性季铵类M受体阻断药，对支气管平滑肌选择性高，可解除气道痉挛；溴丙胺太林等对腺体及胃肠平滑肌作用更明显。"},{"q":"强心苷中毒所致室性心律失常可选用","o":["利多卡因","美西律","普萘洛尔","地尔硫䓬","普鲁卡因胺"],"a":0,"e":"利多卡因属ⅠB类，促进K+外流、缩短复极，对希-浦系统及心室肌作用强，为强心苷中毒所致室性心律失常的首选。"},{"q":"可诱发或加重支气管哮喘的药物是","o":["普萘洛尔","沙丁胺醇","阿托品","哌唑嗪","酚妥拉明"],"a":0,"e":"普萘洛尔阻断支气管平滑肌β2受体，使气道收缩、阻力增加，哮喘患者可被诱发或加重发作；沙丁胺醇为β2激动药，作用相反。"},{"q":"下述何种药物中毒引起血压下降时，禁用肾上腺素","o":["苯巴比妥","地西泮","氯丙嗪","水合氯醛","吗啡"],"a":2,"e":"氯丙嗪阻断血管α受体，中毒低血压时肾上腺素的α缩血管作用被阻断、β2扩血管作用占优，血压反降，故改用去甲肾上腺素。"},{"q":"吗啡的镇痛作用原理","o":["激动阿片受体，模拟内阿片肽","阻断疼痛冲动向大脑皮质传导","阻断阿片受体，拮抗内阿片肽","抑制体内致痛介质的合成和释放","降低痛觉感受器对疼痛刺激的敏感性"],"a":0,"e":"吗啡激动中枢μ等阿片受体，模拟内阿片肽作用，抑制痛觉冲动传入并改变情绪反应而镇痛，其作用可被纳洛酮拮抗。"},{"q":"下列属于选择性β1受体阻断药的是","o":["普萘洛尔","纳多洛尔","拉贝洛尔","卡维地洛","美托洛尔"],"a":4,"e":"美托洛尔对β1受体选择性高，治疗量对β2受体影响小；普萘洛尔、纳多洛尔为非选择性，拉贝洛尔、卡维地洛兼阻断α受体。"},{"q":"可乐定的降压机制是","o":["激动中枢的I1咪唑啉受体","阻断中枢的α2受体","激动中枢的α1受体","激动中枢的M受体","激动中枢的多巴胺受体"],"a":0,"e":"可乐定激动延髓孤束核α2受体和腹外侧区I1咪唑啉受体，减少交感冲动传出而降压；单纯阻断α2受体并无此效应。"},{"q":"既可用于治疗青光眼，又可用于脑水肿的药物是","o":["氢氯噻嗪","呋塞米","螺内酯","甘露醇","阿米洛利"],"a":3,"e":"甘露醇提高血浆渗透压，使组织间液向血循环转移，降低颅内压和眼内压，故脑水肿与青光眼急性发作均可应用。"},{"q":"介导阿托品对膀胱收缩抑制作用最重要的M受体亚型是","o":["M1受体","M2受体","M3受体","M4受体","M5受体"],"a":2,"e":"膀胱逼尿肌以M3受体为主，阿托品阻断后逼尿肌松弛、括约肌张力相对增高，可缓解尿频尿急，故为解痉首选受体亚型。"},{"q":"治疗糖尿病昏迷应选用","o":["甲苯磺丁脲","格列齐特","地特胰岛素","正规胰岛素","精蛋白锌胰岛素"],"a":3,"e":"正规胰岛素起效快、可静脉给药，能迅速纠正酮症酸中毒和高渗性昏迷；精蛋白锌胰岛素起效慢，不宜用于急救。"},{"q":"可治疗心房纤颤的药物是","o":["利多卡因","美西律","苯妥英钠","胺碘酮","普鲁卡因胺"],"a":3,"e":"胺碘酮延长心房肌、心室肌及浦肯野纤维的动作电位时程和有效不应期，可转复房颤并维持窦性心律。"},{"q":"苯巴比妥长期应用产生耐受性的主要原因是","o":["重分布，贮存于脂肪组织内","被血浆中假性胆碱酯酶迅速水解破坏","以原型从肾脏排泄加快","诱导肝药酶加快自身代谢","GABA受体下调"],"a":3,"e":"苯巴比妥诱导肝药酶CYP，加速自身代谢，反复用药后血药浓度下降、疗效减弱，形成耐受性。"},{"q":"氯丙嗪过量引起血压下降时，应选用的药物是","o":["肾上腺素","去甲肾上腺素","阿托品","多巴胺","异丙肾上腺素"],"a":1,"e":"氯丙嗪阻断α受体致低血压，去甲肾上腺素以α激动为主可有效升压；肾上腺素因β2扩血管作用占优会进一步降压。"},{"q":"下列哪个药物是单纯疱疹病毒感染的首选药物","o":["齐多夫定","拉米夫定","糖皮质激素","阿昔洛韦","阿糖腺苷"],"a":3,"e":"阿昔洛韦在感染细胞内经病毒胸苷激酶磷酸化，抑制病毒DNA聚合酶，为单纯疱疹病毒感染的首选药。"},{"q":"给予普萘洛尔后，异丙肾上腺素的降压作用将会","o":["进一步加强","减弱","转为升压","先升压再降压","先降压再升压"],"a":1,"e":"异丙肾上腺素降压依靠β2受体舒张血管，普萘洛尔阻断β2受体后该作用减弱，故其降压效应降低。"},{"q":"阿托品禁用于","o":["流涎症","前列腺肥大","心动过缓","胃痉挛","虹膜睫状体炎"],"a":1,"e":"阿托品阻断M受体使膀胱逼尿肌松弛，前列腺肥大者易致急性尿潴留，属禁忌；青光眼及幽门梗阻亦禁用。"},{"q":"heparin的中文名是","o":["双香豆素","肝素","华法林","噻氯匹啶","阿司匹林"],"a":1,"e":"肝素为黏多糖硫酸酯，依赖抗凝血酶Ⅲ灭活凝血酶及因子Ⅹa，体内外均有抗凝作用；双香豆素、华法林属香豆素类。"},{"q":"噻嗪类利尿药的利尿作用机制是","o":["增加肾小球滤过率","抑制近曲小管碳酸酐酶，减少H＋-Na＋交换","抑制髓袢升支粗段髓质部Na＋-K＋-Cl－共转运子","抑制远曲小管近端Na＋-Cl－共转运子","抑制远曲小管K＋-Na＋交换"],"a":3,"e":"噻嗪类抑制远曲小管近端Na+-Cl-共转运子，减少Na+重吸收而利尿；抑制髓袢升支粗段共转运子者为呋塞米。"},{"q":"临床最常用的抗躁狂症药是","o":["碳酸锂","氯丙嗪","舒必利","氯普噻吨","氟西汀"],"a":0,"e":"碳酸锂抑制肌醇磷酸酶，降低神经元兴奋性，为临床最常用的抗躁狂药，对躁狂发作疗效确切。"},{"q":"具有一定肾毒性的β-内酰胺类抗生素是","o":["青霉素G","耐酶青霉素类","半合成广谱青霉素类","第一代头孢菌素类","第三代头孢菌素类"],"a":3,"e":"第一代头孢菌素经肾排泄并对肾小管有直接毒性，大剂量易致肾损害；第三代头孢菌素基本无肾毒性。"},{"q":"下列关于离子通道的选择性，说法错误的是","o":["钠通道是选择性允许Na+跨膜通过的离子通道，维持细胞膜的行为及其传导","膜上存在两大类钙离子通道：电压门控型和配体门控型","钾通道按照电生理特性可分为电压依赖性、钙依赖性、内向整流钾通道","氯离子通道可参与兴奋性细胞稳定膜电位，抑制动作电位的产生等","其他阳性离子也有部分可以通过钠、钾、钙通道进行跨膜转运"],"a":4,"e":"钠、钾、钙通道对相应离子高度选择性，只允许该离子顺电化学梯度通过，其他阳离子不能经此转运，故E项错误。"},{"q":"作用机制为抑制DNA合成的药物是","o":["磺胺类","万古霉素","异烟肼","红霉素","喹诺酮类"],"a":4,"e":"喹诺酮类抑制细菌DNA回旋酶和拓扑异构酶Ⅳ，阻碍DNA复制而杀菌；磺胺类则干扰叶酸代谢。"},{"q":"抗心绞痛药共有的药理作用是","o":["降低儿茶酚胺的生成","扩张冠状动脉","降低心肌的耗氧量","降低外周血管阻力","减慢心率"],"a":2,"e":"硝酸酯类、β受体阻断药和钙通道阻滞药均能降低心肌耗氧量，为抗心绞痛共同药理基础；普萘洛尔并无扩张冠脉作用。"},{"q":"酚妥拉明扩张血管主要是因为","o":["阻断NA能神经末梢突触前膜α2受体","兴奋血管平滑肌β2受体","阻断血管平滑肌M受体","阻断血管平滑肌α1受体","兴奋血管平滑肌M受体"],"a":3,"e":"酚妥拉明阻断血管平滑肌α1受体，取消去甲肾上腺素的缩血管作用，使血管扩张、外周阻力下降。"},{"q":"急性肾衰竭时，与利尿剂配伍增加尿量的药物是","o":["多巴胺","麻黄碱","去甲肾上腺素","异丙肾上腺素","肾上腺素"],"a":0,"e":"小剂量多巴胺激动肾血管多巴胺受体，扩张肾动脉、增加肾血流量和尿量，与利尿药合用可改善急性肾衰竭少尿。"},{"q":"四环素类主要不良反应是","o":["二重感染","灰婴综合征","对第八对脑神经损害","骨髓抑制","神经肌肉接头阻断"],"a":0,"e":"四环素类抑制敏感菌后，耐药菌与真菌乘虚繁殖引起二重感染，以假膜性肠炎和白色念珠菌感染多见。"},{"q":"阿利吉仑发挥降压作用主要是通过","o":["结合肾素作用于肾素-血管紧张素系统","直接抑制血管紧张素Ⅰ","直接抑制血管紧张素Ⅱ","直接抑制血管紧张素受体亚型1","利尿作用"],"a":0,"e":"阿利吉仑为直接肾素抑制剂，与肾素活性中心结合，阻止血管紧张素原转化为血管紧张素Ⅰ，从而降压。"},{"q":"糖皮质激素类药物隔日疗法的给药方式是","o":["隔日一次，下午4时给药","隔日一次，中午12时给药","隔日一次，晨8时给药","隔日一次，晚8时给药","隔日一次，午夜12时给药"],"a":2,"e":"隔日疗法顺应肾上腺皮质分泌的昼夜节律，晨8时分泌高峰给药，对下丘脑-垂体-肾上腺轴的抑制最轻。"},{"q":"下列关于塞来昔布的不良反应，正确的是","o":["磺胺类过敏的患者可以使用","胃肠道不良反应较轻","出血风险较高","几乎不会发生肾损伤","心血管系统不良反应较轻"],"a":1,"e":"塞来昔布选择性抑制COX-2，不影响胃黏膜COX-1，故胃肠道不良反应较轻，但磺胺类过敏者禁用。"},{"q":"普萘洛尔的临床应用不包括","o":["室上性心动过速","心绞痛","高血压","心房纤颤","重度房室传导阻滞"],"a":4,"e":"普萘洛尔阻断β受体，可加重房室传导阻滞、诱发严重心动过缓，重度房室传导阻滞属禁忌证。"},{"q":"胆道平滑肌痉挛引起的胆绞痛应选用","o":["哌替啶＋美沙酮","阿托品＋纳洛酮","吗啡＋纳洛酮","吗啡＋哌替啶","阿托品＋哌替啶"],"a":4,"e":"阿托品解除胆道平滑肌痉挛，哌替啶中枢镇痛，二者合用缓解胆绞痛；单用吗啡反使括约肌收缩、绞痛加剧。"},{"q":"选择性低的药物，在治疗量下表现为","o":["毒性较大","副作用较多","过敏反应剧烈","容易成瘾","容易耐药"],"a":1,"e":"药物选择性低时作用广泛，治疗量下与治疗目的无关的作用即副作用较多；毒性反应多与剂量过大有关。"},{"q":"在长期用药过程中，突然停药易引起严重高血压，这种药是","o":["普萘洛尔","肼屈嗪","哌唑嗪","氨氯地平","吲达帕胺"],"a":0,"e":"普萘洛尔长期阻断β受体致受体上调，突然停药出现交感活性反跳，可引起严重高血压、心绞痛加重甚至心肌梗死。"},{"q":"下列哪项不是抗菌药物联合用药的目的","o":["提高疗效","降低毒性","减少耐药性的发生","延长作用时间","扩大抗菌范围"],"a":3,"e":"联合用药旨在提高疗效、降低毒性、延缓耐药和扩大抗菌范围；延长作用时间靠剂型与给药间隔，不属联合用药目的。"},{"q":"主要用于治疗伴有醛固酮增高的顽固性水肿的药物是","o":["甘露醇","螺内酯","呋塞米","氨苯蝶啶","氢氯噻嗪"],"a":1,"e":"螺内酯竞争性拮抗醛固酮受体，适用于伴醛固酮增高的顽固性水肿，如肝硬化腹水和肾病综合征。"},{"q":"甲亢术前准备的正确给药方式是","o":["只给硫脲类","只给碘化物","给予放射性碘","先给硫脲类，术前两周再给碘化物","先给碘化物，术前两周再给硫脲类药物"],"a":3,"e":"硫脲类先控制甲亢症状并使腺体缩小变韧，术前两周加用大剂量碘抑制激素释放、减少腺体血供，便于手术。"},{"q":"格列齐特的主要作用机制是","o":["促进葡萄糖降解","拮抗胰高血糖素作用","刺激胰岛素","刺激胰岛β细胞释放胰岛素","减少胰外组织对胰岛素的敏感性和糖的利用"],"a":3,"e":"格列齐特属磺酰脲类，阻断胰岛β细胞ATP敏感钾通道，促细胞除极、Ca2+内流，释放胰岛素。"},{"q":"去甲肾上腺素减慢心率是由于","o":["降低外周阻力","抑制心脏传导","直接的负性频率作用","抑制心血管中枢的调节","血压升高引起的继发性效应"],"a":4,"e":"去甲肾上腺素强烈收缩血管使血压骤升，经颈动脉窦和主动脉弓压力感受器反射性兴奋迷走神经，心率减慢。"},{"q":"下列哪个是口服长效（1周1次）的抗精神分裂症药","o":["五氟利多","氯氮平","利培酮","氯丙嗪","舒必利"],"a":0,"e":"五氟利多口服后储存于脂肪组织缓慢释放，一次给药作用维持一周，适用于精神分裂症的维持治疗。"},{"q":"苯二氮䓬类药物不能单独用于下列何种情况","o":["入睡困难","焦虑症","抗惊厥","全身麻醉","癫痫持续状态"],"a":3,"e":"苯二氮䓬类仅有抗焦虑、镇静催眠、抗惊厥及中枢性肌松作用，单用不能达到全身麻醉所需的意识消失与镇痛。"},{"q":"药物经一级动力学消除的特点是","o":["恒比消除，半衰期恒定","恒量消除，半衰期恒定","恒比消除，半衰期不恒定","恒量消除，半衰期不恒定","消除速率与给药剂量无关"],"a":0,"e":"一级动力学消除指单位时间内消除恒定比例的药物，消除速率与血药浓度成正比，半衰期恒定且不随剂量改变。"},{"q":"兼具抗心律失常、抗高血压和抗心绞痛作用的药物是","o":["阿托品","普萘洛尔","异丙肾上腺素","硝酸甘油","可乐定"],"a":1,"e":"普萘洛尔阻断β1受体，减慢心率、降低心肌收缩力与耗氧量，兼具抗心律失常、抗高血压和抗心绞痛作用。"},{"q":"在药动学模型中，一室模型是指","o":["药物在全身各组织部位的转运速率是相同或者相似的，此时把整个机体视为一个房室","房室代表有腔室解剖部位，把整个机体视为一个房室","药物按两种速率消除，整体视为一个房室","将机体划分为药物分布均匀程度不同的两个独立系统，将整体视为一个房室","药物主要分布到较大的管腔器官，属于一个房室"],"a":0,"e":"一室模型把机体视为转运速率相同或相似的均一单元，药物进入后迅速均匀分布，血药浓度呈单指数衰减。"},{"q":"局麻药的作用机制主要是","o":["阻断钙离子通道","阻断钠离子通道","阻断钾离子通道","阻断镁离子通道","阻断氯离子通道"],"a":1,"e":"局麻药阻滞神经细胞膜电压门控钠通道，抑制Na+内流，使动作电位不能产生和传导，产生局部麻醉。"},{"q":"可制成喷雾制剂用于耳鼻咽喉科术前使用的药物是","o":["普鲁卡因","布比卡因","丁卡因","可卡因","罗哌卡因"],"a":2,"e":"丁卡因穿透力强、表面麻醉效果好而毒性较大不宜注射，常制成喷雾剂用于耳鼻咽喉科术前黏膜麻醉。"},{"q":"下列关于酚妥拉明药理作用的叙述，正确的是","o":["可阻断M胆碱受体","可激动5-HT受体","可翻转肾上腺素升压效应","可抑制心脏活动，降低心排量","对小静脉无舒张作用"],"a":2,"e":"酚妥拉明阻断α受体，取消肾上腺素缩血管的α效应，使β2扩血管作用显现，血压由升转降即升压效应被翻转。"},{"q":"如果某药在体内的转运与分布符合一房室模型，则该药","o":["仅存在于细胞外液中","高度解离，在体内被迅速消除","仅存在于血液中","转运快，在体内分布迅速达平衡","药物先进入血流量大的器官"],"a":3,"e":"一房室模型假定药物在各组织转运速率相近，静脉给药后迅速分布至全身体液并达动态平衡，血药浓度单相下降。"},{"q":"患者，老年男性，冠心病10余年，遵医嘱用小剂量阿司匹林防止冠脉血栓形成，其原理是","o":["抑制前列环素合成","抑制血栓素合成","抑制前列环素和血栓素合成","抑制花生四烯酸的合成","抑制磷酸二酯酶"],"a":1,"e":"小剂量阿司匹林不可逆抑制血小板COX-1，减少血栓素A2生成而抗血小板聚集，对血管内皮前列环素影响较小。"},{"q":"抗嘌呤代谢的抗癌药是","o":["顺铂","紫杉醇","阿糖胞苷","6-MP","5-FU"],"a":3,"e":"6-巯基嘌呤经次黄嘌呤-鸟嘌呤磷酸核糖转移酶活化，掺入DNA干扰嘌呤代谢；阿糖胞苷则作用于嘧啶代谢。"},{"q":"某药的t1/2是6小时，如果按0.5g一次，每天3次给药，达到血浆坪值的时间是","o":["5～10小时","10～16小时","17～23小时","24～30小时","31～36小时"],"a":3,"e":"按一级动力学给药，经4～5个半衰期血药浓度达坪值95%以上，t1/2为6小时，故约24～30小时达到稳态。"},{"q":"有关哌替啶的叙述，错误的是","o":["镇咳作用与可待因相似","镇痛作用比吗啡弱","成瘾性较吗啡轻","无止泻作用","治疗剂量能引起体位性低血压"],"a":0,"e":"哌替啶对咳嗽中枢无明显抑制作用，无镇咳用途，与可待因不同；其镇痛弱于吗啡、成瘾性较轻、无止泻作用。"},{"q":"四环素口服吸收后，分布于哪个部位的药物浓度比血液内的药物浓度高","o":["脑脊液","胆汁","前列腺","唾液腺","细胞外液"],"a":1,"e":"四环素类脂溶性高，经胆汁排泄并存在肝肠循环，胆汁中浓度可达血药浓度的数倍至数十倍。"},{"q":"肝细胞的微粒体混合功能氧化酶中，最重要的酶是","o":["单胺氧化酶","细胞色素P450","葡萄糖醛酸转移酶","乙醛脱氢酶","胆碱酯酶"],"a":1,"e":"肝微粒体混合功能氧化酶即细胞色素P450酶系，催化大多数药物的氧化、还原和水解，是药物代谢的关键酶。"},{"q":"引起病人对巴比妥类药物产生依赖性的主要原因是","o":["使病人产生欣快感","抑制肝药酶","能诱导肝药酶","停药后快动眼睡眠时间反跳性延长，引起睡眠障碍","受体下调"],"a":3,"e":"巴比妥类缩短快动眼睡眠，停药后该时相反跳性延长并伴多梦，患者为求睡眠反复用药而形成依赖性。"},{"q":"下列具有内在拟交感活性的非选择性β受体阻断药是","o":["吲哚洛尔","噻吗洛尔","醋丁洛尔","普萘洛尔","纳多洛尔"],"a":0,"e":"吲哚洛尔为非选择性β受体阻断药且具内在拟交感活性，对β2受体有部分激动，心率减慢和支气管收缩作用较轻。"},{"q":"降压时伴有心率加快、心输出量增加和肾素活性增高的药物是","o":["依那普利","可乐定","哌唑嗪","硝苯地平","普萘洛尔"],"a":3,"e":"硝苯地平阻滞血管平滑肌钙通道，降压同时反射性兴奋交感神经，致心率加快、心输出量增加、肾素活性升高。"},{"q":"关于糖皮质激素治疗哮喘的叙述，错误的是","o":["发挥局部抗炎作用","可吸入给药","抑制磷脂酶A2","减少白三烯的生成","通过抑制磷酸二酯酶"],"a":4,"e":"糖皮质激素抗哮喘主要经诱导脂皮素-1抑制磷脂酶A2，减少前列腺素和白三烯生成；抑制磷酸二酯酶是茶碱的机制。"},{"q":"糖尿病患者合并重度感染时宜选用","o":["罗格列酮","磺酰脲类","双胍类","胰岛素","α-葡萄糖苷酶抑制药"],"a":3,"e":"重度感染时机体处于应激状态，胰岛素需要量增加，口服降糖药难以控制，应改用胰岛素并调整剂量。"},{"q":"下列药物可通过血脑屏障的是","o":["乙酰胆碱","毛果芸香碱","卡巴胆碱","醋甲胆碱","氯贝胆碱"],"a":1,"e":"毛果芸香碱为叔胺类生物碱，脂溶性高易透过血脑屏障；乙酰胆碱等季铵类化合物难以进入中枢。"},{"q":"属三环类抗抑郁药的是","o":["丙米嗪","氯丙嗪","碳酸锂","氟哌啶醇","舒必利"],"a":0,"e":"丙米嗪为三环类抗抑郁药，抑制突触前膜对去甲肾上腺素和5-羟色胺的再摄取；氯丙嗪、氟哌啶醇属抗精神病药。"},{"q":"下列不属于抗心律失常药物作用方式的是","o":["阻滞钠通道","拮抗心脏的交感效应","阻滞钾通道","阻滞钙通道","阻滞水通道"],"a":4,"e":"抗心律失常药通过阻滞钠、钙、钾通道或拮抗β受体发挥疗效，阻滞水通道并非其作用方式。"},{"q":"下列关于半最大效应浓度的描述中，正确的是","o":["常用于表示药物的亲和力","指能引起50%最大效应的药物浓度","常见的表述形式为ED5和ED50","常见的表述形式为LD50和LD95","常见的表述形式为TD50"],"a":1,"e":"半最大效应浓度即EC50，指能引起50%最大效应的药物浓度，反映效价强度；亲和力常以KD表示。"},{"q":"某药t1/2为12小时，单次静脉给药后，最少几天后血药浓度小于高峰浓度的2%","o":["1天","2天","3天","4天","6天"],"a":2,"e":"血药浓度降至高峰的2%需约5.6个半衰期，t1/2为12小时，约67小时，故最少3天后达标。"},{"q":"抑制T4转化为T3的抗甲状腺药物是","o":["放射性碘","卡比马唑","甲苯磺丁脲","碘制剂","丙硫氧嘧啶"],"a":4,"e":"丙硫氧嘧啶抑制甲状腺过氧化物酶，并阻断外周组织T4脱碘转化为活性更强的T3，甲亢危象时尤为适用。"},{"q":"可引起血钾增高的药物是","o":["氢氯噻嗪","呋塞米","依他尼酸","吲哒帕胺","氨苯蝶啶"],"a":4,"e":"氨苯蝶啶阻断远曲小管和集合管钠通道，减少Na+重吸收与K+分泌，久用致高血钾；噻嗪类、袢利尿药则致低血钾。"},{"q":"有机磷农药中毒的机制是","o":["直接兴奋M受体","直接兴奋N受体","抑制胆碱酯酶活性","抑制细胞色素氧化酶","抑制转肽酶"],"a":2,"e":"有机磷与胆碱酯酶结合形成磷酰化胆碱酯酶，使酶失活，乙酰胆碱在突触和神经肌肉接头蓄积而中毒。"},{"q":"为下列感染选择有效的联合用药方案抗药性金葡菌感染","o":["青霉素G＋链霉素","羧苄西林＋庆大霉素","青霉素G＋四环素","苯唑西林＋庆大霉素","异烟肼＋链霉素"],"a":3,"e":"苯唑西林耐β-内酰胺酶，对产酶耐药金葡菌有效，联合庆大霉素可增强杀菌并延缓耐药。"},{"q":"肾功能不全应避免或慎用的药物是","o":["氯霉素","利福平","氨基糖苷类","氨苄西林","甘露醇"],"a":2,"e":"氨基糖苷类经肾小球滤过排出并在近曲小管蓄积，肾功能不全时排泄减慢、耳肾毒性加重，应避免或减量慎用。"},{"q":"属于广谱抗心律失常药的是","o":["氟卡尼","奎尼丁","维拉帕米","苯妥英钠","多非利特"],"a":1,"e":"奎尼丁阻滞钠通道，兼有抗胆碱及α受体阻断作用，对房性和室性心律失常均有效，属广谱抗心律失常药。"},{"q":"弱酸性药物在酸性环境中","o":["容易吸收","解离多","排泄不变","不容易吸收","排泄较快"],"a":0,"e":"弱酸性药物在酸性胃液中解离少、脂溶性高，易跨膜吸收；碱化尿液则解离增多、重吸收减少而排泄加快。"},{"q":"可使皮肤、黏膜血管收缩，骨骼肌血管扩张的药物是","o":["去甲肾上腺素","普萘洛尔","肾上腺素","异丙肾上腺素","间羟胺"],"a":2,"e":"肾上腺素激动α1受体使皮肤、黏膜及内脏血管收缩，激动β2受体使骨骼肌血管扩张，呈现血流重分布。"},{"q":"以下药物中不具有增强免疫系统效果的是","o":["左旋咪唑","干扰素","卡介苗","泼尼松","胸腺肽"],"a":3,"e":"泼尼松为糖皮质激素，抑制巨噬细胞吞噬和淋巴细胞增殖、减少抗体生成，属免疫抑制药而非增强药。"},{"q":"在碱性尿液中弱碱性药物","o":["解离多，重吸收少，排泄快","解离少，重吸收多，排泄快","解离多，重吸收多，排泄快","解离少，重吸收多，排泄慢","解离多，重吸收少，排泄慢"],"a":3,"e":"弱碱性药物在碱性尿中解离少、脂溶性高，易被肾小管重吸收，故重吸收多、排泄慢；酸化尿液则相反。"},{"q":"可引起高血钾的药物是","o":["氨苯蝶啶","氢氯噻嗪","布美他尼","依他尼酸","乙酰唑胺"],"a":0,"e":"氨苯蝶啶为保钾利尿药，抑制集合管钠通道、减少钾分泌而致高血钾；噻嗪类、袢利尿药及乙酰唑胺均致低血钾。"},{"q":"麻醉时用于控制血压，减少手术区出血的神经节阻断药是","o":["美卡拉明","利多卡因","普鲁卡因","筒箭毒碱","地西泮"],"a":0,"e":"美卡拉明阻断自主神经节N1受体，使血管扩张、血压下降，曾用于控制性降压以减少手术野出血。"},{"q":"大多数抗癌药常见的严重不良反应是","o":["肝脏损害","脱发","心肌损害","骨髓抑制","过敏反应"],"a":3,"e":"多数抗癌药缺乏选择性，对增殖旺盛的骨髓造血细胞同样抑制，骨髓抑制为最常见且严重的剂量限制性毒性。"},{"q":"青霉素最常见和应警惕的不良反应是","o":["变态反应","腹泻、恶心、呕吐","听力减退","二重感染","肝、肾损害"],"a":0,"e":"青霉素降解产物与体内蛋白结合成全抗原，引起皮疹乃至过敏性休克，为最常见且必须警惕的不良反应。"},{"q":"因某种全麻辅助用药导致的中毒反应，可选用新斯的明进行解救，该药引起中毒反应的原因是","o":["与抗胆碱酯酶药有加强作用","肌松作用最短，并有骨骼肌的始期纤颤","升高血钾","非除极化型肌松药","主要被假性胆碱酯酶水解"],"a":3,"e":"新斯的明抑制胆碱酯酶、增加接头处乙酰胆碱，可竞争性对抗非去极化型肌松药的阻滞，故其中毒源于该类肌松药。"},{"q":"下列不属于心律失常主要发生机制的是","o":["折返","自律性升高","早后除极","迟后除极","体外循环"],"a":4,"e":"心律失常发生机制为自律性升高、折返及触发活动（早后、迟后除极）；体外循环是治疗条件，并非发生机制。"},{"q":"对变异型心绞痛疗效最好的药物是","o":["硝酸甘油","普萘洛尔","硝苯地平","单硝酸异山梨酯","维拉帕米"],"a":2,"e":"变异型心绞痛由冠脉痉挛所致，硝苯地平阻滞血管平滑肌钙通道，解除痉挛并扩张冠脉，疗效最佳。"},{"q":"对磺酰脲类过敏的糖尿病患者仍可使用的药物是","o":["格列苯脲","格列吡嗪","甲苯磺丁脲","氯磺丙脲","瑞格列奈"],"a":4,"e":"瑞格列奈为格列奈类，经不同位点阻断β细胞钾通道促胰岛素释放，结构不同于磺酰脲类，故磺酰脲过敏者可用。"},{"q":"能很有效性治疗癫痫大发作而又无催眠作用的药物是","o":["地西泮","苯巴比妥钠","乙琥胺","苯妥英钠","扑米酮"],"a":3,"e":"苯妥英钠阻滞钠通道，阻止异常放电向周围扩散，对大发作疗效好且无催眠作用，为治疗大发作的主要药物。"},{"q":"应用利福平容易出现的不良反应是","o":["可引起肝损害，并能激活肝药酶","视神经炎","外周神经炎","使中枢抑制性神经递质GABA生成减少","耳、肾毒性"],"a":0,"e":"利福平经肝代谢，可致转氨酶升高和黄疸，又是强效肝药酶诱导剂，能加速华法林、口服避孕药等代谢。"},{"q":"关于青霉素过敏性休克，下列哪种说法不正确","o":["头孢菌素类与青霉素类之间可能有交叉过敏","对青霉素G过敏者可以改用阿莫西林口服","用药前必须皮试","每次用药后应观察半小时","在抢救时必须使用肾上腺素"],"a":1,"e":"阿莫西林与青霉素G同属β-内酰胺类，存在交叉过敏，青霉素过敏者不可改用，头孢菌素类亦应慎用。"},{"q":"细菌对氨基糖苷类抗生素耐药的主要原因是","o":["细菌产生大量PABA","细菌产生大量二氢蝶酸合成酶","细菌产生水解酶","细菌产生钝化酶","细菌细胞膜通透性降低"],"a":3,"e":"细菌产生乙酰化酶、磷酸化酶等钝化酶，使氨基糖苷类结构改变而失活，是其耐药的主要机制。"},{"q":"硫糖铝治疗消化性溃疡的机制是","o":["中和胃酸","抑制胃酸分泌","保护胃肠黏膜","抗幽门螺杆菌","促进胃肠动力"],"a":2,"e":"硫糖铝在胃酸中解离并聚合成胶体，附着于溃疡面形成保护膜，同时吸附胃蛋白酶和胆盐，属黏膜保护药。"},{"q":"胺碘酮少见的不良反应是","o":["窦性心动过缓","眼角膜微粒沉淀","房室传导阻滞","肺纤维化","低血压"],"a":3,"e":"胺碘酮含碘量高，长期用药可致角膜微粒沉着及甲状腺功能异常；肺间质纤维化发生率低但最严重，属少见不良反应。"},{"q":"支气管哮喘的患者应慎用或禁用","o":["沙丁胺醇","异丙肾上腺素","普萘洛尔","糖皮质激素","氨茶碱"],"a":2,"e":"普萘洛尔阻断支气管平滑肌β2受体，使气道收缩、阻力增加，支气管哮喘患者应慎用或禁用。"},{"q":"强心苷最适宜治疗的心衰是","o":["心包缩窄引起的心衰","肺源性心脏病引起的心衰","高血压性心衰伴有房颤","甲状腺功能亢进的心衰","严重贫血引起的心衰"],"a":2,"e":"强心苷增强心肌收缩力并减慢房室传导，高血压性心衰伴房颤者既改善心功能又可控制心室率，故最适宜。"},{"q":"尼可地尔的作用是","o":["激活KATP钾通道，促进K＋外流","激活KACh钾通道，促进K＋外流","阻滞钙通道，减少钙内流","阻滞钠通道，抑制细胞膜除极","促进血管平滑肌细胞膜上的Na＋-Ca2＋交换，增加细胞内钙"],"a":0,"e":"尼可地尔为钾通道开放药，激活血管平滑肌ATP敏感钾通道，K+外流使膜超极化、Ca2+内流减少，血管扩张。"},{"q":"对心率和血压无明显影响的选择性α1受体阻断药是","o":["酚苄明","哌唑嗪","坦洛新","酚妥拉明","育亨宾"],"a":2,"e":"坦洛新选择性阻断α1A受体，主要松弛前列腺和膀胱颈平滑肌，对血管α1B受体作用弱，故心率和血压无明显影响。"},{"q":"抗肿瘤药共有的毒性反应主要是","o":["肝脏毒性","肾脏毒性","骨髓抑制","神经毒性","过敏反应"],"a":2,"e":"抗肿瘤药对增殖旺盛的骨髓造血干细胞杀伤明显，骨髓抑制为共有的主要毒性，表现为白细胞及血小板减少。"},{"q":"双胍类降糖药最常见的不良反应是","o":["乳酸性酸中毒","肝功能异常","低血糖","过敏性皮疹","胃肠道反应"],"a":4,"e":"双胍类刺激胃肠道，引起恶心、呕吐、腹泻及口中金属味，胃肠道反应最常见，多随用药时间延长而减轻。"},{"q":"HMG-CoA还原酶抑制剂最严重的不良反应是","o":["甲状腺功能异常","中枢神经系统反应","肝损伤","横纹肌溶解症","肺纤维化"],"a":3,"e":"HMG-CoA还原酶抑制剂可致肌痛、肌酸激酶升高，严重者横纹肌溶解并引发急性肾衰竭，为最严重的不良反应。"},{"q":"链霉素不良反应不包括","o":["过敏性休克","肾损害","第八对脑神经损害","神经肌肉阻滞","灰婴综合征"],"a":4,"e":"灰婴综合征由氯霉素在新生儿引起，表现为循环衰竭、灰紫发绀；链霉素的不良反应为耳毒性、肾损害及神经肌肉阻滞。"},{"q":"地西泮不具有下列哪项作用","o":["镇静、催眠作用","中枢性肌松作用","抗癫痫作用","抗焦虑","抗躁狂症"],"a":4,"e":"地西泮作用于苯二氮䓬受体，具抗焦虑、镇静催眠、抗惊厥和中枢性肌松作用，无抗躁狂作用，抗躁狂用碳酸锂。"},{"q":"以下选项中可以通过抑制虫体微管聚集、葡萄糖摄取、减少ATP生成从而达到广谱驱虫效果的药物是","o":["阿苯达唑","左旋咪唑","哌嗪","吡喹酮","恩波吡维铵"],"a":0,"e":"阿苯达唑抑制虫体微管聚集，阻断葡萄糖摄取与ATP生成，对肠道线虫、绦虫及囊虫均有效，属广谱驱虫药。"},{"q":"全身应用毒性大，仅限于局部应用的药物是","o":["利巴韦林","干扰素","齐多夫定","碘苷","阿糖腺苷"],"a":3,"e":"碘苷为碘化胸苷类似物，全身应用毒性大，仅局部用于单纯疱疹性角膜炎；阿糖腺苷则可静脉给药。"},{"q":"治疗全身性深部真菌感染的首选药是","o":["灰黄霉素","制霉菌素","两性霉素B","克霉唑","咪康唑"],"a":2,"e":"两性霉素B与真菌细胞膜麦角固醇结合，形成孔道致胞内容物外漏，为全身性深部真菌感染的首选药。"},{"q":"强心苷正性肌力作用的表现不包括","o":["提高心肌收缩时最高张力","提高心肌收缩速率","心脏容积扩张","每搏输出量增加","不增加心肌耗氧量"],"a":2,"e":"强心苷正性肌力作用表现为收缩力增强、收缩速率加快、每搏输出量增加、心室容积缩小，心脏容积扩张与之相反。"},{"q":"香豆素类抗凝药最常见的给药途径是","o":["肌内注射","皮下注射","口服","舌下含服","静脉注射"],"a":2,"e":"香豆素类口服吸收完全，一般制成片剂经口服用，起效慢需数日方达抗凝高峰；肝素在消化道被破坏，只能静脉或皮下注射。"},{"q":"不能引起调节麻痹作用的药物是","o":["阿托品","后马托品","尤卡托品","托吡卡胺","环喷托酯"],"a":2,"e":"尤卡托品仅阻断瞳孔括约肌的M受体而散瞳，对睫状肌作用弱，不引起调节麻痹，适用于眼底检查。"},{"q":"属于皮质激素类药物共有的基本结构是","o":["C4-5之间为一双键","C1-2之间为一双键","C17上有α羟基","C11上无氧","C9上有氟（F）"],"a":0,"e":"肾上腺皮质激素母核为甾环，C4-5间双键为共有必需基团；C1-2双键、C9氟及C17羟基仅见于部分衍生物。"},{"q":"必须与胃壁细胞分泌的糖蛋白即“内因子”结合才能吸收的抗贫血药是","o":["枸橼酸铁铵","叶酸","硫酸亚铁","维生素B12","右旋糖酐铁"],"a":3,"e":"维生素B12须与胃壁细胞分泌的内因子结合成复合物，在回肠末端吸收；叶酸和铁剂的吸收不依赖内因子。"},{"q":"胰岛素对糖代谢的影响是","o":["抑制葡萄糖向组织细胞内转移","抑制葡萄糖的氧化和酵解","促进糖原的分解和异生","抑制糖原的合成和储存","降低血糖"],"a":4,"e":"胰岛素促进葡萄糖转运入细胞，加速糖原合成与氧化酵解并抑制糖异生，总效应为降低血糖。"},{"q":"下列哪项是吗啡的作用","o":["兴奋呼吸","止吐","止泻","升高血压","散瞳"],"a":2,"e":"吗啡激动肠道阿片受体，使胃肠蠕动减慢、括约肌张力增高而致便秘，故有止泻作用；其对呼吸、瞳孔和颅内压作用相反。"},{"q":"有首过消除的给药途径是","o":["直肠给药","舌下给药","静脉给药","喷雾给药","口服给药"],"a":4,"e":"口服给药经胃肠吸收后先经门静脉入肝，部分被肝药酶灭活，称首过消除；舌下和直肠给药可部分避免。"},{"q":"不具有溶栓作用的药物是","o":["肝素","链激酶","尿素酶","组织纤溶酶原激活剂","阿尼普酶"],"a":0,"e":"肝素通过抗凝血酶Ⅲ抑制凝血因子，对已形成血栓无溶解作用；链激酶、组织纤溶酶原激活剂及阿尼普酶均属溶栓药。"},{"q":"抗高血压药中，不属于交感神经抑制药的是","o":["莫索尼定","美卡拉明","利血平","普萘洛尔","米诺地尔"],"a":4,"e":"米诺地尔开放血管平滑肌ATP敏感钾通道直接舒张血管，不作用于交感神经；莫索尼定、美卡拉明、利血平、普萘洛尔均属交感抑制药。"},{"q":"下列药物中属于M受体阻断药的是","o":["东莨菪碱","筒箭毒碱","琥珀胆碱","毒扁豆碱","乙酰胆碱"],"a":0,"e":"东莨菪碱阻断M受体；筒箭毒碱、琥珀胆碱作用于N受体，毒扁豆碱抑制胆碱酯酶，乙酰胆碱为内源性递质。"},{"q":"通过抑制细菌的细胞壁的合成发挥杀菌作用，但杀菌速度较慢的抗菌药物是","o":["青霉素","阿奇霉素","阿莫西林","多黏菌素B","万古霉素"],"a":4,"e":"万古霉素与细胞壁前体肽聚糖结合，阻断转糖基和肽桥形成，杀菌速度较青霉素慢，对耐甲氧西林金葡菌有效。"},{"q":"以下哪种药物对阿米巴包囊最有效","o":["甲硝唑","氯喹","二氯尼特","巴龙霉素","吡喹酮"],"a":2,"e":"二氯尼特在肠道内直接杀灭阿米巴包囊，为包囊携带者的首选；甲硝唑对滋养体作用强而对包囊无效。"},{"q":"氨基糖苷类抗生素的消除途径是","o":["原型经肾小球滤过排出","原型经肾小管分泌排出","被单胺氧化酶代谢","被肝药酶P450代谢","与葡糖醛酸结合后排出"],"a":0,"e":"氨基糖苷类口服难吸收，体内几乎不被代谢，主要以原型经肾小球滤过排出，尿中浓度高。"},{"q":"下列哪项不是四环素类产生耐药性的机制","o":["产生灭活酶","产生核糖体保护蛋白","缺乏自溶酶","减少药物进入菌体","促进药物主动外排"],"a":2,"e":"四环素耐药机制包括产生灭活酶、核糖体保护蛋白、膜通透性降低及主动外排；缺乏自溶酶是β-内酰胺类的耐药机制。"},{"q":"部分激动剂的特点是","o":["与受体无亲和力，但有部分内在活性","与受体亲和力弱，内在活性强","与受体亲和力强，但内在活性弱","与受体亲和力强，内在活性亦强","与受体亲和力强，但无内在活性"],"a":2,"e":"部分激动剂与受体亲和力强而内在活性弱，单独应用产生较弱效应，并可竞争性拮抗完全激动剂。"},{"q":"用硫喷妥钠或氧化亚氮作诱导麻醉是因为","o":["可增加镇痛作用","肌肉松弛效果好","能迅速进入外科麻醉期","减少支气管分泌物的产生","减少麻醉药用量"],"a":2,"e":"硫喷妥钠脂溶性高，静脉注射后迅速透过血脑屏障，数分钟内即进入外科麻醉期，故用作诱导麻醉。"},{"q":"易燃易爆，有特殊臭味的麻醉药是","o":["乙醚","氟烷","恩氟烷","异氟烷","氧化亚氮"],"a":0,"e":"乙醚为挥发性液体，蒸气易燃易爆并具特殊臭味，遇明火可燃烧；氟烷类及氧化亚氮均不燃。"},{"q":"以下治疗方式不属于肿瘤免疫治疗药物的是","o":["肿瘤疫苗","细胞毒T淋巴细胞抗原-4（CTLA-4）单克隆抗体","程序性死亡受体1（PD-1）单克隆抗体","表皮生长因子受体（EGFR）单克隆抗体","与DNA交联的烷化剂"],"a":3,"e":"EGFR单抗为分子靶向药，阻断表皮生长因子受体信号而抑制肿瘤增殖；肿瘤疫苗、CTLA-4及PD-1单抗才属免疫治疗。"},{"q":"轻度抑制心肌细胞Na＋通道，主要作用于心室肌的抗心律失常药是","o":["奎尼丁","利多卡因","普鲁卡因胺","胺碘酮","维拉帕米"],"a":1,"e":"利多卡因轻度阻滞钠通道，促进K+外流、缩短动作电位时程，主要作用于希-浦系统和心室肌，为室性心律失常首选。"},{"q":"西咪替丁治疗消化性溃疡的机制是","o":["中和胃酸","吸附胃酸","阻断H1受体，抑制胃酸分泌","阻断H2受体，抑制胃酸分泌","阻断M1受体，抑制胃酸分泌"],"a":3,"e":"西咪替丁选择性阻断胃壁细胞基底膜H2受体，减少胃酸分泌而促进溃疡愈合；阻断H1受体者为经典抗组胺药。"},{"q":"对尿量已减少的中毒性休克，最好选用","o":["阿托品","多巴胺","麻黄碱","异丙肾上腺素","酚妥拉明"],"a":1,"e":"多巴胺激动多巴胺受体扩张肾血管，并激动β1受体增强心肌收缩、激动α受体升压，适用于尿量已减少的中毒性休克。"},{"q":"苯妥英钠对下列哪种癫痫无效","o":["癫痫持续状态","大发作","单纯局限性发作","小发作","精神运动性发作"],"a":3,"e":"苯妥英钠阻滞钠通道，对失神小发作无效甚至可诱发其发作，小发作应选用乙琥胺或丙戊酸钠。"},{"q":"中枢神经受到抑制的表现为","o":["欣快","失眠","幻觉","抑郁","躁狂"],"a":3,"e":"中枢神经受抑制时表现为淡漠、抑郁、嗜睡乃至昏迷；欣快、失眠、幻觉和躁狂属中枢兴奋的表现。"},{"q":"糖皮质激素可增强儿茶酚胺的血管收缩作用，称为","o":["允许作用","协同作用","拮抗作用","依赖作用","叠加作用"],"a":0,"e":"糖皮质激素本身并不直接收缩血管，但可增强血管平滑肌对儿茶酚胺的敏感性，此种现象称为允许作用。"},{"q":"治疗癫痫小发作的首选药物是","o":["乙琥胺","丙戊酸钠","苯妥英钠","扑米酮","卡马西平"],"a":0,"e":"乙琥胺抑制丘脑神经元T型钙通道，减少3Hz棘慢波发放，为癫痫小发作首选，对强直-阵挛发作无效。"},{"q":"糖皮质激素用于严重的感染的目的","o":["提高机体防御能力","抗细菌感染","提高抗菌药物的活性","防止病灶扩散","使病人度过危险期"],"a":4,"e":"严重感染时糖皮质激素抗炎、抗毒、抗休克，缓解中毒症状，帮助患者度过危险期，但须与足量有效抗菌药合用。"},{"q":"洛伐他汀的降脂机制为","o":["抑制磷酸二酯酶","抑制HMG-CoA还原酶","抑制血管紧张素转换酶","激活乙酰胆碱酯酶","激活一氧化氮合酶"],"a":1,"e":"洛伐他汀竞争性抑制HMG-CoA还原酶，减少肝内胆固醇合成，并上调肝细胞LDL受体，降低血浆胆固醇。"},{"q":"最易引起心律失常的药物是","o":["去甲肾上腺素","间羟胺","肾上腺素","麻黄碱","多巴胺"],"a":2,"e":"肾上腺素激动β1受体提高心肌自律性、加快传导，易诱发期前收缩甚至心室颤动，为最易致心律失常的拟肾上腺素药。"},{"q":"决定药物每天用药次数的最主要因素是","o":["吸收快慢","作用强弱","体内分布速度","体内转化速度","体内消除速度"],"a":4,"e":"给药间隔主要取决于药物消除速度，t1/2短者需多次给药，t1/2长者间隔延长，以维持有效血药浓度。"},{"q":"治疗前列腺癌宜选用的药物是","o":["苯丙酸诺龙","炔雌醇","丙酸睾丸素","氯米芬","双醋炔诺醇"],"a":1,"e":"前列腺癌为雄激素依赖性肿瘤，炔雌醇经负反馈抑制促性腺激素释放、减少睾酮生成，并可对抗雄激素作用。"},{"q":"格列美脲的主要作用机制是","o":["促进葡萄糖降解","拮抗胰高血糖素的作用","刺激胰岛β细胞释放胰岛素","促进葡萄糖的合成","刺激胰岛素"],"a":2,"e":"格列美脲与β细胞膜ATP敏感钾通道的磺酰脲受体结合，促Ca2+内流和胰岛素释放，兼具胰岛素增敏作用。"},{"q":"氯丙嗪中毒引起血压下降时，禁用哪种措施","o":["注射多巴胺","补充血容量","注射去甲肾上腺素","中枢兴奋药","吸氧"],"a":0,"e":"多巴胺升压依赖α受体，氯丙嗪已阻断α受体，注射后血管扩张使血压更低，故属禁用；应补液并用去甲肾上腺素。"},{"q":"因电击导致的心脏骤停，在采用心肺复苏措施的同时还应给予的急救药物是","o":["去甲肾上腺素","肾上腺素","多巴胺","多巴酚丁胺","糖皮质激素"],"a":1,"e":"肾上腺素激动α受体提高冠脉灌注压、激动β1受体增强心肌收缩，使室颤波变粗，为心脏骤停复苏首选药。"},{"q":"伴有胃溃疡的风湿性关节炎患者最好选用","o":["吲哚美辛","布洛芬","阿司匹林","保泰松","对乙酰氨基酚"],"a":1,"e":"布洛芬为丙酸类非甾体抗炎药，抗炎镇痛作用与胃肠刺激性相对平衡，胃肠道刺激较阿司匹林、吲哚美辛轻。"},{"q":"能引起金鸡纳反应的药物是","o":["普萘洛尔","普鲁卡因胺","胺碘酮","奎尼丁","普罗帕酮"],"a":3,"e":"奎尼丁可致金鸡纳反应，表现为恶心、呕吐、耳鸣、听力减退、头痛和视力模糊，其发生与用药剂量相关。"},{"q":"下列药物属于α、β受体阻断药的是","o":["普萘洛尔","吲哚洛尔","酚苄明","拉贝洛尔","阿替洛尔"],"a":3,"e":"拉贝洛尔兼有α1和β受体阻断作用，降压时较少引起反射性心动过速；普萘洛尔、阿替洛尔仅阻断β受体。"},{"q":"钙通道阻滞药的药理作用不包括","o":["血管平滑肌松弛，血压下降","冠脉血管扩张","抗动脉粥样硬化","加快房室传导","明显增加肾血流"],"a":3,"e":"钙通道阻滞药抑制Ca2+内流，减慢房室传导，可用于室上性心动过速；加快房室传导与其作用相反。"},{"q":"下列地西泮的药理学作用中，小剂量即可明显改善症状的是","o":["镇静催眠","抗惊厥、抗癫痫","中枢性肌肉松弛","抗焦虑","暂时性记忆缺失"],"a":3,"e":"地西泮小剂量即可减轻焦虑与紧张不安，随剂量增加才出现镇静催眠、抗惊厥和中枢性肌松作用。"},{"q":"强心苷心脏毒性的发生机制是","o":["兴奋心肌细胞膜上Na＋-K＋-ATP酶","使心肌细胞内K＋增多","促进心肌抑制因子的释放","抑制心肌细胞膜上Na＋-K＋-ATP酶","激活磷酸二酯酶"],"a":3,"e":"强心苷抑制心肌细胞膜Na+-K+-ATP酶，使细胞内Na+增多、Na+-Ca2+交换增加、Ca2+超载，中毒量则引起迟后除极和心律失常。"},{"q":"长期应用糖皮质激素后停药不会引起","o":["原病复发或恶化","肾上腺皮质功能不全","肾上腺皮质功能亢进","糖皮质激素抵抗","肾上腺危象"],"a":2,"e":"长期大剂量应用糖皮质激素反馈抑制下丘脑-垂体-肾上腺轴，停药后出现皮质萎缩、功能不全甚至危象，而非功能亢进。"},{"q":"小剂量的多巴胺即能增加肾血流量的主要原因是","o":["兴奋β1受体","兴奋β2受体","兴奋多巴胺受体","阻断α受体","直接松弛肾血管平滑肌"],"a":2,"e":"小剂量多巴胺选择性激动肾血管多巴胺受体，扩张肾动脉、增加肾血流量和肾小球滤过率而利尿。"},{"q":"呋塞米的利尿效能高的原因是","o":["增强肾脏的稀释功能","抑制肾脏的浓缩功能","抑制肾脏的稀释和浓缩功能","抗醛固酮的作用","阻滞Na＋重吸收"],"a":2,"e":"呋塞米抑制髓袢升支粗段Na+-K+-2Cl-共转运子，使肾脏稀释与浓缩功能均受损，排出大量近等渗尿，故效能最高。"},{"q":"下列药物中，中枢镇静作用最强的是","o":["阿司咪唑","氯苯那敏","布克力嗪","苯海拉明","美克洛嗪"],"a":3,"e":"苯海拉明易透过血脑屏障阻断中枢H1受体，镇静催眠作用最强，常致嗜睡；阿司咪唑则几乎无中枢作用。"},{"q":"可用于解救低分子量肝素应用过量所致出血的药物是","o":["维生素K","鱼精蛋白","垂体后叶素","氨甲苯酸","氯化钙"],"a":1,"e":"鱼精蛋白带强正电荷，与低分子肝素结合成无活性复合物，为其过量出血的特效拮抗药；维生素K仅对抗香豆素类。"},{"q":"属于n-3型多烯脂肪酸的药物是","o":["二十碳五烯酸","亚油酸","γ-亚麻酸","硫酸类肝素","烟酸"],"a":0,"e":"二十碳五烯酸属n-3型多烯脂肪酸，可降低甘油三酯、抑制血小板聚集；亚油酸和γ-亚麻酸属n-6型。"},{"q":"有关叶酸的说法，错误的是","o":["主要在十二指肠和空肠上段吸收","促进氨基酸的互变","妊娠妇女需要量增加","吸收需要内因子的协助","参与嘌呤的从头合成"],"a":3,"e":"叶酸在十二指肠和空肠上段经主动转运吸收，不需内因子协助；内因子是维生素B12吸收所必需。"},{"q":"巨幼红细胞性贫血患者合并神经症状时需应用","o":["亚叶酸钙","维生素B12","红细胞生成素","硫酸亚铁","叶酸"],"a":1,"e":"维生素B12参与甲基丙二酰辅酶A变位反应、维持髓鞘完整，巨幼细胞性贫血伴神经症状者必须补充，单用叶酸会加重神经损害。"},{"q":"喹诺酮类药物对革兰阴性菌的抗菌作用机制为","o":["抑制β-内酰胺酶","抑制DNA回旋酶","抑制二氢蝶酸合酶","抑制细菌细胞壁的合成","增加细菌胞浆膜的通透性"],"a":1,"e":"喹诺酮类抑制细菌DNA回旋酶（拓扑异构酶Ⅱ），阻碍DNA复制，对革兰阴性菌作用强；抑制二氢蝶酸合酶者为磺胺类。"},{"q":"易通过血脑屏障的抗真菌药物是","o":["咪康唑","克霉唑","氟康唑","酮康唑","阿司咪唑"],"a":2,"e":"氟康唑脂溶性高、血浆蛋白结合率低，能透过血脑屏障，脑脊液浓度可达血药浓度的60%以上，是中枢神经系统真菌感染的首选药。"},{"q":"可用于处理去甲肾上腺素静脉滴注外漏引起局部缺血的药物是","o":["酚妥拉明","阿托品","去氧肾上腺素","多巴胺","普萘洛尔"],"a":0,"e":"酚妥拉明阻断血管α受体，使痉挛血管舒张、局部血流恢复；去甲肾上腺素外漏致局部缺血时，应尽早于该部位浸润注射酚妥拉明。"},{"q":"为了保证药物的疗效，多次给药应该","o":["后续给药剂量加倍","每天3次或3次以上给药","根据药物半衰期确定给药间隔","每2小时用药1次","不间断用药"],"a":2,"e":"一级动力学消除的药物半衰期恒定，按半衰期确定给药间隔可使稳态血药浓度波动在安全有效范围内，一般经4～5个半衰期达稳态。"},{"q":"下列农药中毒，碘解磷定抢救无效的是","o":["对硫磷","内吸磷","马拉硫磷","乐果","敌百虫"],"a":3,"e":"乐果在体内氧化后毒性增强，其磷酰化胆碱酯酶老化快，碘解磷定复能作用差而疗效不佳；对硫磷、内吸磷等中毒则有效。"},{"q":"立克次体感染，治疗首选","o":["四环素类","氯霉素类","青霉素类","头孢菌素类","万古霉素类"],"a":0,"e":"四环素类对立克次体、衣原体、支原体及螺旋体均有良好作用，立克次体感染以四环素类为首选。"},{"q":"甲氧苄啶长期大量服用会引起人体叶酸缺乏症，原因是人体的哪种酶被抑制","o":["二氢叶酸还原酶","四氢叶酸还原酶","二氢蝶酸合酶","一碳单位转移酶","葡萄糖-6-磷酸脱氢酶"],"a":0,"e":"甲氧苄啶选择性抑制二氢叶酸还原酶，使二氢叶酸不能还原为四氢叶酸；人体该酶同样受抑，长期大量应用可致叶酸缺乏。"},{"q":"应用硫脲类药物前一般避免服用碘剂的原因是","o":["可明显延缓硫脲类药物的疗效","可产生交叉过敏反应","易诱发甲状腺功能低下和甲状腺肿","可与硫脲类药物竞争靶细胞","可加速肝脏对硫脲类药物的代谢灭活"],"a":0,"e":"碘剂可抑制甲状腺球蛋白水解、减少激素释放，并使腺体缩小变硬、血供减少，先用碘剂会延缓硫脲类疗效，故须避免。"},{"q":"由于心脏手术或洋地黄中毒引起的室性期前收缩，宜选用的治疗药物是","o":["利多卡因","奎尼丁","普鲁卡因胺","普萘洛尔","氟卡尼"],"a":0,"e":"利多卡因作用于浦肯野纤维，促进钾外流、降低自律性，对缺血或强心苷中毒所致室性期前收缩疗效好，且不抑制心肌收缩力。"},{"q":"金刚烷胺能特异性地抑制下列哪项病毒感染","o":["A型流感病毒","乙型流感病毒","麻疹病毒","腮腺炎病毒","单纯疱疹病毒"],"a":0,"e":"金刚烷胺阻止A型流感病毒穿入宿主细胞并抑制其脱壳，对乙型流感病毒无效，仅用于A型流感的防治。"},{"q":"卡托普利的降压作用机制是","o":["抑制血管紧张素转化酶","拮抗AT1受体","拮抗α1受体","兴奋α2受体","阻滞钙通道"],"a":0,"e":"卡托普利抑制血管紧张素转化酶，减少血管紧张素Ⅱ生成并减少缓激肽降解，使血管舒张、血压下降。"},{"q":"可引起幼儿牙釉质发育不良并黄染的药物是","o":["红霉素","四环素","青霉素","林可霉素","多黏霉素E"],"a":1,"e":"四环素与钙结合沉积于骨和牙组织，影响婴幼儿骨骼生长，并致牙釉质发育不全、牙齿黄染，8岁以下儿童禁用。"},{"q":"下列药物对血压产生双相反应的是","o":["去甲肾上腺素","肾上腺素","异丙肾上腺素","多巴酚丁胺","间羟胺"],"a":1,"e":"肾上腺素激动α和β受体，小剂量时β2受体舒血管作用占优，血压短暂下降，较大剂量以α受体缩血管为主使血压升高，呈双相反应。"},{"q":"下列属于七氟烷的特点的是","o":["刺激性大","血/气分配系数大","脑/血分配系数大","易燃易爆","对心肺功能影响小"],"a":4,"e":"七氟烷血/气分配系数低，诱导苏醒快，无刺激性、不燃不爆，对心肌收缩力和心排出量抑制轻，对心肺功能影响小。"},{"q":"用于治疗心力衰竭和高血压病的药物是","o":["洋地黄毒苷","氨力农","米力农","毛花苷C","卡托普利"],"a":4,"e":"卡托普利抑制血管紧张素转化酶，降低心脏前后负荷并抑制心肌及血管重构，是治疗慢性心力衰竭和高血压的常用药。"},{"q":"乙胺丁醇与利福平合用抗结核可以","o":["减少利福平的不良反应","延长利福平的作用时间","延缓利福平的排泄","增加利福平的血药浓度","延缓结核菌产生耐药性"],"a":4,"e":"乙胺丁醇为抑菌药，单用易产生耐药，与利福平等联合应用可延缓和减少结核分枝杆菌耐药性的产生。"},{"q":"下列药物哪一个是肝药酶抑制药","o":["卡马西平","苯巴比妥","西咪替丁","苯妥英钠","利福平"],"a":2,"e":"西咪替丁抑制肝药酶CYP450，使华法林、苯妥英钠代谢减慢、血药浓度升高；卡马西平、苯巴比妥、苯妥英钠、利福平均为肝药酶诱导药。"},{"q":"下列β受体阻断药中半衰期最长的是","o":["普萘洛尔","纳多洛尔","卡维地洛","阿替洛尔","噻吗洛尔"],"a":1,"e":"纳多洛尔半衰期长达14～24小时，为β受体阻断药中最长者，可每日给药一次；普萘洛尔、阿替洛尔等半衰期均较短。"},{"q":"右美托咪定的作用是","o":["激动中枢α1受体","激动中枢α2受体","阻断中枢α1受体","阻断中枢α2受体","激动外周α受体"],"a":1,"e":"右美托咪定为高选择性α2受体激动药，激动中枢蓝斑核α2受体而产生镇静、催眠、抗焦虑和镇痛作用，呼吸抑制轻。"},{"q":"可抑制婴幼儿骨骼发育的药物是","o":["青霉素","庆大霉素","四环素","头孢曲松","阿奇霉素"],"a":2,"e":"四环素沉积于骨骼钙化区，与钙结合妨碍婴幼儿骨骼发育，并致牙齿黄染，故8岁以下儿童禁用。"},{"q":"抑制血管紧张素转化酶的抗高血压药是","o":["卡托普利","可乐定","普萘洛尔","拉贝洛尔","肼屈嗪"],"a":0,"e":"卡托普利抑制血管紧张素转化酶，减少血管紧张素Ⅱ生成，扩张外周血管而降压，属ACE抑制药。"},{"q":"治疗心肌梗死所致室性期前收缩的首选药物是","o":["普萘洛尔","胺碘酮","维拉帕米","利多卡因","苯妥英钠"],"a":3,"e":"利多卡因对缺血心肌的浦肯野纤维作用明显，是心肌梗死并发室性期前收缩及室性心动过速的首选药。"},{"q":"关于雌激素替代治疗的描述以下哪一项是不正确的","o":["可以有效抑制绝经期后骨吸收","调整每个重建周期的骨吸收和形成的平衡","是治疗骨质疏松的一线方案","绝经早期用药获益大","治疗方案个体化，使用最低有效剂量"],"a":2,"e":"雌激素替代治疗可抑制绝经后骨吸收、维持骨量，绝经早期用药获益最大，须个体化并用最低有效剂量，但因其增加乳腺癌、血栓风险，不作骨质疏松一线方案。"},{"q":"药物代谢动力学研究","o":["药物进入血液循环与血浆蛋白结合及解离的规律","药物吸收后在机体细胞分布变化的规律","药物经肝脏代谢为无活性产物的过程","药物从给药部位进入血液循环的过程","药物在机体的影响下发生的变化及其规律"],"a":4,"e":"药物代谢动力学研究药物在体内经吸收、分布、代谢、排泄所发生的浓度变化规律，即机体对药物的处置。"},{"q":"克林霉素（氯林可霉素）可引起下列哪种不良反应","o":["胆汁阻塞性肝炎","听力下降","伪膜性肠炎","肝功能严重损害","肾功能严重损害"],"a":2,"e":"克林霉素抑制细菌蛋白质合成，可致艰难梭菌大量繁殖并产生毒素，引起伪膜性肠炎，严重时需用甲硝唑或万古霉素治疗。"},{"q":"阿托品可用于治疗","o":["心房扑动","心房纤颤","窦性心动过缓","室上性心动过速","室性心动过速"],"a":2,"e":"阿托品阻断窦房结M受体，解除迷走神经对心脏的抑制，使心率加快，用于治疗窦性心动过缓及房室传导阻滞。"},{"q":"阿托品中毒治疗可选用的药物是","o":["乙酰胆碱","毒扁豆碱","肾上腺素","酚妥拉明","哌仑西平"],"a":1,"e":"毒扁豆碱为易透过血脑屏障的胆碱酯酶抑制药，可对抗阿托品的外周和中枢中毒症状，为阿托品中毒的解救药。"},{"q":"按一级动力学消除的药物，其血浆半衰期等于","o":["0.693/Ke","Ke/0.693","2.303/Ke","Ke/2.303","0.301/Ke"],"a":0,"e":"一级动力学消除的药物血药浓度按恒比衰减，半衰期t1/2为0.693除以Ke，与血药浓度高低无关。"},{"q":"下列药物中抑制胃酸作用最强的是","o":["法莫替丁","硫糖铝","兰索拉唑","铝碳酸镁","米索前列醇"],"a":2,"e":"兰索拉唑为质子泵抑制药，不可逆抑制胃壁细胞H+-K+-ATP酶，抑制胃酸分泌的作用最强、最持久。"},{"q":"药物在肝脏内代谢转化后都会","o":["毒性减小或消失","经胆汁排泄","极性增高","脂/水分布系数增大","分子量减小"],"a":2,"e":"药物在肝脏经氧化、还原、水解及结合反应后分子极性增高、脂溶性降低，利于随尿和胆汁排出。"},{"q":"泰能为临床上治疗G+和G-需氧菌和厌氧菌所致各种严重感染的药物，是西司他汀与下列哪个药物组成的复方制剂","o":["硫霉素","亚胺培南","头孢西丁","拉氧头孢","氨曲南"],"a":1,"e":"泰能即亚胺培南与西司他丁的复方制剂，西司他丁抑制肾脱氢肽酶，保护亚胺培南不被破坏并减轻其肾毒性。"},{"q":"维司力农治疗心衰的作用机制是","o":["兴奋心脏β1受体","抑制钠钾ATP酶","通过抑制PDE-Ⅲ提高细胞内cAMP含量","促进血管内皮细胞合成NO","阻滞钙通道"],"a":2,"e":"维司力农为磷酸二酯酶Ⅲ抑制药，抑制cAMP降解、提高细胞内cAMP浓度，增强心肌收缩力并扩张血管。"},{"q":"在远曲小管通过与醛固酮竞争性拮抗而产生利尿作用的药物是","o":["呋塞米","布美他尼","螺内酯","阿米洛利","氨苯蝶啶"],"a":2,"e":"螺内酯化学结构与醛固酮相似，在远曲小管和集合管竞争性拮抗醛固酮受体，抑制钠重吸收而保钾利尿。"},{"q":"硝酸甘油扩血管是通过哪项发挥作用的","o":["增加NO的生成","抑制交感神经","兴奋迷走神经","抑制血管紧张素生成","利尿作用"],"a":0,"e":"硝酸甘油在体内释放一氧化氮，激活鸟苷酸环化酶使cGMP增多，松弛血管平滑肌，扩张静脉和动脉。"},{"q":"下列不宜用于支气管哮喘患者的静脉麻醉药是","o":["依托咪酯","氯胺酮","丙泊酚","硫喷妥钠","咪达唑仑"],"a":3,"e":"硫喷妥钠使迷走神经张力相对增高并可释放组胺，易诱发喉痉挛和支气管痉挛，禁用于支气管哮喘患者。"},{"q":"青霉素治疗效果最好的是","o":["铜绿假单胞菌感染","肺炎杆菌感染","破伤风杆菌感染","结核杆菌感染","变形杆菌感染"],"a":2,"e":"青霉素对破伤风梭菌高度敏感，是治疗破伤风的首选；铜绿假单胞菌、肺炎杆菌、结核杆菌、变形杆菌多对其耐药。"},{"q":"下列用于治疗阿尔茨海默病的药物中，不属于胆碱酯酶抑制剂的是","o":["多奈哌齐","美金刚","石杉碱甲","加兰他敏","利斯的明"],"a":1,"e":"美金刚为N-甲基-D-天冬氨酸受体非竞争性拮抗药，调节谷氨酸能神经传递；多奈哌齐、石杉碱甲、加兰他敏、利斯的明均为胆碱酯酶抑制药。"},{"q":"麦角新碱治疗产后出血的作用机制是","o":["收缩子宫平滑肌","收缩血管","促进血管修复","促进凝血过程","促进血小板聚集"],"a":0,"e":"麦角新碱选择性兴奋子宫平滑肌，剂量稍大即引起强直性收缩，压迫子宫肌内血管而止血，用于产后出血及子宫复旧。"},{"q":"别嘌醇属于","o":["镇痛药","抗癫痫药","解热镇痛抗炎药","抗痛风药","中枢兴奋药"],"a":3,"e":"别嘌醇抑制黄嘌呤氧化酶，阻断次黄嘌呤向黄嘌呤及尿酸转化，降低血尿酸水平，属抗痛风药。"},{"q":"下列哪类抗菌药物属于静止期杀菌药","o":["青霉素类","磺胺类","大环内酯类","氨基苷类","四环素类"],"a":3,"e":"氨基苷类为静止期杀菌药，抑制细菌蛋白质合成并破坏胞质膜使细菌死亡；青霉素类则属繁殖期杀菌药。"},{"q":"组胺H2受体阻滞药在临床适用于治疗的疾病是","o":["荨麻疹","呕吐","晕动病","消化道溃疡","支气管哮喘"],"a":3,"e":"组胺H2受体阻断药抑制胃壁细胞基础胃酸和夜间胃酸分泌，促进溃疡愈合，用于胃及十二指肠溃疡。"},{"q":"糖皮质激素抗毒作用机理是","o":["对抗细菌外毒素","中和细菌内毒素","提高机体对细菌内毒素的耐受力","加速细菌内毒素的排泄","加速机体对细菌外毒素的代谢"],"a":2,"e":"糖皮质激素提高机体对细菌内毒素的耐受力，减轻内毒素所致发热、休克等反应，但不能中和内毒素，对外毒素亦无效。"},{"q":"抗消化性溃疡米索前列醇禁用于妊娠妇女是由于","o":["子宫收缩","女性胎儿男性化","致畸胎作用","盆腔充血","胃肠道反应"],"a":0,"e":"米索前列醇为前列腺素E1衍生物，可兴奋子宫平滑肌引起收缩，妊娠妇女禁用，以免引起流产。"},{"q":"具有扩瞳作用的药物是","o":["溴甲东莨菪碱","普鲁本辛","哌仑西平","后马托品","双环维林"],"a":3,"e":"后马托品为合成抗胆碱药，阻断瞳孔括约肌M受体使瞳孔扩大，作用较阿托品短，适用于眼底检查。"},{"q":"妥拉唑林的药物分类属于","o":["选择性α1受体阻断药","非选择性α受体阻断药","选择性β1受体阻断药","非选择性β受体阻断药","选择性α2受体阻断药"],"a":1,"e":"妥拉唑林对α1和α2受体均有阻断作用，属非选择性α受体阻断药，可舒张血管、加快心率。"},{"q":"下列无抗幽门螺杆菌作用的药物是","o":["阿莫西林","奥美拉唑","四环素","普鲁苯辛","枸橼酸铋钾"],"a":3,"e":"普鲁苯辛为M胆碱受体阻断药，仅缓解溃疡症状，无抑制或杀灭幽门螺杆菌的作用；阿莫西林、四环素、铋剂和奥美拉唑均参与根除治疗。"},{"q":"吗啡的中枢药理作用有","o":["镇痛、镇静、致咳","镇痛、镇咳、兴奋呼吸","镇痛、欣快、散瞳","镇痛、镇静、抑制呼吸、镇咳","镇痛、镇静、兴奋呼吸"],"a":3,"e":"吗啡激动中枢阿片受体，产生镇痛、镇静和镇咳作用，并抑制延髓呼吸中枢，使呼吸频率减慢、潮气量降低。"},{"q":"不能用于治疗甲状腺危象的药物是","o":["大剂量碘剂","丙硫氧嘧啶","普萘洛尔","甲苯磺丁脲","卡比马唑"],"a":3,"e":"甲苯磺丁脲为磺酰脲类降糖药，不能抑制甲状腺激素的合成与释放，对甲状腺危象无效；碘剂、丙硫氧嘧啶、普萘洛尔、卡比马唑均可应用。"},{"q":"下列药物属于α-葡萄糖苷酶抑制药是","o":["氯磺丙脲","甲苯磺丁脲","格列齐特","吡格列酮","阿卡波糖"],"a":4,"e":"阿卡波糖在小肠上皮刷状缘抑制α-葡萄糖苷酶，延缓碳水化合物水解和吸收，降低餐后血糖。"},{"q":"有关维生素K的叙述，错误的是","o":["对于应用链激酶所致出血有特效","较大剂量维生素K3可出现新生儿溶血","参与凝血因子的合成","天然维生素K为脂溶性","维生素K1注射过快可出现呼吸困难"],"a":0,"e":"维生素K参与凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的合成，对香豆素类过量出血有效；链激酶所致出血源于纤溶亢进，须用氨甲苯酸对抗。"},{"q":"按一级动力学消除的药物，其血浆半衰期的计算公式是","o":["Ke/1、44","1.44/Ke","0.693/Ke","Ke/0.693","2D/Ke"],"a":2,"e":"一级动力学消除时单位时间消除恒比，半衰期t1/2为0.693除以Ke，与剂量和血药浓度无关。"},{"q":"关于吗啡作用的叙述，哪项是错误的","o":["镇痛","抑制呼吸","瞳孔缩小","治疗支气管哮喘","引起体位性低血压"],"a":3,"e":"吗啡抑制呼吸、释放组胺并收缩支气管，可加重哮喘发作，支气管哮喘患者禁用，不能用于治疗哮喘。"},{"q":"吗啡连续应用易成瘾，一般仅应用于","o":["慢性钝痛","慢性失眠","慢性充血性心力衰竭","精神焦虑症","急性剧痛"],"a":4,"e":"吗啡易产生耐受性和成瘾性，仅用于急性剧痛如严重创伤、手术后及晚期癌痛，慢性钝痛不宜使用。"},{"q":"磺酰脲类降糖作用主要机制是","o":["抑制胰高血糖素分泌","提高靶细胞对胰岛素的敏感性","增加靶细胞膜上胰岛素受体数目","阻滞ATP敏感钾通道，触发胰岛素释放","降低食物吸收和糖原异生"],"a":3,"e":"磺酰脲类与胰岛β细胞膜上ATP敏感钾通道的磺酰脲受体结合，使通道关闭、细胞去极化，钙内流触发胰岛素释放。"},{"q":"氨基糖苷类抗生素对下列哪类细菌作用差","o":["铜绿假单胞菌","厌氧菌属","结核分枝杆菌","克雷伯菌属","肠杆菌"],"a":1,"e":"氨基糖苷类需经氧依赖性主动转运进入菌体，厌氧菌缺乏该转运系统，故对厌氧菌作用差。"},{"q":"去甲肾上腺素扩张冠脉的原因是","o":["激动α2受体","阻断α1受体","激动β2受体","兴奋心脏，使心肌代谢产物增加","激动M受体"],"a":3,"e":"去甲肾上腺素强烈激动α受体使血管收缩，同时激动β1受体增强心肌代谢，代谢产物腺苷等增多使冠脉继发性扩张。"},{"q":"受体拮抗剂的特点是","o":["对受体有亲和力，有内在活性","对受体无亲和力，有内在活性","对受体无亲和力，无内在活性","对受体有亲和力，无内在活性","抑制体内自主神经末梢释放递质"],"a":3,"e":"受体拮抗剂对受体有亲和力而无内在活性，本身不产生效应，但能阻断激动剂与受体结合。"},{"q":"某碱性药物的pKa为9.8，如果增高尿液的pH，则此药在尿中","o":["解离度增高，重吸收减少，排泄加快","解离度增高，重吸收增多，排泄减慢","解离度降低，重吸收减少，排泄加快","解离度降低，重吸收增多，排泄减慢","排泄速度并不改变"],"a":3,"e":"碱性药物在碱性尿中解离度降低、脂溶性增高，肾小管重吸收增多而排泄减慢，故碱化尿液可解救其过量中毒。"},{"q":"哪项不是氯丙嗪的不良反应","o":["体位性低血压","嗜睡、无力、鼻塞、心动过速","帕金森综合征","迟发性运动障碍","牙龈增生"],"a":4,"e":"氯丙嗪可致体位性低血压及帕金森综合征、迟发性运动障碍等锥体外系反应；牙龈增生为苯妥英钠的不良反应。"},{"q":"下列不属于自体活性物质的是","o":["前列腺素","内皮素","血管紧张素","肾上腺素","血清素"],"a":3,"e":"自体活性物质由机体自身生成并参与局部或全身调节，如前列腺素、内皮素、血管紧张素和5-羟色胺；肾上腺素属神经递质。"},{"q":"X、Y两药的S型量-效曲线位于同一坐标上，其中，Y药在X药的右侧且高出后者20%，下列描述正确的是","o":["X药的效价强度和效能均较大","X药的效价强度和效能均较小","X药的效价强度较小而效能较大","X药的效价强度较大而效能较小","两药的效价强度和效能均相等"],"a":3,"e":"量-效曲线右移表示效价强度降低，Y药位于X药右侧，故X药效价强度大；Y药最大效应高出20%，故X药效能较小。"},{"q":"小剂量多巴胺舒张血管主要是通过激动","o":["α1受体","β1受体","D1受体","β2受体","α2受体"],"a":2,"e":"小剂量多巴胺激动肾及肠系膜血管的D1受体，使血管舒张、肾血流量增加；大剂量则激动α受体使血管收缩。"},{"q":"肝素过量时特效的解毒剂是","o":["鱼精蛋白","维生素K","氨甲苯酸","硫酸亚铁","阿司匹林"],"a":0,"e":"鱼精蛋白带强正电荷，与带负电荷的肝素结合成稳定复合物而使其失活，为肝素过量出血的特效解毒药。"},{"q":"氯丙嗪翻转肾上腺素升压效应是因为它","o":["阻断DA受体","阻断M受体","阻断α受体","阻断β受体","阻断N受体"],"a":2,"e":"氯丙嗪阻断外周血管α受体，取消肾上腺素激动α受体所致的升压作用，仅保留β2受体舒血管效应，使升压翻转为降压。"},{"q":"可引起出血性膀胱炎的抗肿瘤药是","o":["阿糖胞苷","环磷酰胺","长春碱","阿奇霉素","长春新碱"],"a":1,"e":"环磷酰胺经肝代谢生成丙烯醛，随尿排泄时刺激膀胱黏膜引起出血性膀胱炎，用药须充分水化。"},{"q":"TMP的抗菌作用机制是抑制","o":["二氢叶酸还原酶","过氧化物酶","二氢蝶酸合酶","DNA回旋酶","β-内酰胺酶"],"a":0,"e":"甲氧苄啶抑制二氢叶酸还原酶，阻止二氢叶酸还原为四氢叶酸，与磺胺类合用可双重阻断叶酸代谢。"},{"q":"丙磺舒与青霉素合用，增强后者疗效的原因是","o":["与青霉素竞争血浆结合蛋白","与青霉素在杀菌作用上有协同效应","抑制青霉素在肝内的代谢","与青霉素竞争肾小管分泌","延缓青霉素耐药性的产生"],"a":3,"e":"丙磺舒与青霉素均为有机酸，经同一肾小管分泌载体转运，二者竞争使青霉素排泄减少、血药浓度升高而增效。"},{"q":"麦角胺治疗偏头痛的作用机制是","o":["阻断血管平滑肌α受体","具有镇痛作用","扩张脑血管，改善脑组织供氧","抑制前列腺素合成","收缩脑血管"],"a":4,"e":"麦角胺收缩脑血管，使扩张的颅外动脉恢复张力，从而缓解偏头痛，宜于发作初期用药。"},{"q":"小剂量碘的用途是","o":["黏液性水肿","甲亢","单纯性甲状腺肿","呆小病","甲状腺危象"],"a":2,"e":"小剂量碘为甲状腺合成激素提供原料，纠正碘缺乏所致代偿性增生，用于防治单纯性甲状腺肿。"},{"q":"药物作用的两重性是指药物同时具有","o":["兴奋作用和抑制作用","副作用和毒性反应","治疗作用和不良反应","药物作用和药理效应","选择性和专一性"],"a":2,"e":"药物作用的两重性指药物既可产生防治疾病的治疗作用，又可产生对机体不利的不良反应，二者随剂量和机体状态而转化。"},{"q":"有机磷酸酯类中毒时产生M样症状的原因是","o":["胆碱能神经递质释放减少","胆碱能神经递质释放增加","胆碱能神经递质破坏减慢","药物排泄减慢","M受体的敏感性增加"],"a":2,"e":"有机磷酸酯类抑制胆碱酯酶，使乙酰胆碱不能被水解而大量堆积，过度激动M受体产生M样症状。"},{"q":"甲氨蝶呤引起的贫血宜选用的治疗药物是","o":["硫酸亚铁","叶酸","亚叶酸钙","维生素B12","二氢叶酸"],"a":2,"e":"甲氨蝶呤抑制二氢叶酸还原酶，阻断四氢叶酸生成，其所致贫血与叶酸缺乏有关，须用不经酶还原的亚叶酸钙解救。"},{"q":"能抑制胃酸分泌最后环节的药物是","o":["哌仑西平","奥美拉唑","雷尼替丁","丙谷胺","米索前列醇"],"a":1,"e":"奥美拉唑抑制胃壁细胞H+-K+-ATP酶，阻断胃酸分泌的最后环节，对基础胃酸及刺激后胃酸分泌均有强抑制作用。"},{"q":"某弱酸性药物，口服可由胃吸收，pKa=5.4，当达平衡时血浆（pH=7.4）药物浓度约是胃中（pH=1.4）药物浓度的","o":["1倍","10倍","100倍","1000倍","10000倍"],"a":2,"e":"弱酸性药物在胃内解离少、易吸收，平衡时两侧分子型浓度相等；血浆pH高，解离型浓度约为胃内100倍，故总浓度比约100倍。"},{"q":"治疗强心苷中毒引起的房室传导阻滞或窦性心动过缓最好选用","o":["异丙肾上腺素","阿托品","苯妥英钠","氨茶碱","麻黄碱"],"a":1,"e":"强心苷中毒所致房室传导阻滞和窦性心动过缓属迷走神经兴奋表现，阿托品阻断M受体、解除迷走抑制，可提高心率、改善传导。"},{"q":"抗菌药物的抗菌范围称为","o":["抗菌谱","抗菌活性","化疗指数","抗生素后效应","首次接触效应"],"a":0,"e":"抗菌谱指抗菌药物抑制或杀灭病原微生物的范围，分窄谱与广谱，是临床选用抗菌药物的重要依据。"},{"q":"下列哪种药物首次服用时，可能引起较严重的体位性低血压","o":["哌唑嗪","可乐定","普萘洛尔","硝苯地平","卡托普利"],"a":0,"e":"哌唑嗪阻断血管α1受体，首次给药后立位血压可明显下降，出现首剂现象，故首剂应减半并睡前服用。"},{"q":"哌替啶中毒时发生的呼吸抑制、昏迷等症状，可注射以下哪种药物解救","o":["美沙酮","纳洛酮","氟马西尼","丁丙诺啡","曲马多"],"a":1,"e":"纳洛酮为阿片受体拮抗药，能迅速对抗哌替啶激动阿片受体所致的呼吸抑制和昏迷，为阿片类中毒的首选解救药。"},{"q":"药物代谢动力学参数不包括","o":["消除速率常数","表观分布容积","半衰期","半数致死量","血浆清除率"],"a":3,"e":"半数致死量反映药物毒性大小，属安全性指标而非药动学参数；消除速率常数、表观分布容积、半衰期、清除率均为药动学参数。"},{"q":"下列不属于吗啡禁忌证的是","o":["哺乳期妇女止痛","肺源性心脏病","支气管哮喘","颅内压增高","血压正常的心肌梗死患者"],"a":4,"e":"吗啡禁用于支气管哮喘、肺源性心脏病、颅内压增高、哺乳期妇女及分娩止痛；血压正常的心肌梗死患者可用吗啡镇痛镇静。"},{"q":"糖皮质激素隔日疗法的给药时间是","o":["隔日早上","隔日中午","隔日下午","隔日晚上","隔日午夜"],"a":0,"e":"糖皮质激素分泌呈晨高夜低节律，隔日疗法将两日总量于隔日清晨一次顿服，对下丘脑-垂体-肾上腺轴的抑制最轻。"},{"q":"不具有抗铜绿假单胞菌的抗生素是","o":["头孢呋辛","羧苄西林","头孢哌酮","庆大霉素","头孢他啶"],"a":0,"e":"头孢呋辛为第二代头孢菌素，对铜绿假单胞菌无效；羧苄西林、头孢哌酮、头孢他啶和庆大霉素均有抗铜绿假单胞菌作用。"},{"q":"抗着床的避孕药是","o":["复方氯地孕酮","大剂量雌激素","炔雌醇","大剂量甲地孕酮","炔雌醚"],"a":3,"e":"大剂量甲地孕酮为孕激素制剂，使子宫内膜呈分泌期改变而不利于孕卵着床，作为探亲避孕药用于抗着床。"},{"q":"一个效能和效价强度均高的激动剂应该是","o":["亲和力高，内在活性低","亲和力低，内在活性较弱","亲和力低，内在活性低","亲和力低，内在活性高","亲和力高，内在活性高"],"a":4,"e":"激动剂的效应取决于亲和力与内在活性，效能与内在活性成正比，效价强度与二者均有关，两者皆高者为完全激动药。"},{"q":"香豆素类药物抗凝作用的机制是","o":["妨碍肝脏合成凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ","耗竭体内凝血因子","激活血浆中抗凝血酶Ⅲ","抑制纤溶酶原变为纤溶酶","抑制凝血酶原转变为凝血酶"],"a":0,"e":"香豆素类竞争性抑制维生素K环氧化物还原酶，妨碍肝脏合成凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ，从而产生抗凝作用。"},{"q":"卡托普利的降压作用主要通过下列哪项产生","o":["利尿降压","血管扩张","钙拮抗","ACE抑制","α受体阻断"],"a":3,"e":"卡托普利抑制血管紧张素转化酶，使血管紧张素Ⅱ生成减少、缓激肽降解减少，血管舒张而血压下降。"},{"q":"地高辛不良反应的叙述，下列哪项是错误的","o":["胃肠道反应","外周神经炎","黄视、绿视","各种心律失常","中枢神经系统"],"a":1,"e":"地高辛中毒可致胃肠道反应、黄视绿视等视觉障碍、中枢神经症状及各种心律失常；外周神经炎不是其典型不良反应。"},{"q":"红霉素、克林霉素合用可","o":["扩大抗菌谱","由于竞争结合部位产生拮抗作用","增强抗菌活性","降低毒性","增加毒性"],"a":1,"e":"红霉素与克林霉素均作用于细菌核糖体50S亚基，合用相互竞争结合部位而产生拮抗作用，不宜联用。"},{"q":"某哮喘患者，遵医嘱使用糖皮质激素类药治疗哮喘的药理作用的是","o":["降低支气管平滑肌对儿茶酚胺的敏感性","抗炎作用","直接松弛支气管平滑肌","增强气道纤毛的清除功能","呼吸兴奋作用"],"a":1,"e":"糖皮质激素抑制炎症介质生成、减少渗出和毛细血管增生，发挥强大抗炎作用，从而减轻哮喘气道炎症。"},{"q":"阻止病毒穿入宿主细胞、抑制其脱壳而抗病毒的药物是","o":["金刚烷胺","阿昔洛韦","利巴韦林","碘苷","吗啉胍"],"a":0,"e":"金刚烷胺阻止病毒穿入宿主细胞并抑制其脱壳，还能促进多巴胺释放，用于甲型流感防治及帕金森病。"},{"q":"丙磺舒可在肾小管主动分泌，其主动转运跨膜时的特点是","o":["需要载体，耗能，有饱和性和竞争性","不需要载体，不耗能，无饱和性和竞争性","需要载体，耗能，无饱和性和竞争性","不需要载体，不耗能，有饱和性和竞争性","需要载体，不耗能，无饱和性和竞争性"],"a":0,"e":"主动转运逆浓度差进行，需膜上载体并消耗能量，载体数量有限故有饱和现象，结构相似药物间存在竞争性抑制。"},{"q":"伴窦性心动过缓的高血压不宜用","o":["普萘洛尔","硝普钠","氢氯噻嗪","肼屈嗪","硝酸甘油"],"a":0,"e":"普萘洛尔阻断β受体，抑制窦房结自律性、减慢心率，可加重窦性心动过缓甚至致房室传导阻滞，故不宜使用。"},{"q":"强心苷中毒引起的传导阻滞可选用的治疗药物是","o":["氯化钾","肾上腺素","阿托品","氨茶碱","苯妥英钠"],"a":2,"e":"强心苷中毒所致传导阻滞由迷走神经张力过高引起，阿托品阻断M受体可解除迷走抑制、加快房室传导；苯妥英钠用于室性心律失常。"},{"q":"有关氧化亚氮的理化性质，正确的是","o":["有色无味液态气体","对呼吸道有刺激","易燃烧，且与可燃性全麻药混合时有助燃性","脂溶性低，血/气分配系数为0.47","性质不稳定"],"a":3,"e":"氧化亚氮为无色无味气体，脂溶性低、血/气分配系数0.47，麻醉诱导快，无刺激性、不燃不爆且性质稳定。"},{"q":"链激酶引起的出血宜选用哪种药物进行治疗","o":["维生素K","氨甲苯酸","去甲肾上腺素","维生素C","维生素B12"],"a":1,"e":"链激酶激活纤溶酶原使纤溶亢进引起出血，氨甲苯酸抑制纤溶酶原激活而止血；维生素K对纤溶亢进所致出血无效。"},{"q":"毒蕈碱的中毒症状不包括","o":["恶心呕吐","头痛、眼痛、视物模糊","腹痛、腹泻","心率过快、血压上升","流涎、呼吸困难"],"a":3,"e":"毒蕈碱激动M受体，引起恶心呕吐、腹痛腹泻、流涎、出汗、视物模糊及支气管痉挛，心率减慢、血压下降而非升高。"},{"q":"强心苷主要用于治疗","o":["充血性心力衰竭","心肌炎","心室纤颤","甲亢性心脏病","室性心律失常"],"a":0,"e":"强心苷增强心肌收缩力、减慢心率，主要用于充血性心力衰竭，也可用于心房颤动和心房扑动。"},{"q":"呋塞米的不良反应不包括","o":["胃肠道反应","电解质紊乱（低钾等）","恶心、呕吐","耳毒性","坏死性胰腺炎"],"a":4,"e":"呋塞米可致低钾、低钠等电解质紊乱，引起恶心呕吐等胃肠道反应及耳毒性；坏死性胰腺炎不是其不良反应。"},{"q":"双膦酸盐类治疗骨质疏松的机制是","o":["只能被破骨细胞摄取","抑制破骨细胞的凋亡","促进法尼基焦磷酸合酶的活性","抑制破骨细胞的活性","促进小分子GTP酶的异戊烯化"],"a":3,"e":"双膦酸盐与骨羟磷灰石结合，被破骨细胞摄取后抑制其活性并促进其凋亡，减少骨吸收，用于骨质疏松。"},{"q":"具有M1受体阻断作用的抗消化性溃疡药是","o":["奥美拉唑","苯海拉明","阿托品","哌仑西平","雷尼替丁"],"a":3,"e":"哌仑西平选择性阻断胃壁细胞M1受体，减少胃酸分泌而治疗消化性溃疡，其扩瞳、口干等反应较阿托品轻。"},{"q":"强心苷治疗心衰的直接作用是","o":["缩小已扩大的心室容积","减慢心率","增强心肌收缩力","降低心室壁张力","增加冠脉血供"],"a":2,"e":"强心苷直接抑制心肌细胞膜Na+-K+-ATP酶，使细胞内钙增多，增强心肌收缩力，为其治疗心力衰竭的基本作用。"},{"q":"下列药物属于钾通道开放药的是","o":["硝苯地平","维拉帕米","普罗帕酮","米诺地尔","苯妥英钠"],"a":3,"e":"米诺地尔开放血管平滑肌ATP敏感钾通道，使细胞膜超极化、钙内流减少，血管舒张而降压。"},{"q":"静脉注射2g磺胺药，其血药浓度为10mg/L，经计算其表观分布容积为","o":["0.05L","2L","5L","20L","200L"],"a":4,"e":"表观分布容积等于剂量除以血药浓度，即2000mg除以10mg/L为200L，提示药物在组织分布广泛。"},{"q":"下列药物哪种是中枢多巴胺受体拮抗药","o":["阿托品","安定","尼可刹米","氯丙嗪","哌替啶"],"a":3,"e":"氯丙嗪阻断中脑-皮质和中脑-边缘系统D2受体，产生抗精神病作用，为吩噻嗪类中枢多巴胺受体拮抗药。"},{"q":"药物的化疗指数是指","o":["ED95/LD5","LD95/ED5","LD50/ED50","LD50＝ED50","ED5＝LD95"],"a":2,"e":"化疗指数为动物半数致死量与半数有效量的比值，即LD50/ED50，比值越大疗效越高、毒性越低。"},{"q":"对H2受体具有阻断作用的药物","o":["哌仑西平","雷尼替丁","丙谷胺","甲硝唑","苯海拉明"],"a":1,"e":"雷尼替丁选择性阻断胃壁细胞H2受体，抑制胃酸分泌，用于消化性溃疡；苯海拉明则为H1受体阻断药。"}];
